function isD1DatabaseBinding(value) {
    try {
        return !!value && (typeof value === "object" || typeof value === "function") && typeof value.prepare === "function" && typeof value.batch === "function";
    } catch (e) {
        return false;
    }
}

function findD1RuntimeBinding(env) {
    const source = env || {};
    const preferred = [ "DB", "D1", "DATABASE", "NEXA_DB", "PANEL_DB" ];
    for (const name of preferred) {
        try {
            const value = source[name];
            if (value != null && (typeof value === "object" || typeof value === "function")) {
                return {
                    name: name,
                    value: value
                };
            }
        } catch (e) {}
    }
    const reserved = new Set([ "ASSETS", "AI", "BROWSER" ]);
    for (const name of listRuntimeBindingNames(source)) {
        if (reserved.has(name) || /^CF_PAGES(?:_|$)/.test(name) || /^__NEXA_/.test(name)) continue;
        try {
            if (isD1DatabaseBinding(source[name])) return {
                name: name,
                value: source[name]
            };
        } catch (e) {}
    }
    return null;
}

function listRuntimeBindingNames(env) {
    const names = new Set;
    let current = env || {};
    for (let depth = 0; current && depth < 2; depth++) {
        try {
            for (const name of Object.keys(current)) names.add(name);
        } catch (e) {}
        try {
            current = Object.getPrototypeOf(current);
        } catch (e) {
            break;
        }
    }
    return [ ...names ];
}

function findRuntimeBinding(env, preferredNames, predicate) {
    const source = env || {};
    for (const name of preferredNames || []) {
        try {
            if (source[name] != null && (!predicate || predicate(source[name]))) {
                return {
                    name: name,
                    value: source[name]
                };
            }
        } catch (e) {}
    }
    if (predicate) {
        for (const name of listRuntimeBindingNames(source)) {
            try {
                if (predicate(source[name])) return {
                    name: name,
                    value: source[name]
                };
            } catch (e) {}
        }
    }
    return null;
}

function firstNonEmptyEnvValue(env, names) {
    for (const name of names || []) {
        try {
            const value = env?.[name];
            if (value != null && String(value).trim()) return {
                name: name,
                value: value
            };
        } catch (e) {}
    }
    return null;
}

function inferPagesProjectName(env, request) {
    const explicit = firstNonEmptyEnvValue(env, [ "PAGES_PROJECT_NAME", "CF_PAGES_PROJECT_NAME", "CLOUDFLARE_PAGES_PROJECT_NAME" ]);
    if (explicit) return String(explicit.value).trim();
    const urls = [];
    try {
        if (env?.CF_PAGES_URL) urls.push(String(env.CF_PAGES_URL));
    } catch (e) {}
    try {
        if (request?.url) urls.push(String(request.url));
    } catch (e) {}
    for (const raw of urls) {
        try {
            const hostname = new URL(raw).hostname.toLowerCase();
            if (!hostname.endsWith(".pages.dev")) continue;
            const prefix = hostname.slice(0, -".pages.dev".length);
            const labels = prefix.split(".").filter(Boolean);
            if (labels.length) return labels[labels.length - 1];
        } catch (e) {}
    }
    return "";
}

function detectCloudflareRuntime(env, request) {
    const source = env || {};
    let hostname = "";
    try {
        hostname = new URL(request?.url || source.CF_PAGES_URL || "https://invalid.local").hostname.toLowerCase();
    } catch (e) {}
    const forced = String(source.NEXA_RUNTIME || source.RUNTIME_TYPE || "").trim().toLowerCase();
    const pagesProjectName = inferPagesProjectName(source, request);
    const pagesSignal = forced === "pages" || source.CF_PAGES === "1" || source.CF_PAGES === 1 || source.CF_PAGES === true || !!source.CF_PAGES_BRANCH || !!source.CF_PAGES_URL || !!pagesProjectName || hostname.endsWith(".pages.dev");
    let environment = String(source.PAGES_ENVIRONMENT || source.CF_PAGES_ENVIRONMENT || "").trim().toLowerCase();
    if (environment !== "preview" && environment !== "production") {
        environment = "production";
        if (hostname.endsWith(".pages.dev")) {
            const prefix = hostname.slice(0, -".pages.dev".length);
            if (prefix.split(".").filter(Boolean).length > 1) environment = "preview";
        }
    }
    let workerName = String(source.WORKER_NAME || "").trim();
    if (!workerName && hostname.endsWith(".workers.dev")) workerName = hostname.split(".")[0] || "";
    return {
        type: pagesSignal ? "pages" : "worker",
        projectName: pagesProjectName,
        workerName: workerName,
        environment: environment
    };
}

function normalizeRuntimeEnv(rawEnv, request) {
    const source = rawEnv || {};
    try {
        if (source.__NEXA_NORMALIZED_ENV) return source;
    } catch (e) {}
    const normalized = Object.create(source);
    const define = (name, value) => {
        try {
            Object.defineProperty(normalized, name, {
                value: value,
                enumerable: true,
                configurable: true
            });
        } catch (e) {}
    };
    const d1 = findD1RuntimeBinding(source);
    if (d1) {
        define("DB", d1.value);
        define("__NEXA_DB_BINDING_NAME", d1.name);
    }
    const aliases = {
        ADMIN: [ "ADMIN", "PANEL_PASSWORD", "NEXA_ADMIN" ],
        CF_API_TOKEN: [ "CF_API_TOKEN", "CF_API_TOKEN", "CLOUDFLARE_API_TOKEN" ],
        CF_AC_ID: [ "CF_AC_ID", "CF_ACCOUNT_ID", "CLOUDFLARE_ACCOUNT_ID" ],
        WORKER_NAME: [ "WORKER_NAME", "CF_WORKER_NAME" ],
        PAGES_PROJECT_NAME: [ "PAGES_PROJECT_NAME", "CF_PAGES_PROJECT_NAME", "CLOUDFLARE_PAGES_PROJECT_NAME" ]
    };
    for (const [canonical, names] of Object.entries(aliases)) {
        const found = firstNonEmptyEnvValue(source, names);
        if (found) define(canonical, found.value);
    }
    define("__NEXA_RUNTIME_INFO", detectCloudflareRuntime(normalized, request));
    define("__NEXA_NORMALIZED_ENV", true);
    return normalized;
}

function normalizeExecutionContext(ctx) {
    return {
        waitUntil(promise) {
            safeWaitUntil(ctx, promise);
        },
        passThroughOnException() {
            try {
                if (ctx && typeof ctx.passThroughOnException === "function") ctx.passThroughOnException();
            } catch (e) {}
        }
    };
}

/* ====================================================================== */
/*  دروازه‌ی راه‌اندازی اجباری (Setup gate)                                 */
/*  ---------------------------------------------------------------------  */
/*  تا وقتی رمز عبور پنل تنظیم نشده باشد، کاربر به هیچ صفحه‌ای راه ندارد    */
/*  و مستقیماً به /setup هدایت می‌شود.                                      */
/*                                                                        */
/*  محل ذخیره‌ی رمز: D1 → جدول settings → کلید ADMIN → هش SHA-256.          */
/*  این مسیر کاملاً محلی است: هیچ فراخوانی به api.cloudflare.com، هیچ        */
/*  secret-writing و هیچ redeploy وجود ندارد؛ بنابراین عامل اصلی کرش        */
/*  (خطای 1101) در مرحله راه‌اندازی حذف می‌شود.                              */
/*  اگر متغیر ADMIN را دستی در ورکر ست کرده باشید، همان هم معتبر است.       */
/* ====================================================================== */
async function hasPanelPasswordSet(env) {
    try {
        return !!(await DbService.getPanelPassword(env));
    } catch (e) {
        return false;
    }
}

async function shouldForceSetup(env) {
    return !(await hasPanelPasswordSet(env));
}

function buildSetupRedirectResponse(request) {
    let target = "/setup";
    try {
        target = new URL("/setup", request.url).href;
    } catch (e) {}
    return new Response(null, {
        status: 302,
        headers: {
            Location: target,
            "Cache-Control": "no-store, no-cache, must-revalidate"
        }
    });
}

