const proxyFailPenalty = new Map;

function fnv1a32(str) {
    let h = 2166136261 >>> 0;
    const s = String(str || "");
    for (let i = 0; i < s.length; i++) {
        h ^= s.charCodeAt(i);
        h = Math.imul(h, 16777619) >>> 0;
    }
    return h >>> 0;
}

function isCloudflareIPv6(value) {
    const ip = String(value || "").toLowerCase().replace(/^\[|\]$/g, "");
    if (!ip.includes(":")) return false;
    return CF_IPv6_PREFIXES.some(p => ip.startsWith(p));
}

function isCloudflareIP(value) {
    return isCloudflareIPv4(value) || isCloudflareIPv6(value);
}

function proxyPenalize(addr, port) {
    const key = addr + ":" + port;
    const prev = proxyFailPenalty.get(key) || {
        fails: 0,
        until: 0
    };
    proxyFailPenalty.set(key, {
        fails: prev.fails + 1,
        until: Date.now() + PROXY_FAIL_PENALTY_MS
    });
    if (proxyFailPenalty.size > 256) {
        const nowMs = Date.now();
        for (const [k, v] of proxyFailPenalty) {
            if (v.until <= nowMs) proxyFailPenalty.delete(k);
        }
    }
}

function proxyClearPenalty(addr, port) {
    proxyFailPenalty.delete(addr + ":" + port);
}

function proxyIsPenalized(addr, port) {
    const v = proxyFailPenalty.get(addr + ":" + port);
    if (!v) return false;
    if (v.until <= Date.now()) {
        proxyFailPenalty.delete(addr + ":" + port);
        return false;
    }
    return true;
}

