function withTimeout(promise, ms, fallback) {
    let timer = null;
    const guard = new Promise(function(resolve) {
        timer = setTimeout(function() {
            resolve(fallback);
        }, ms);
    });
    /* [FINAL] rejectionPromise دیگر هرگز unhandled نمی‌ماند: اگر promise وسط
       کار شکست بخورد، به‌جای فرار کردن استثنا (→ خطای 1101 روی Cloudflare)
       همان fallback برمی‌گردد. */
    const safePromise = Promise.resolve(promise).catch(function() {
        return fallback;
    });
    return Promise.race([ safePromise, guard ]).finally(function() {
        if (timer) clearTimeout(timer);
    });
}

async function fetchWithTimeout(url, options, timeoutMs) {
    const controller = new AbortController;
    const timer = setTimeout(function() {
        controller.abort();
    }, timeoutMs || API_FETCH_TIMEOUT_MS);
    try {
        const opts = Object.assign({}, options || {});
        const headers = new Headers(opts.headers || {});
        if (!headers.has("User-Agent")) headers.set("User-Agent", NEXA_USER_AGENT);
        if (!headers.has("Accept")) headers.set("Accept", "*/*");
        opts.headers = headers;
        return await fetch(url, Object.assign(opts, {
            signal: controller.signal
        }));
    } finally {
        clearTimeout(timer);
    }
}

