const DomainBlockService = {
    normalizeDomain(value) {
        let d = String(value || "").trim().toLowerCase();
        d = d.replace(/^https?:\/\//, "");
        d = d.replace(/\/.*$/, "");
        d = d.replace(/:\d+$/, "");
        d = d.replace(/^www\./, "");
        d = d.replace(/^\*\./, "");
        return d;
    },
    parseList(value) {
        return CdnProxyService.parseList(value).map(v => this.normalizeDomain(v)).filter(Boolean);
    },
    isBlocked(target, blocklist) {
        if (!target || !blocklist?.length) return false;
        if (isIPv4(target)) return false;
        const host = this.normalizeDomain(target);
        if (!host || !host.includes(".")) return false;
        for (const entry of blocklist) {
            const blocked = this.normalizeDomain(entry);
            if (!blocked) continue;
            if (host === blocked || host.endsWith("." + blocked)) return true;
        }
        return false;
    },
    invalidateCache() {
        blockedDomainsCache = {
            enabled: false,
            domains: [],
            fetchedAt: 0
        };
    },
    async getSettings(env) {
        const now = Date.now();
        if (blockedDomainsCache.fetchedAt && now - blockedDomainsCache.fetchedAt < BLOCKED_DOMAINS_CACHE_TTL) {
            return blockedDomainsCache;
        }
        const settings = {
            enabled: false,
            domains: [],
            fetchedAt: now
        };
        try {
            const {results: results} = await env.DB.prepare("SELECT key, value FROM settings WHERE key IN ('blocked_domains', 'blocked_domains_enabled')").all();
            for (const row of results || []) {
                if (row.key === "blocked_domains_enabled") {
                    settings.enabled = row.value === "1" || row.value === "true";
                } else if (row.key === "blocked_domains") {
                    settings.domains = this.parseList(row.value);
                }
            }
        } catch (e) {}
        blockedDomainsCache = settings;
        return settings;
    },
    async saveSettings(env, data) {
        if (data.enabled !== undefined) {
            await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('blocked_domains_enabled', ?)").bind(data.enabled ? "1" : "0").run();
        }
        if (data.domains !== undefined) {
            const list = this.parseList(data.domains);
            await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('blocked_domains', ?)").bind(list.join("\n")).run();
        }
        this.invalidateCache();
    }
};

function isIranDomain(hostname) {
    const host = DomainBlockService.normalizeDomain(hostname);
    return !!host && (host === "ir" || host.endsWith(".ir"));
}

const ContentPolicyService = {
    async getSettings(env) {
        const now = Date.now();
        if (contentPolicyCache.data && now - contentPolicyCache.fetchedAt < CONTENT_POLICY_CACHE_TTL_MS) {
            return contentPolicyCache.data;
        }
        const result = {
            adultBlockEnabled: false
        };
        try {
            const {results: results} = await env.DB.prepare("SELECT key, value FROM settings WHERE key IN ('adult_block_enabled')").all();
            for (const row of results || []) {
                if (row.key === "adult_block_enabled") result.adultBlockEnabled = row.value === "1";
            }
        } catch (e) {}
        contentPolicyCache = {
            data: result,
            fetchedAt: now
        };
        return result;
    },
    async saveSettings(env, data) {
        await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)").bind("adult_block_enabled", data.adultBlockEnabled ? "1" : "0").run();
        contentPolicyCache = {
            data: {
                adultBlockEnabled: !!data.adultBlockEnabled
            },
            fetchedAt: Date.now()
        };
    },
    async getAdultBlocklist() {
        const now = Date.now();
        if (adultBlocklistCache.domains.length && now - adultBlocklistCache.fetchedAt < ADULT_BLOCKLIST_CACHE_TTL) {
            return adultBlocklistCache.domains;
        }
        try {
            const res = await fetchWithTimeout(ADULT_BLOCKLIST_URL, {
                headers: {
                    "User-Agent": NEXA_USER_AGENT,
                    Accept: "text/plain, */*"
                }
            }, MANIFEST_FETCH_TIMEOUT_MS);
            if (!res.ok) throw new Error("fetch failed");
            const text = await res.text();
            const domains = text.split("\n").map(l => l.trim()).filter(l => l && !l.startsWith("#")).map(l => l.replace(/^0\.0\.0\.0\s+/, "").replace(/^127\.0\.0\.1\s+/, "").trim()).filter(Boolean);
            adultBlocklistCache = {
                domains: domains,
                fetchedAt: now
            };
            return domains;
        } catch (e) {
            return adultBlocklistCache.domains;
        }
    },
    async checkBlocked(env, hostname) {
        if (!hostname || isIPv4(hostname)) return {
            blocked: false
        };
        const settings = await this.getSettings(env);
        if (settings.adultBlockEnabled) {
            const list = await this.getAdultBlocklist();
            if (DomainBlockService.isBlocked(hostname, list)) {
                return {
                    blocked: true,
                    reason: "محتوای بزرگسال"
                };
            }
        }
        return {
            blocked: false
        };
    }
};

const BACKUP_EXCLUDED_SETTINGS = [ "panel_password", "ADMIN" ];

const BACKUP_VERSION = 2;

const BackupService = {
    async build(env) {
        try {
            await flushExpiredTraffic(env);
            await purgeExpiredUsers(env);
        } catch (e) {}
        const {results: users} = await env.DB.prepare("SELECT * FROM users ORDER BY id ASC").all();
        const {results: settingsRows} = await env.DB.prepare("SELECT key, value FROM settings").all();
        const settings = {};
        (settingsRows || []).forEach(row => {
            if (!BACKUP_EXCLUDED_SETTINGS.includes(row.key)) settings[row.key] = row.value;
        });
        let panel_logs = [];
        try {
            const {results: pl} = await env.DB.prepare("SELECT * FROM panel_logs ORDER BY id ASC").all();
            panel_logs = pl || [];
        } catch (e) {}
        return {
            version: BACKUP_VERSION,
            exported_at: (new Date).toISOString(),
            users: users || [],
            settings: settings,
            panel_logs: panel_logs,
            meta: {
                users_count: (users || []).length,
                settings_count: Object.keys(settings).length,
                panel_logs_count: panel_logs.length
            }
        };
    },
    async restore(env, body) {
        if (!body || !Array.isArray(body.users)) {
            throw new Error("فرمت بکاپ نامعتبر است — لیست کاربران یافت نشد");
        }
        try {
            await flushExpiredTraffic(env);
        } catch (e) {}
        await env.DB.prepare("DELETE FROM users").run();
        for (const user of body.users) {
            await env.DB.prepare("INSERT INTO users (username, uuid, limit_gb, expiry_days, ips, connection_type, tls, port, used_gb, is_active, last_active, created_at, fingerprint, max_requests, max_requests_daily, used_requests, used_requests_today, req_last_date, proxy_ip, is_saved, expired_at, status_slug, is_system) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(user.username, user.uuid, user.limit_gb != null ? parseFloat(user.limit_gb) : null, user.expiry_days != null ? parseInt(user.expiry_days) : null, user.ips || null, user.connection_type || atob("dmxlc3M="), user.tls || null, user.port || null, user.used_gb != null ? parseFloat(user.used_gb) : 0, user.is_active != null ? parseInt(user.is_active) : 1, user.last_active || null, user.created_at || null, user.fingerprint || "random", user.max_requests != null ? parseInt(user.max_requests) : user.max_connections != null ? parseInt(user.max_connections) : null, user.max_requests_daily != null ? parseInt(user.max_requests_daily) : null, user.used_requests != null ? parseInt(user.used_requests) : 0, user.used_requests_today != null ? parseInt(user.used_requests_today) : 0, user.req_last_date || null, user.proxy_ip || null, user.is_saved != null ? parseInt(user.is_saved) : 0, user.expired_at || null, user.status_slug || user.username || null, user.is_system != null ? parseInt(user.is_system) : 0).run();
        }
        await ensureSystemUser(env.DB);
        if (body.settings && typeof body.settings === "object") {
            await env.DB.prepare("DELETE FROM settings").run();
            for (const [key, value] of Object.entries(body.settings)) {
                if (BACKUP_EXCLUDED_SETTINGS.includes(key) || value == null) continue;
                await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)").bind(key, String(value)).run();
            }
        }
        if (Array.isArray(body.panel_logs) && body.panel_logs.length) {
            try {
                await env.DB.prepare("DELETE FROM panel_logs").run();
                for (const log of body.panel_logs) {
                    await env.DB.prepare("INSERT INTO panel_logs (action, details, ip, created_at) VALUES (?, ?, ?, ?)").bind(log.action || "", log.details || "", log.ip || "", log.created_at || (new Date).toISOString()).run();
                }
            } catch (e) {}
        }
        return {
            users_count: body.users.length
        };
    }
};

const TG_VERIFY_REASONS = {
    disabled: [ "اعلان تلگرام خاموش است — برای تغییر آدرس پنل باید اعلان تلگرام روشن باشد", "Telegram notifications are off — turn them on before changing the panel address" ],
    no_token: [ "توکن ربات تلگرام تنظیم نشده است — اول توکن ربات را ذخیره کن", "The Telegram bot token is not set — save it first" ],
    no_chat: [ "شناسه چت/کاربر تلگرام تنظیم نشده است — اول شناسه چت را ذخیره کن", "No Telegram chat id is set — save one first" ],
    bad_token: [ "توکن ربات تلگرام معتبر نیست (پاسخ تلگرام: {err})", "The Telegram bot token is not valid (Telegram says: {err})" ],
    webhook_missing: [ "وب‌هوک ربات تلگرام تنظیم نشده است — تنظیمات تلگرام را ذخیره کنید تا وب‌هوک خودکار تنظیم شود", "The bot webhook is not set — save the Telegram settings to configure it automatically" ],
    webhook_error: [ "وب‌هوک ربات تلگرام خطا دارد: {err}", "The bot webhook reports an error: {err}" ],
    send_failed: [ "ارسال پیام به تلگرام ناموفق بود: {err}", "Sending a Telegram message failed: {err}" ],
    http_error: [ "ارتباط با تلگرام برقرار نشد: {err}", "Could not reach Telegram: {err}" ],
    unknown: [ "وضعیت اعلان تلگرام نامشخص است", "The Telegram notification status is unknown" ]
};

const TelegramNotifyService = {
    async getSettings(env) {
        const settings = {
            enabled: false,
            bot_token: "",
            chat_ids: ""
        };
        try {
            const {results: results} = await env.DB.prepare("SELECT key, value FROM settings WHERE key IN ('tg_notify_enabled', 'tg_bot_token', 'tg_chat_ids')").all();
            for (const row of results || []) {
                if (row.key === "tg_notify_enabled") settings.enabled = row.value === "1" || row.value === "true";
                if (row.key === "tg_bot_token") settings.bot_token = row.value || "";
                if (row.key === "tg_chat_ids") settings.chat_ids = row.value || "";
            }
        } catch (e) {}
        return settings;
    },
    async saveSettings(env, data) {
        const enabled = data.enabled ? "1" : "0";
        const token = String(data.bot_token || "").trim();
        const chatIds = String(data.chat_ids || "").trim();
        await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('tg_notify_enabled', ?)").bind(enabled).run();
        await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('tg_bot_token', ?)").bind(token).run();
        await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('tg_chat_ids', ?)").bind(chatIds).run();
    },
    parseChatIds(raw) {
        return String(raw || "").split(/[\n,،]+/).map(s => s.trim()).filter(Boolean);
    },
    escapeHtml(text) {
        return String(text || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    },
    async sendIfEnabled(env, action, details, ip) {
        try {
            const settings = await this.getSettings(env);
            if (!settings.enabled || !settings.bot_token) return;
            const chatIds = this.parseChatIds(settings.chat_ids);
            if (!chatIds.length) return;
            const lines = [ "📋 Nexa Panel Log", "🔹 " + action ];
            if (details) lines.push("📝 " + details);
            if (ip) lines.push("🌐 IP: " + ip);
            lines.push("🕐 " + (new Date).toISOString());
            const body = lines.map(l => this.escapeHtml(l)).join("\n");
            const text = body;
            await Promise.all(chatIds.map(chatId => fetch("https://api.telegram.org/bot" + settings.bot_token + "/sendMessage", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    chat_id: chatId,
                    text: text,
                    parse_mode: "HTML",
                    disable_web_page_preview: true
                })
            }).catch(() => {})));
        } catch (e) {}
    },
    async apiCall(env, settings, method, payload, timeoutMs) {
        const token = settings && settings.bot_token;
        if (!token) return {
            ok: false,
            reason: "no_token"
        };
        const controller = typeof AbortController === "function" ? new AbortController : null;
        const timer = controller ? setTimeout(function() {
            controller.abort();
        }, timeoutMs || 6e3) : null;
        try {
            const res = await fetch("https://api.telegram.org/bot" + token + "/" + method, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify(payload || {}),
                signal: controller ? controller.signal : undefined
            });
            const data = await res.json().catch(function() {
                return {};
            });
            return {
                ok: !!(res.ok && data && data.ok),
                status: res.status,
                data: data
            };
        } catch (e) {
            return {
                ok: false,
                reason: "http_error",
                error: String(e && e.message || e)
            };
        } finally {
            if (timer) clearTimeout(timer);
        }
    },
    async getMeta(env) {
        const meta = {
            webhook_url: "",
            webhook_last_seen: "",
            webhook_secret: ""
        };
        try {
            const {results: results} = await env.DB.prepare("SELECT key, value FROM settings WHERE key IN ('tg_webhook_url', 'tg_webhook_last_seen', 'tg_webhook_secret')").all();
            for (const row of results || []) {
                if (row.key === "tg_webhook_url") meta.webhook_url = row.value || "";
                if (row.key === "tg_webhook_last_seen") meta.webhook_last_seen = row.value || "";
                if (row.key === "tg_webhook_secret") meta.webhook_secret = row.value || "";
            }
        } catch (e) {}
        return meta;
    },
    async setMeta(env, key, value) {
        try {
            await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)").bind(key, String(value || "")).run();
        } catch (e) {}
    },
    async ensureWebhook(env, origin) {
        const settings = await this.getSettings(env);
        if (!settings.bot_token) return {
            ok: false,
            reason: "no_token"
        };
        const base = String(origin || "").replace(/\/+$/, "");
        if (!/^https:\/\//i.test(base)) return {
            ok: false,
            reason: "http_error",
            error: "origin"
        };
        const wanted = base + "/api/tg-webhook";
        const me = await this.apiCall(env, settings, "getMe", {});
        if (!me.ok) {
            return {
                ok: false,
                reason: me.reason === "http_error" ? "http_error" : "bad_token",
                error: me.data && me.data.description || me.error || "",
                username: ""
            };
        }
        const username = me.data && me.data.result && me.data.result.username || "";
        const info = await this.apiCall(env, settings, "getWebhookInfo", {});
        const infoResult = info.data && info.data.result || {};
        const current = infoResult.url || "";
        if (current === wanted) {
            await this.setMeta(env, "tg_webhook_url", wanted);
            return {
                ok: true,
                url: wanted,
                changed: false,
                external: false,
                username: username,
                error: infoResult.last_error_message || ""
            };
        }
        if (current && current.indexOf(base + "/") !== 0) {
            return {
                ok: true,
                url: current,
                changed: false,
                external: true,
                username: username,
                error: infoResult.last_error_message || ""
            };
        }
        const meta = await this.getMeta(env);
        let secret = meta.webhook_secret;
        if (!secret) {
            secret = (crypto.randomUUID ? crypto.randomUUID() : String(Date.now()) + Math.random().toString(36).slice(2)).replace(/-/g, "");
            await this.setMeta(env, "tg_webhook_secret", secret);
        }
        const set = await this.apiCall(env, settings, "setWebhook", {
            url: wanted,
            allowed_updates: [ "message", "callback_query" ],
            drop_pending_updates: false,
            secret_token: secret
        });
        if (!set.ok) {
            return {
                ok: false,
                reason: "webhook_error",
                error: set.data && set.data.description || set.error || "",
                username: username
            };
        }
        await this.setMeta(env, "tg_webhook_url", wanted);
        return {
            ok: true,
            url: wanted,
            changed: true,
            external: false,
            username: username
        };
    },
    async verifyStatus(env, opts) {
        opts = opts || {};
        const settings = await this.getSettings(env);
        const chatIds = this.parseChatIds(settings.chat_ids);
        const out = {
            ok: false,
            reason: "",
            message: "",
            message_en: "",
            enabled: !!settings.enabled,
            has_token: !!settings.bot_token,
            has_chat: chatIds.length > 0,
            bot_username: "",
            webhook_url: "",
            webhook_error: "",
            webhook_pending: 0,
            webhook_last_seen: "",
            webhook_checked: false,
            delivered: false,
            checked_at: (new Date).toISOString()
        };
        const fail = function(reason, err) {
            const pair = TG_VERIFY_REASONS[reason] || TG_VERIFY_REASONS.unknown;
            out.reason = reason;
            out.message = String(pair[0]).split("{err}").join(err || "");
            out.message_en = String(pair[1]).split("{err}").join(err || "");
            return out;
        };
        const meta = await this.getMeta(env);
        out.webhook_last_seen = meta.webhook_last_seen || "";
        if (!settings.enabled) return fail("disabled");
        if (!settings.bot_token) return fail("no_token");
        if (!chatIds.length) return fail("no_chat");
        if (opts.ensureWebhook && opts.origin) {
            const ensured = await this.ensureWebhook(env, opts.origin);
            out.webhook_ensured = ensured;
            if (!ensured.ok || ensured.external) {
                return fail(ensured.reason || "webhook_missing", ensured.error || "");
            }
        }
        const me = await this.apiCall(env, settings, "getMe", {});
        if (!me.ok) return fail(me.reason === "http_error" ? "http_error" : "bad_token", me.data && me.data.description || me.error || "");
        out.bot_username = me.data && me.data.result && me.data.result.username || "";
        const info = await this.apiCall(env, settings, "getWebhookInfo", {});
        if (!info.ok) {
            return fail(info.reason === "http_error" ? "http_error" : "webhook_error", info.data && info.data.description || info.error || "");
        }
        const res = info.data && info.data.result || {};
        out.webhook_checked = true;
        out.webhook_url = res.url || "";
        out.webhook_error = res.last_error_message || "";
        out.webhook_pending = Number(res.pending_update_count || 0);
        if (!out.webhook_url) return fail("webhook_missing");
        if (opts.origin) {
            const expectedWebhook = String(opts.origin).replace(/\/+$/, "") + "/api/tg-webhook";
            if (out.webhook_url !== expectedWebhook) return fail("webhook_missing");
        }
        if (out.webhook_error) return fail("webhook_error", out.webhook_error);
        if (opts.full) {
            const sent = await this.apiCall(env, settings, "sendMessage", {
                chat_id: chatIds[0],
                text: "✅ تست اتصال پنل Nexa — اعلان‌ها و وب‌هوک درست کار می‌کنند.\n" + (new Date).toISOString(),
                disable_web_page_preview: true
            });
            if (!sent.ok) return fail("send_failed", sent.data && sent.data.description || sent.error || "");
            out.delivered = true;
        }
        out.ok = true;
        return out;
    }
};

const LogService = {
    async addLog(env, action, details = "", ip = "") {
        try {
            await env.DB.prepare("INSERT INTO panel_logs (action, details, ip, created_at) VALUES (?, ?, ?, ?)").bind(action, details, ip || "", (new Date).toISOString()).run();
            await TelegramNotifyService.sendIfEnabled(env, action, details, ip);
        } catch (e) {}
    },
    async getLogs(env, limit = 300) {
        try {
            const {results: results} = await env.DB.prepare("SELECT * FROM panel_logs ORDER BY id DESC LIMIT ?").bind(limit).all();
            return results || [];
        } catch (e) {
            return [];
        }
    },
    async clearLogs(env, ip = "") {
        try {
            await env.DB.prepare("DELETE FROM panel_logs").run();
            await this.addLog(env, "پاک کردن لاگ‌ها", "همه لاگ‌های فعالیت حذف شدند", ip);
        } catch (e) {}
    }
};

let schemaEnsured = false;

let cachedAdminSecret = null;

let cachedPanelPassword = null;

let pendingPasswordOverride = null;

function clearPasswordCache() {
    cachedAdminSecret = null;
    cachedPanelPassword = null;
    pendingPasswordOverride = null;
}

function setPasswordOverride(plainPassword) {
    pendingPasswordOverride = plainPassword ? String(plainPassword) : null;
    cachedAdminSecret = null;
    cachedPanelPassword = null;
}

const DbService = {
    async ensureSchema(db) {
        if (schemaEnsured) return;
        try {
            await db.prepare(`\n        CREATE TABLE IF NOT EXISTS users (\n          id INTEGER PRIMARY KEY AUTOINCREMENT,\n          username TEXT UNIQUE,\n          uuid TEXT,\n          limit_gb REAL,\n          expiry_days INTEGER,\n          ips TEXT,\n          connection_type TEXT,\n          tls TEXT,\n          port INTEGER,\n          used_gb REAL DEFAULT 0,\n          is_active INTEGER DEFAULT 1,\n          last_active INTEGER,\n          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n        )\n      `).run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN is_active INTEGER DEFAULT 1").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN last_active INTEGER").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN fingerprint TEXT DEFAULT 'random'").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN max_connections INTEGER").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN max_requests INTEGER").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN used_requests INTEGER DEFAULT 0").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN req_last_date TEXT").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN max_requests_daily INTEGER").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN used_requests_today INTEGER DEFAULT 0").run();
        } catch (e) {}
        try {
            await db.prepare("UPDATE users SET max_requests = max_connections WHERE max_requests IS NULL AND max_connections IS NOT NULL").run();
        } catch (e) {}
        try {
            const today = (new Date).toISOString().split("T")[0];
            await db.prepare("UPDATE users SET used_requests_today = used_requests, used_requests = used_requests WHERE req_last_date = ? AND used_requests_today IS NULL").bind(today).run();
            await db.prepare("UPDATE users SET used_requests_today = 0 WHERE req_last_date IS NOT NULL AND req_last_date != ? AND (used_requests_today IS NULL OR used_requests_today = 0)").bind(today).run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN proxy_ip TEXT").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN is_saved INTEGER DEFAULT 0").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN expired_at INTEGER").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN status_slug TEXT").run();
        } catch (e) {}
        try {
            await db.prepare("UPDATE users SET status_slug = username WHERE status_slug IS NULL OR status_slug != username").run();
        } catch (e) {}
        try {
            await db.prepare("ALTER TABLE users ADD COLUMN is_system INTEGER DEFAULT 0").run();
        } catch (e) {}
        try {
            await db.prepare("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)").run();
        } catch (e) {}
        try {
            await db.prepare(`\n        CREATE TABLE IF NOT EXISTS panel_logs (\n          id INTEGER PRIMARY KEY AUTOINCREMENT,\n          action TEXT NOT NULL,\n          details TEXT,\n          ip TEXT,\n          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n        )\n      `).run();
        } catch (e) {}
        try {
            await db.prepare("DROP TABLE IF EXISTS " + "connection_" + "logs").run();
        } catch (e) {}
        schemaEnsured = true;
    },
    readCfTokenFromEnv(env) {
        for (const key of [ "CF_API_TOKEN", "CF_API_TOKEN", "CLOUDFLARE_API_TOKEN" ]) {
            try {
                const val = env[key];
                if (val != null && String(val).trim()) return String(val).trim();
            } catch (e) {}
        }
        return "";
    },
    isCfTokenBound(env) {
        return !!this.readCfTokenFromEnv(env);
    },
    async getCfToken(env) {
        const isPages = getRuntimeInfo(env).type === "pages";
        if (isPages && env.DB) {
            try {
                const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'CF_API_TOKEN'").first();
                if (row?.value && String(row.value).trim()) return String(row.value).trim();
            } catch (e) {}
        }
        const fromEnv = this.readCfTokenFromEnv(env);
        if (fromEnv) return fromEnv;
        if (!env.DB) return "";
        try {
            const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'CF_API_TOKEN'").first();
            return row?.value ? String(row.value).trim() : "";
        } catch (e) {
            return "";
        }
    },
    async getCfAccountId(env) {
        const isPages = getRuntimeInfo(env).type === "pages";
        if (isPages && env.DB) {
            try {
                const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'CF_AC_ID'").first();
                if (row?.value && String(row.value).trim()) return String(row.value).trim();
            } catch (e) {}
        }
        const fromEnv = env.CF_AC_ID ? String(env.CF_AC_ID).trim() : "";
        if (fromEnv) return fromEnv;
        if (!env.DB) return "";
        try {
            const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'CF_AC_ID'").first();
            return row?.value ? String(row.value).trim() : "";
        } catch (e) {
            return "";
        }
    },
    async cacheCfAccountId(env, accountId) {
        const id = String(accountId || "").trim();
        if (!id || !env.DB) return;
        await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('CF_AC_ID', ?)").bind(id).run();
    },
    async getCfAccountIdResolved(env, request) {
        const target = getCloudflareApiTarget(env, request);
        if (target.accountId) return target.accountId;
        const stored = await this.getCfAccountId(env);
        const token = await this.getCfToken(env);
        if (!token || !target.name) return stored || "";
        if (stored) {
            try {
                if (await cloudflareTargetExistsInAccount(token, target, stored)) return stored;
            } catch (e) {}
        }
        try {
            const accountId = await resolveCfAccountId(token, target);
            if (accountId) await this.cacheCfAccountId(env, accountId);
            return accountId;
        } catch (e) {
            return stored || "";
        }
    },
    async getPanelPassword(env) {
        if (getRuntimeInfo(env).type === "pages" && env.DB) {
            try {
                const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'ADMIN'").first();
                if (row?.value && String(row.value).trim()) {
                    const storedHash = String(row.value).trim();
                    const cacheKey = "__pages_d1__" + storedHash;
                    if (cachedAdminSecret !== cacheKey || cachedPanelPassword === null) {
                        cachedAdminSecret = cacheKey;
                        cachedPanelPassword = storedHash;
                    }
                    return cachedPanelPassword;
                }
            } catch (e) {}
        }
        if (pendingPasswordOverride) {
            const envAdmin = env.ADMIN ? String(env.ADMIN).trim() : "";
            if (envAdmin && envAdmin === pendingPasswordOverride) {
                pendingPasswordOverride = null;
            } else {
                return await this.sha256(pendingPasswordOverride);
            }
        }
        const adminSecret = env.ADMIN ? String(env.ADMIN).trim() : "";
        if (adminSecret) {
            if (cachedAdminSecret === adminSecret && cachedPanelPassword !== null) {
                return cachedPanelPassword;
            }
            cachedAdminSecret = adminSecret;
            cachedPanelPassword = await this.sha256(adminSecret);
            return cachedPanelPassword;
        }
        if (!env.DB) return null;
        try {
            const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'ADMIN'").first();
            if (!row?.value) return null;
            const storedHash = String(row.value).trim();
            const cacheKey = "__d1__" + storedHash;
            if (cachedAdminSecret === cacheKey && cachedPanelPassword !== null) {
                return cachedPanelPassword;
            }
            cachedAdminSecret = cacheKey;
            cachedPanelPassword = storedHash;
            return storedHash;
        } catch (e) {
            return null;
        }
    },
    async verifyApiAuth(request, env) {
        const storedPasswordHash = await this.getPanelPassword(env);
        if (!storedPasswordHash) return true;
        const cookies = request.headers.get("Cookie") || "";
        const sessionCookie = cookies.split(";").find(c => c.trim().startsWith("panel_session="));
        if (!sessionCookie) return false;
        const sessionToken = sessionCookie.split("=")[1].trim();
        return sessionToken === storedPasswordHash;
    },
    async sha256(message) {
        const msgBuffer = (new TextEncoder).encode(message);
        const hashBuffer = await crypto.subtle.digest("SHA-256", msgBuffer);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        return hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
    }
};

function isSystemUser(user) {
    if (!user) return false;
    return user.is_system === 1 || user.username === SYSTEM_USER_LABEL;
}

/* [FINAL] هر خطایی در ساخت/خواندن کاربر سیستمی (اسکیمای قدیمی D1، قطعی موقت)
   باید به null تبدیل شود، نه به استثنا‌ی فرار‌کرده که کل داشبورد را کرش می‌کند. */
async function ensureSystemUser(db) {
    try {
        return await ensureSystemUserInner(db);
    } catch (e) {
        return null;
    }
}

async function ensureSystemUserInner(db) {
    const now = Date.now();
    if (systemUserCache.user && now - systemUserCache.fetchedAt < SYSTEM_USER_CACHE_TTL_MS) {
        return systemUserCache.user;
    }
    let user = await db.prepare("SELECT * FROM users WHERE is_system = 1 OR username = ? LIMIT 1").bind(SYSTEM_USER_LABEL).first();
    if (user) {
        if (user.is_system !== 1 || user.is_saved !== 1 || user.limit_gb != null || user.expiry_days != null || user.max_requests != null || user.max_requests_daily != null) {
            await db.prepare("UPDATE users SET is_system = 1, is_saved = 1, limit_gb = NULL, expiry_days = NULL, max_requests = NULL, max_requests_daily = NULL WHERE username = ?").bind(user.username).run();
            user = await db.prepare("SELECT * FROM users WHERE username = ?").bind(user.username).first();
        }
        if (user.is_system === 1 && LEGACY_SYSTEM_USER_LABELS.includes(String(user.username || ""))) {
            try {
                const clash = await db.prepare("SELECT username FROM users WHERE username = ? LIMIT 1").bind(SYSTEM_USER_LABEL).first();
                if (!clash) {
                    await db.prepare("UPDATE users SET username = ?, status_slug = ? WHERE username = ?").bind(SYSTEM_USER_LABEL, SYSTEM_USER_LABEL, user.username).run();
                    user = await db.prepare("SELECT * FROM users WHERE username = ?").bind(SYSTEM_USER_LABEL).first();
                }
            } catch (e) {}
        }
        systemUserCache = {
            user: user,
            fetchedAt: now
        };
        return user;
    }
    const uuid = crypto.randomUUID();
    await db.prepare("INSERT INTO users (username, uuid, limit_gb, expiry_days, ips, connection_type, tls, port, fingerprint, max_requests, proxy_ip, is_active, is_saved, is_system) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 1, 1)").bind(SYSTEM_USER_LABEL, uuid, null, null, null, atob("dmxlc3M="), "on", 443, "chrome", null, null).run();
    await StatusUrlService.assignStatusSlug(db, SYSTEM_USER_LABEL);
    user = await db.prepare("SELECT * FROM users WHERE username = ?").bind(SYSTEM_USER_LABEL).first();
    systemUserCache = {
        user: user,
        fetchedAt: now
    };
    return user;
}

async function getWorkerRequestStats(env) {
    let cfReqs = {
        today: 0,
        total: 0,
        pending: pendingRequestCount
    };
    try {
        const liveCf = await getCfUsage(env);
        const todayStr = (new Date).toISOString().split("T")[0];
        const dateRow = await env.DB.prepare("SELECT value FROM settings WHERE key = 'req_last_date'").first();
        const totalRow = await env.DB.prepare("SELECT value FROM settings WHERE key = 'req_total'").first();
        let dbTotal = totalRow ? parseInt(totalRow.value) || 0 : 0;
        let dbToday = 0;
        if (dateRow && dateRow.value === todayStr) {
            const todayRow = await env.DB.prepare("SELECT value FROM settings WHERE key = 'req_today'").first();
            dbToday = todayRow ? parseInt(todayRow.value) || 0 : 0;
        }
        if (liveCf.today > dbToday) {
            dbToday = liveCf.today;
            await env.DB.prepare("INSERT INTO settings (key, value) VALUES ('req_today', ?) ON CONFLICT(key) DO UPDATE SET value = ?").bind(String(dbToday), String(dbToday)).run();
            await env.DB.prepare("INSERT INTO settings (key, value) VALUES ('req_last_date', ?) ON CONFLICT(key) DO UPDATE SET value = ?").bind(todayStr, todayStr).run();
        }
        if (liveCf.total > dbTotal) {
            dbTotal = liveCf.total;
            await env.DB.prepare("INSERT INTO settings (key, value) VALUES ('req_total', ?) ON CONFLICT(key) DO UPDATE SET value = ?").bind(String(dbTotal), String(dbTotal)).run();
        }
        cfReqs.today = dbToday + pendingRequestCount;
        cfReqs.total = dbTotal + pendingRequestCount;
    } catch (e) {}
    return cfReqs;
}

function getCloudflareApiTarget(env, request) {
    const info = getRuntimeInfo(env, request);
    const accountId = String(info.accountId || "").trim();
    if (info.type === "pages") {
        return {
            type: "pages",
            name: info.projectName || String(env?.PAGES_PROJECT_NAME || "").trim(),
            environment: info.environment === "preview" ? "preview" : "production",
            accountId: accountId
        };
    }
    return {
        type: "worker",
        name: info.workerName || String(env?.WORKER_NAME || "").trim(),
        environment: "production",
        accountId: accountId
    };
}

function getWorkerScriptName(env, request) {
    const target = getCloudflareApiTarget(env, request);
    return target.type === "worker" ? target.name : "";
}

function missingWorkerNameMessage() {
    return "Worker مربوط به این دامنه پیدا نشد. شناسایی خودکار به دسترسی خواندن Workers Domains/Routes در توکن Cloudflare نیاز دارد؛ در صورت نیاز متغیر متنی WORKER_NAME را برابر نام دقیق اسکریپت تنظیم کنید.";
}

function missingPagesProjectNameMessage() {
    return "پروژهٔ Pages مربوط به این دامنه پیدا نشد. برای شناسایی خودکار، توکن Cloudflare باید دسترسی Pages:Read داشته باشد؛ در صورت نیاز PAGES_PROJECT_NAME را برابر نام دقیق پروژه تنظیم کنید.";
}

function withWorkerNameNotFoundHint(message) {
    const text = String(message || "");
    if (!/this worker does not exist on your account/i.test(text)) return text;
    return text + " — مقدار WORKER_NAME باید دقیقاً نام Worker در Cloudflare باشد، نه نام دامنه.";
}

function getPagesProjectName(env, request) {
    const target = getCloudflareApiTarget(env, request);
    return target.type === "pages" ? target.name : "";
}

function pagesProjectApiUrl(accountId, projectName) {
    return `https://api.cloudflare.com/client/v4/accounts/${accountId}/pages/projects/${encodeURIComponent(projectName)}`;
}

function pagesConfigToBindings(config) {
    const cfg = config || {};
    const bindings = [];
    for (const [name, item] of Object.entries(cfg.d1_databases || {})) {
        bindings.push({
            type: "d1",
            name: name,
            id: item?.id || item?.database_id || ""
        });
    }
    for (const [name, item] of Object.entries(cfg.kv_namespaces || {})) {
        bindings.push({
            type: "kv_namespace",
            name: name,
            namespace_id: item?.namespace_id || ""
        });
    }
    for (const [name, item] of Object.entries(cfg.r2_buckets || {})) {
        bindings.push({
            type: "r2_bucket",
            name: name,
            bucket_name: item?.name || item?.bucket_name || ""
        });
    }
    for (const [name, item] of Object.entries(cfg.env_vars || {})) {
        bindings.push({
            type: item?.type || "plain_text",
            name: name,
            text: item?.value
        });
    }
    return bindings;
}

async function getCloudflareTargetConfiguration(env, request, cfToken, cfAccountId) {
    const target = getCloudflareApiTarget(env, request);
    if (!target.name) {
        throw new Error(target.type === "pages" ? missingPagesProjectNameMessage() : missingWorkerNameMessage());
    }
    const headers = {
        Authorization: "Bearer " + cfToken
    };
    if (target.type === "pages") {
        const response = await fetch(pagesProjectApiUrl(cfAccountId, target.name), {
            headers: headers
        });
        const data = await parseCfApiJson(response, "عدم دسترسی به تنظیمات پروژه Pages");
        if (!data.success) throw new Error(data.errors?.[0]?.message || "عدم دسترسی به تنظیمات پروژه Pages");
        const project = data.result || {};
        const environment = target.environment === "preview" ? "preview" : "production";
        const config = project.deployment_configs?.[environment] || project.deployment_configs?.production || {};
        return {
            target: target,
            project: project,
            config: config,
            bindings: pagesConfigToBindings(config)
        };
    }
    const baseUrl = `https://api.cloudflare.com/client/v4/accounts/${cfAccountId}/workers/scripts/${encodeURIComponent(target.name)}`;
    const response = await fetch(`${baseUrl}/bindings`, {
        headers: headers
    });
    const data = await parseCfApiJson(response, "عدم دسترسی به bindings ورکر");
    if (!data.success) throw new Error(withWorkerNameNotFoundHint(data.errors?.[0]?.message || "عدم دسترسی به تنظیمات ورکر"));
    return {
        target: target,
        baseUrl: baseUrl,
        config: null,
        bindings: data.result || []
    };
}

async function patchPagesEnvironmentVariables(env, request, cfToken, cfAccountId, changes) {
    const target = getCloudflareApiTarget(env, request);
    if (target.type !== "pages" || !target.name) throw new Error(missingPagesProjectNameMessage());
    const environment = target.environment === "preview" ? "preview" : "production";
    const response = await fetch(pagesProjectApiUrl(cfAccountId, target.name), {
        method: "PATCH",
        headers: {
            Authorization: "Bearer " + cfToken,
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            deployment_configs: {
                [environment]: {
                    env_vars: changes
                }
            }
        })
    });
    const data = await parseCfApiJson(response, "خطا در به‌روزرسانی متغیرهای Pages");
    if (!data.success) throw new Error(data.errors?.[0]?.message || "خطا در به‌روزرسانی متغیرهای Pages");
    return data.result;
}

function buildDeployBindings(existingBindings, cfToken, cfAccountId, env, workerName) {
    const names = new Set;
    const bindings = [];
    const adminValue = env?.ADMIN != null && String(env.ADMIN).trim() ? String(env.ADMIN) : "";
    for (const b of existingBindings || []) {
        if (!b?.name || names.has(b.name)) continue;
        names.add(b.name);
        if (b.name === "WORKER_NAME") {
            if (workerName) bindings.push({
                type: "plain_text",
                name: "WORKER_NAME",
                text: String(workerName)
            }); else if (b.type === "plain_text" && b.text != null) bindings.push({
                type: "plain_text",
                name: "WORKER_NAME",
                text: b.text
            }); else bindings.push({
                type: "inherit",
                name: "WORKER_NAME"
            });
            continue;
        }
        if (b.name === "CF_API_TOKEN") {
            const value = String(cfToken || b.text || "").trim();
            bindings.push(value ? {
                type: "plain_text",
                name: "CF_API_TOKEN",
                text: value
            } : {
                type: "inherit",
                name: "CF_API_TOKEN"
            });
            continue;
        }
        if (b.name === "CF_AC_ID") {
            const value = String(cfAccountId || b.text || "").trim();
            bindings.push(value ? {
                type: "plain_text",
                name: "CF_AC_ID",
                text: value
            } : {
                type: "inherit",
                name: "CF_AC_ID"
            });
            continue;
        }
        if (b.name === "ADMIN") {
            if (adminValue) bindings.push({
                type: "plain_text",
                name: "ADMIN",
                text: adminValue
            }); else if (b.type === "plain_text" && b.text != null) bindings.push({
                type: "plain_text",
                name: "ADMIN",
                text: b.text
            }); else bindings.push({
                type: "inherit",
                name: "ADMIN"
            });
            continue;
        }
        if (b.type === "d1") {
            bindings.push({
                type: "d1",
                name: b.name,
                id: b.database_id || b.id
            });
        } else if (b.type === "kv_namespace") {
            bindings.push({
                type: "kv_namespace",
                name: b.name,
                namespace_id: b.namespace_id
            });
        } else if (b.type === "plain_text" && b.text != null) {
            bindings.push({
                type: "plain_text",
                name: b.name,
                text: b.text
            });
        } else {
            bindings.push({
                type: "inherit",
                name: b.name
            });
        }
    }
    if (workerName && !names.has("WORKER_NAME")) bindings.push({
        type: "plain_text",
        name: "WORKER_NAME",
        text: String(workerName)
    });
    if (cfToken && !names.has("CF_API_TOKEN")) bindings.push({
        type: "plain_text",
        name: "CF_API_TOKEN",
        text: String(cfToken)
    });
    if (cfAccountId && !names.has("CF_AC_ID")) bindings.push({
        type: "plain_text",
        name: "CF_AC_ID",
        text: String(cfAccountId)
    });
    if (adminValue && !names.has("ADMIN")) bindings.push({
        type: "plain_text",
        name: "ADMIN",
        text: adminValue
    });
    return bindings;
}

function isCfTokenAuthError(message) {
    const msg = String(message || "").trim().toLowerCase();
    if (!msg) return false;
    return msg.includes("authentication error") || msg.includes("unauthorized") || msg.includes("invalid api token") || msg.includes("invalid access token") || msg.includes("invalid credentials") || msg.includes("عدم دسترسی به bindings ورکر") || msg.includes("عدم دسترسی به تنظیمات پروژه pages") || msg.includes("توکن یا اکانت آیدی کلودفلر تنظیم نشده");
}

async function deployPanelScript(env, request, sourceCode) {
    try {
        await RuntimeIdentityService.prepare(env, request, {
            forceRefresh: true
        });
    } catch (e) {}
    const target = getCloudflareApiTarget(env, request);
    const cfToken = await DbService.getCfToken(env);
    const cfAccountId = await DbService.getCfAccountIdResolved(env, request);
    if (!cfToken || !cfAccountId) {
        throw new Error("توکن یا اکانت آیدی کلودفلر تنظیم نشده است.");
    }
    if (target.type === "pages") {
        return await deployToPagesProject(env, request, sourceCode, target, cfToken, cfAccountId);
    }
    if (!sourceCode || sourceCode.length < 100) {
        throw new Error("سورس دریافتی نامعتبر است");
    }
    const scriptName = target.name;
    if (!scriptName) throw new Error(missingWorkerNameMessage());
    const baseUrl = `https://api.cloudflare.com/client/v4/accounts/${cfAccountId}/workers/scripts/${encodeURIComponent(scriptName)}`;
    const authHeaders = {
        Authorization: "Bearer " + cfToken
    };
    const bindingsRes = await fetch(`${baseUrl}/bindings`, {
        headers: authHeaders
    });
    const bindingsData = await parseCfApiJson(bindingsRes, "عدم دسترسی به bindings ورکر");
    if (!bindingsData.success) {
        throw new Error(withWorkerNameNotFoundHint(bindingsData.errors?.[0]?.message || "عدم دسترسی به تنظیمات ورکر"));
    }
    const mainModule = "nexa.js";
    const metadata = {
        main_module: mainModule,
        compatibility_date: "2024-02-08",
        bindings: buildDeployBindings(bindingsData.result || [], cfToken, cfAccountId, env, scriptName)
    };
    const formData = new FormData;
    formData.append("metadata", new Blob([ JSON.stringify(metadata) ], {
        type: "application/json"
    }));
    formData.append(mainModule, new Blob([ sourceCode ], {
        type: "application/javascript+module"
    }), mainModule);
    const deployRes = await fetch(baseUrl, {
        method: "PUT",
        headers: authHeaders,
        body: formData
    });
    const deployData = await parseCfApiJson(deployRes, "خطا در اعمال آپدیت در کلودفلر");
    if (!deployData.success) {
        throw new Error(deployData.errors?.[0]?.message || "خطا در اعمال آپدیت در کلودفلر");
    }
    return {
        scriptName: scriptName,
        runtime: "worker"
    };
}

async function parseCfApiJson(response, fallbackError) {
    const text = await response.text();
    try {
        return JSON.parse(text);
    } catch (e) {
        if (text.trimStart().startsWith("<!")) {
            throw new Error(fallbackError + " (پاسخ نامعتبر از Cloudflare)");
        }
        throw new Error(fallbackError);
    }
}

const PAGES_DEFAULT_COMPATIBILITY_DATE = "2024-02-08";

function sleepMs(ms) {
    return new Promise(function(resolve) {
        setTimeout(resolve, ms);
    });
}

function readPagesDeployHook(env) {
    for (const key of [ "PAGES_DEPLOY_HOOK", "CF_PAGES_DEPLOY_HOOK", "PAGES_DEPLOY_HOOK_URL" ]) {
        try {
            const value = env?.[key];
            if (value != null && String(value).trim()) return String(value).trim();
        } catch (e) {}
    }
    return "";
}

async function triggerPagesDeployHook(env, hookUrl, target) {
    let res;
    try {
        res = await fetch(hookUrl, {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                source: "nexa-panel",
                panel_version: PANEL_VERSION
            })
        });
    } catch (e) {
        throw new Error("ارتباط با Deploy Hook پروژه Pages برقرار نشد");
    }
    if (!res.ok) {
        let detail = "";
        try {
            detail = String(await res.text() || "").trim().slice(0, 160);
        } catch (e) {}
        throw new Error("Deploy Hook پروژه Pages با خطا پاسخ داد (کد " + res.status + ")" + (detail ? ": " + detail : ""));
    }
    return {
        scriptName: target.name,
        runtime: "pages",
        method: "deploy_hook",
        environment: target.environment
    };
}

async function waitForPagesDeployment(cfAccountId, projectName, deploymentId, cfToken, maxMs) {
    if (!deploymentId) return null;
    const url = pagesProjectApiUrl(cfAccountId, projectName) + "/deployments/" + encodeURIComponent(deploymentId);
    const deadline = Date.now() + (maxMs || 12e3);
    let last = null;
    while (Date.now() < deadline) {
        try {
            const res = await fetch(url, {
                headers: {
                    Authorization: "Bearer " + cfToken
                }
            });
            const data = await parseCfApiJson(res, "خطا در بررسی وضعیت دیپلوی Pages");
            if (data.success && data.result) {
                last = data.result;
                const status = String(last.latest_stage && last.latest_stage.status || "").toLowerCase();
                if (status === "success" || status === "failure" || status === "canceled") break;
            }
        } catch (e) {}
        await sleepMs(1500);
    }
    return last;
}

async function deployToPagesProject(env, request, sourceCode, target, cfToken, cfAccountId) {
    if (!sourceCode || sourceCode.length < 100 || !sourceCode.includes("export default")) {
        throw new Error("سورس دریافتی از سرور نامعتبر است؛ دیپلوی روی Pages انجام نشد.");
    }
    const projectName = String(target.name || "").trim();
    if (!projectName) {
        throw new Error(missingPagesProjectNameMessage());
    }
    const environment = target.environment === "preview" ? "preview" : "production";
    const hookUrl = readPagesDeployHook(env);
    if (hookUrl) {
        return await triggerPagesDeployHook(env, hookUrl, target);
    }
    const authHeaders = {
        Authorization: "Bearer " + cfToken
    };
    const projectUrl = pagesProjectApiUrl(cfAccountId, projectName);
    let project = {};
    try {
        const projectRes = await fetch(projectUrl, {
            headers: authHeaders
        });
        const projectData = await parseCfApiJson(projectRes, "عدم دسترسی به تنظیمات پروژه Pages");
        if (projectData.success) project = projectData.result || {};
    } catch (e) {}
    const deployConfigs = project.deployment_configs || {};
    const envConfig = deployConfigs[environment] || deployConfigs.production || {};
    const productionBranch = String(project.production_branch || "").trim();
    const branch = environment === "preview" ? String(envConfig.branch || "").trim() || "preview" : productionBranch || "main";
    const mainModule = "_worker.js";
    const metadata = {
        main_module: mainModule
    };
    const compatDate = String(envConfig.compatibility_date || "").trim();
    metadata.compatibility_date = /^\d{4}-\d{2}-\d{2}$/.test(compatDate) ? compatDate : PAGES_DEFAULT_COMPATIBILITY_DATE;
    const compatFlags = Array.isArray(envConfig.compatibility_flags) ? envConfig.compatibility_flags.filter(function(flag) {
        return String(flag || "").trim();
    }) : [];
    if (compatFlags.length) metadata.compatibility_flags = compatFlags;
    const boundary = "----nexapages" + Date.now().toString(16) + Math.random().toString(16).slice(2);
    const innerBody = "--" + boundary + "\r\n" + 'Content-Disposition: form-data; name="metadata"\r\n' + "Content-Type: application/json\r\n\r\n" + JSON.stringify(metadata) + "\r\n" + "--" + boundary + "\r\n" + 'Content-Disposition: form-data; name="' + mainModule + '"; filename="' + mainModule + '"\r\n' + "Content-Type: application/javascript+module\r\n\r\n" + sourceCode + "\r\n" + "--" + boundary + "--\r\n";
    const formData = new FormData;
    formData.append("manifest", "{}");
    formData.append("branch", branch);
    formData.append("_worker.bundle", new Blob([ innerBody ], {
        type: "multipart/form-data; boundary=" + boundary
    }), "_worker.bundle");
    let deployRes;
    try {
        deployRes = await fetch(projectUrl + "/deployments", {
            method: "POST",
            headers: authHeaders,
            body: formData
        });
    } catch (e) {
        throw new Error("ارتباط با API کلودفلر برای دیپلوی پروژه Pages برقرار نشد");
    }
    const deployData = await parseCfApiJson(deployRes, "خطا در دیپلوی پروژه Pages");
    if (!deployData.success) {
        const cfError = deployData.errors && deployData.errors[0] || {};
        const message = String(cfError.message || "خطا در دیپلوی پروژه Pages");
        let hint = "";
        if (/git|repository/i.test(message)) {
            hint = " — پروژه Pages به مخزن گیت وصل است؛ برای آپدیت خودکار متغیر PAGES_DEPLOY_HOOK را با آدرس Deploy Hook پروژه تنظیم کنید.";
        } else if (isCfTokenAuthError(message) || /permission|not authorized|forbidden|authentication/i.test(message)) {
            hint = " — توکن کلودفلر مجوز ویرایش Pages را ندارد (Cloudflare Pages: Edit لازم است) یا می‌توانید PAGES_DEPLOY_HOOK را تنظیم کنید.";
        }
        throw new Error("دیپلوی خودکار روی Pages انجام نشد: " + message + hint);
    }
    const deployment = deployData.result || {};
    const finalState = await waitForPagesDeployment(cfAccountId, projectName, deployment.id, cfToken);
    const finalStage = finalState && finalState.latest_stage || {};
    const finalStatus = String(finalStage.status || "").toLowerCase();
    if (finalStatus === "failure" || finalStatus === "canceled") {
        const stageName = String(finalStage.name || "").trim();
        throw new Error("دیپلوی جدید پروژه Pages آماده نشد (وضعیت: " + finalStatus + (stageName ? " - " + stageName : "") + ")؛ کد فعلی پنل دست‌نخورده است.");
    }
    return {
        scriptName: projectName,
        runtime: "pages",
        method: "direct_upload",
        environment: environment,
        branch: branch,
        deploymentId: deployment.id || "",
        deploymentUrl: deployment.url || "",
        deploymentStatus: finalStatus
    };
}

async function cloudflareTargetExistsInAccount(cfToken, target, accountId) {
    if (!target?.name || !accountId) return false;
    const url = target.type === "pages" ? pagesProjectApiUrl(accountId, target.name) : `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(accountId)}/workers/scripts/${encodeURIComponent(target.name)}`;
    const response = await fetchWithTimeout(url, {
        headers: {
            Authorization: "Bearer " + String(cfToken || "").trim()
        }
    }, 5e3);
    const data = await parseCfApiJson(response, "");
    return response.ok && !!data?.success;
}

async function resolveCfAccountId(cfToken, rawTarget) {
    const token = String(cfToken || "").trim();
    if (!token) throw new Error("توکن API کلودفلر یافت نشد");
    const target = typeof rawTarget === "string" ? {
        type: "worker",
        name: rawTarget
    } : rawTarget || {
        type: "worker",
        name: ""
    };
    if (target.accountId) return String(target.accountId).trim();
    const candidates = await listCloudflareAccounts(token);
    if (!candidates.length) {
        throw new Error("اکانت کلودفلر یافت نشد؛ شناسهٔ اکانت را در صفحهٔ راه‌اندازی وارد کنید یا CF_AC_ID را به‌صورت Text تنظیم کنید.");
    }
    if (target.name) {
        for (const acc of candidates) {
            try {
                const url = target.type === "pages" ? pagesProjectApiUrl(acc.id, target.name) : `https://api.cloudflare.com/client/v4/accounts/${acc.id}/workers/scripts/${encodeURIComponent(target.name)}`;
                const targetRes = await fetchWithTimeout(url, {
                    headers: {
                        Authorization: "Bearer " + token
                    }
                }, 5e3);
                if (targetRes.ok) {
                    const targetData = await targetRes.json();
                    if (targetData.success) return acc.id;
                }
            } catch (e) {}
        }
        if (candidates.length === 1) return candidates[0].id;
        throw new Error(target.type === "pages" ? "پروژهٔ Pages با این نام در اکانت‌های قابل‌دسترسی پیدا نشد؛ نام پروژه و مجوز Pages:Read را بررسی کنید." : "Worker با این نام در اکانت‌های قابل‌دسترسی پیدا نشد؛ نام Worker و مجوز Workers Scripts:Read را بررسی کنید.");
    }
    return candidates[0].id;
}

const RUNTIME_TARGET_KEY_PREFIX = "runtime_target:";

const RUNTIME_TARGET_CACHE_TTL_MS = 5 * 60 * 1e3;

const RUNTIME_TARGET_RECHECK_MS = 15 * 60 * 1e3;

const runtimeTargetMemoryCache = new Map;

function normalizeRuntimeHostname(value) {
    return String(value || "").trim().toLowerCase().replace(/\.$/, "");
}

function runtimeTargetName(target) {
    return String(target?.name || target?.projectName || target?.workerName || "").trim();
}

function applyRuntimeTarget(env, target) {
    if (!env || !target || !target.name) return;
    const type = target.type === "pages" ? "pages" : "worker";
    const info = {
        type: type,
        projectName: type === "pages" ? String(target.name) : "",
        workerName: type === "worker" ? String(target.name) : "",
        environment: type === "pages" && target.environment === "preview" ? "preview" : "production",
        accountId: String(target.accountId || "").trim()
    };
    try {
        Object.defineProperty(env, "__NEXA_RUNTIME_INFO", {
            value: info,
            enumerable: true,
            configurable: true
        });
    } catch (e) {}
    try {
        Object.defineProperty(env, "__NEXA_RUNTIME_TARGET", {
            value: target,
            enumerable: true,
            configurable: true
        });
    } catch (e) {}
}

async function cloudflareApiGetJson(url, token, timeoutMs = 6e3) {
    const response = await fetchWithTimeout(url, {
        headers: {
            Authorization: "Bearer " + String(token || "").trim()
        }
    }, timeoutMs);
    const data = await parseCfApiJson(response, "");
    return response.ok && data?.success ? data : null;
}

async function listCloudflareAccounts(token, preferredAccountId) {
    const accounts = [];
    const seen = new Set;
    const add = item => {
        const id = String(item?.id || "").trim();
        if (!id || seen.has(id)) return;
        seen.add(id);
        accounts.push({
            id: id
        });
    };
    if (preferredAccountId) add({
        id: preferredAccountId
    });
    for (let page = 1; page <= 5; page++) {
        try {
            const data = await cloudflareApiGetJson(`https://api.cloudflare.com/client/v4/accounts?page=${page}&per_page=50`, token, 6e3);
            if (!data || !Array.isArray(data.result)) break;
            data.result.forEach(add);
            const totalPages = Number(data.result_info?.total_pages || 0);
            if (!totalPages || page >= totalPages || data.result.length < 50) break;
        } catch (e) {
            break;
        }
    }
    if (!accounts.length) {
        try {
            const data = await cloudflareApiGetJson("https://api.cloudflare.com/client/v4/zones?per_page=50", token, 6e3);
            if (data && Array.isArray(data.result)) data.result.forEach(zone => add(zone?.account));
        } catch (e) {}
    }
    if (!accounts.length) {
        try {
            const data = await cloudflareApiGetJson("https://api.cloudflare.com/client/v4/memberships", token, 6e3);
            if (data && Array.isArray(data.result)) data.result.forEach(membership => add(membership?.account));
        } catch (e) {}
    }
    return accounts;
}

function routePatternMatches(pattern, hostname, pathname) {
    const value = String(pattern || "").trim();
    if (!value) return false;
    const candidates = [ normalizeRuntimeHostname(hostname) + (pathname || "/"), normalizeRuntimeHostname(hostname) ];
    const escaped = value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\\\*/g, ".*");
    let regex;
    try {
        regex = new RegExp("^" + escaped + "$", "i");
    } catch (e) {
        return false;
    }
    return candidates.some(candidate => regex.test(candidate));
}

async function findWorkerCustomDomain(token, accountId, hostname) {
    const url = `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(accountId)}/workers/domains?hostname=${encodeURIComponent(hostname)}`;
    const data = await cloudflareApiGetJson(url, token, 5e3);
    const domains = Array.isArray(data?.result) ? data.result : [];
    const match = domains.find(item => normalizeRuntimeHostname(item?.hostname) === hostname && String(item?.service || "").trim());
    if (!match) return null;
    return {
        type: "worker",
        name: String(match.service).trim(),
        environment: "production",
        accountId: accountId,
        hostname: hostname,
        source: "workers-domain-api"
    };
}

async function findPagesProjectByDomain(token, accountId, hostname) {
    for (let page = 1; page <= 10; page++) {
        const url = `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(accountId)}/pages/projects?page=${page}&per_page=100`;
        const data = await cloudflareApiGetJson(url, token, 6e3);
        const projects = Array.isArray(data?.result) ? data.result : [];
        for (const project of projects) {
            const projectName = String(project?.name || project?.project_name || "").trim();
            const domains = Array.isArray(project?.domains) ? project.domains : [];
            const matches = domains.some(item => {
                const domain = typeof item === "string" ? item : item?.name || item?.domain || "";
                return normalizeRuntimeHostname(domain) === hostname;
            });
            if (projectName && matches) {
                return {
                    type: "pages",
                    name: projectName,
                    environment: "production",
                    accountId: accountId,
                    hostname: hostname,
                    source: "pages-project-domains-api"
                };
            }
        }
        const totalPages = Number(data?.result_info?.total_pages || 0);
        if (!data || !projects.length || totalPages && page >= totalPages || projects.length < 100) break;
    }
    return null;
}

async function findWorkerRouteByDomain(token, accountId, hostname, pathname) {
    const zonesUrl = `https://api.cloudflare.com/client/v4/zones?account.id=${encodeURIComponent(accountId)}&page=1&per_page=100`;
    const zonesData = await cloudflareApiGetJson(zonesUrl, token, 5e3);
    const zones = Array.isArray(zonesData?.result) ? zonesData.result : [];
    const matchingZones = zones.filter(zone => {
        const name = normalizeRuntimeHostname(zone?.name);
        return name && (hostname === name || hostname.endsWith("." + name));
    }).sort((a, b) => String(b?.name || "").length - String(a?.name || "").length);
    for (const zone of matchingZones) {
        const routesUrl = `https://api.cloudflare.com/client/v4/zones/${encodeURIComponent(zone.id)}/workers/routes`;
        const routesData = await cloudflareApiGetJson(routesUrl, token, 5e3);
        const routes = Array.isArray(routesData?.result) ? routesData.result : [];
        const matchingRoutes = routes.filter(route => route?.script && routePatternMatches(route.pattern, hostname, pathname)).sort((a, b) => String(b.pattern || "").length - String(a.pattern || "").length);
        if (matchingRoutes.length) {
            return {
                type: "worker",
                name: String(matchingRoutes[0].script).trim(),
                environment: "production",
                accountId: accountId,
                hostname: hostname,
                source: "workers-route-api"
            };
        }
    }
    return null;
}

async function findTargetInCloudflareAccount(token, accountId, hostname, pathname, preferredType) {
    const types = preferredType === "pages" ? [ "pages", "worker" ] : [ "worker", "pages" ];
    for (const type of types) {
        try {
            if (type === "worker") {
                const domain = await findWorkerCustomDomain(token, accountId, hostname);
                if (domain) return domain;
                const route = await findWorkerRouteByDomain(token, accountId, hostname, pathname);
                if (route) return route;
            } else {
                const project = await findPagesProjectByDomain(token, accountId, hostname);
                if (project) return project;
            }
        } catch (e) {}
    }
    return null;
}

async function findTargetForCustomDomain(token, hostname, pathname, preferredType, preferredAccountId) {
    const triedAccounts = new Set;
    if (preferredAccountId) {
        triedAccounts.add(String(preferredAccountId));
        const preferredMatch = await findTargetInCloudflareAccount(token, String(preferredAccountId), hostname, pathname, preferredType);
        if (preferredMatch) return preferredMatch;
    }
    const accounts = await listCloudflareAccounts(token);
    for (const account of accounts) {
        if (!account?.id || triedAccounts.has(String(account.id))) continue;
        triedAccounts.add(String(account.id));
        const match = await findTargetInCloudflareAccount(token, String(account.id), hostname, pathname, preferredType);
        if (match) return match;
    }
    return null;
}

const RuntimeIdentityService = {
    async readStored(env, hostname) {
        if (!env?.DB || !hostname) return null;
        try {
            const key = RUNTIME_TARGET_KEY_PREFIX + hostname;
            const row = await env.DB.prepare("SELECT value FROM settings WHERE key = ?").bind(key).first();
            if (!row?.value) return null;
            const parsed = JSON.parse(String(row.value));
            const type = parsed?.type === "pages" ? "pages" : parsed?.type === "worker" ? "worker" : "";
            const name = String(parsed?.name || "").trim();
            if (!type || !name) return null;
            return {
                type: type,
                name: name,
                environment: type === "pages" && parsed.environment === "preview" ? "preview" : "production",
                accountId: String(parsed.accountId || "").trim(),
                hostname: hostname,
                checkedAt: Number(parsed.checkedAt || 0),
                source: String(parsed.source || "d1-cache")
            };
        } catch (e) {
            return null;
        }
    },
    async save(env, target) {
        const hostname = normalizeRuntimeHostname(target?.hostname);
        const name = runtimeTargetName(target);
        if (!hostname || !name || ![ "worker", "pages" ].includes(target.type)) return null;
        const saved = {
            type: target.type,
            name: name,
            environment: target.type === "pages" && target.environment === "preview" ? "preview" : "production",
            accountId: String(target.accountId || "").trim(),
            hostname: hostname,
            checkedAt: Date.now(),
            source: String(target.source || "runtime-detection")
        };
        runtimeTargetMemoryCache.set(hostname, {
            target: saved,
            cachedAt: Date.now()
        });
        if (runtimeTargetMemoryCache.size > 128) {
            const oldest = runtimeTargetMemoryCache.keys().next().value;
            if (oldest) runtimeTargetMemoryCache.delete(oldest);
        }
        if (env?.DB) {
            try {
                await DbService.ensureSchema(env.DB);
                await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)").bind(RUNTIME_TARGET_KEY_PREFIX + hostname, JSON.stringify(saved)).run();
            } catch (e) {}
        }
        applyRuntimeTarget(env, saved);
        return saved;
    },
    async prepare(env, request, options = {}) {
        const hostname = normalizeRuntimeHostname(new URL(request.url).hostname);
        if (!hostname) return null;
        const forceRefresh = !!options.forceRefresh;
        const now = Date.now();
        const cached = runtimeTargetMemoryCache.get(hostname);
        if (!forceRefresh && cached && now - cached.cachedAt < RUNTIME_TARGET_CACHE_TTL_MS) {
            applyRuntimeTarget(env, cached.target);
            return cached.target;
        }
        try {
            if (env?.DB) await DbService.ensureSchema(env.DB);
        } catch (e) {}
        const stored = await this.readStored(env, hostname);
        const detected = getRuntimeInfo(env, request);
        const detectedName = runtimeTargetName({
            type: detected.type,
            name: detected.type === "pages" ? detected.projectName : detected.workerName
        });
        const directTarget = detectedName ? {
            type: detected.type,
            name: detectedName,
            environment: detected.environment || "production",
            accountId: String(detected.accountId || "").trim(),
            hostname: hostname,
            source: hostname.endsWith(".workers.dev") || hostname.endsWith(".pages.dev") ? "runtime-host" : "runtime-binding"
        } : null;
        const isCloudflareDefaultHost = hostname.endsWith(".workers.dev") || hostname.endsWith(".pages.dev");
        const isCustomDomain = !isCloudflareDefaultHost;
        const token = String(options.tokenOverride || await DbService.getCfToken(env) || "").trim();
        let accountHint = String(options.accountIdOverride || stored?.accountId || "").trim();
        if (!accountHint) {
            try {
                accountHint = await DbService.getCfAccountId(env);
            } catch (e) {}
        }
        const storedIsFresh = !!(stored?.checkedAt && now - stored.checkedAt < RUNTIME_TARGET_RECHECK_MS);
        if (isCustomDomain && token && (forceRefresh || !storedIsFresh)) {
            try {
                const url = new URL(request.url);
                const discovered = await findTargetForCustomDomain(token, hostname, url.pathname, detected.type, accountHint);
                if (discovered) return await this.save(env, discovered);
            } catch (e) {}
        }
        if (directTarget) {
            if (!directTarget.accountId && stored?.type === directTarget.type && stored.name === directTarget.name) {
                directTarget.accountId = stored.accountId;
            }
            if (!directTarget.accountId) directTarget.accountId = String(options.accountIdOverride || "").trim();
            return await this.save(env, directTarget);
        }
        if (stored) {
            runtimeTargetMemoryCache.set(hostname, {
                target: stored,
                cachedAt: now
            });
            applyRuntimeTarget(env, stored);
            return stored;
        }
        return null;
    }
};

const SetupService = {
    async setAdminVariable(env, request, password) {
        try {
            await RuntimeIdentityService.prepare(env, request);
        } catch (e) {}
        const target = getCloudflareApiTarget(env, request);
        if (target.type === "pages") {
            if (!env.DB) throw new Error("برای ذخیره رمز در Pages اتصال D1 لازم است");
            const passwordHash = await DbService.sha256(String(password));
            await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('ADMIN', ?)").bind(passwordHash).run();
            const cfToken = await DbService.getCfToken(env);
            if (cfToken && target.name) {
                try {
                    const cfAccountId = await DbService.getCfAccountIdResolved(env, request);
                    if (cfAccountId) {
                        await patchPagesEnvironmentVariables(env, request, cfToken, cfAccountId, {
                            ADMIN: {
                                type: "plain_text",
                                value: String(password)
                            },
                            CF_API_TOKEN: {
                                type: "plain_text",
                                value: String(cfToken)
                            },
                            CF_AC_ID: {
                                type: "plain_text",
                                value: String(cfAccountId)
                            },
                            PAGES_PROJECT_NAME: {
                                type: "plain_text",
                                value: String(target.name)
                            }
                        });
                    }
                } catch (e) {}
            }
            return true;
        }
        const cfToken = await DbService.getCfToken(env);
        if (!cfToken) {
            throw new Error("متغیر CF_API_TOKEN از نوع Text یا Secret پیدا نشد یا خالی است؛ مقدار CF_API_TOKEN را در تنظیمات Worker وارد کنید.");
        }
        const scriptName = target.name;
        if (!scriptName) throw new Error(missingWorkerNameMessage());
        const cfAccountId = await DbService.getCfAccountIdResolved(env, request);
        if (!cfAccountId) {
            throw new Error("CF_AC_ID از نوع Text تنظیم نشده و شناسهٔ اکانت از توکن دریافت نشد؛ شناسهٔ اکانت را در فیلد اختیاری همین صفحه وارد کنید، یا CF_AC_ID را Text تنظیم کنید یا دسترسی خواندن اکانت/زون را به توکن بدهید.");
        }
        const baseUrl = `https://api.cloudflare.com/client/v4/accounts/${cfAccountId}/workers/scripts/${encodeURIComponent(scriptName)}`;
        const authHeaders = {
            Authorization: "Bearer " + cfToken
        };
        for (const name of [ "ADMIN", "CF_API_TOKEN", "CF_AC_ID" ]) {
            try {
                await fetchWithTimeout(`${baseUrl}/secrets/${encodeURIComponent(name)}`, {
                    method: "DELETE",
                    headers: authHeaders
                }, CF_API_TIMEOUT_MS);
            } catch (e) {}
        }
        const bindingsRes = await fetchWithTimeout(`${baseUrl}/bindings`, {
            headers: authHeaders
        }, CF_API_TIMEOUT_MS);
        const bindingsData = await parseCfApiJson(bindingsRes, "عدم دسترسی به bindings ورکر");
        if (!bindingsData.success) {
            throw new Error(withWorkerNameNotFoundHint(bindingsData.errors?.[0]?.message || "عدم دسترسی به تنظیمات ورکر"));
        }
        const existingBindings = bindingsData.result || [];
        const replacedNames = new Set([ "ADMIN", "CF_API_TOKEN", "CF_AC_ID" ]);
        const newBindings = existingBindings.filter(b => !replacedNames.has(b.name)).map(b => b.name === "WORKER_NAME" ? {
            type: "plain_text",
            name: "WORKER_NAME",
            text: scriptName
        } : {
            type: "inherit",
            name: b.name
        });
        if (!existingBindings.some(b => b.name === "WORKER_NAME")) {
            newBindings.push({
                type: "plain_text",
                name: "WORKER_NAME",
                text: scriptName
            });
        }
        newBindings.push({
            type: "plain_text",
            name: "CF_API_TOKEN",
            text: String(cfToken)
        }, {
            type: "plain_text",
            name: "CF_AC_ID",
            text: String(cfAccountId)
        }, {
            type: "plain_text",
            name: "ADMIN",
            text: String(password)
        });
        const formData = new FormData;
        formData.append("settings", new Blob([ JSON.stringify({
            bindings: newBindings
        }) ], {
            type: "application/json"
        }));
        const patchRes = await fetchWithTimeout(`${baseUrl}/settings`, {
            method: "PATCH",
            headers: authHeaders,
            body: formData
        }, CF_API_TIMEOUT_MS);
        const patchData = await parseCfApiJson(patchRes, "خطا در به‌روزرسانی متغیرهای ADMIN و Cloudflare");
        if (!patchData.success) {
            throw new Error(patchData.errors?.[0]?.message || patchData.errors?.[0]?.code || "خطا در به‌روزرسانی متغیرهای ADMIN و Cloudflare");
        }
        return true;
    },
    async setCfCredentials(env, request, newToken, newAccountId) {
        newToken = String(newToken || "").trim();
        newAccountId = String(newAccountId || "").trim();
        if (!newToken) throw new Error("توکن API کلودفلر را وارد کنید");
        try {
            await RuntimeIdentityService.prepare(env, request, {
                forceRefresh: true,
                tokenOverride: newToken,
                accountIdOverride: newAccountId
            });
        } catch (e) {}
        const target = getCloudflareApiTarget(env, request);
        if (!target.name) {
            throw new Error(target.type === "pages" ? missingPagesProjectNameMessage() : missingWorkerNameMessage());
        }
        newAccountId = target.accountId || newAccountId || await resolveCfAccountId(newToken, target);
        if (target.type === "pages") {
            let mirrorError = null;
            try {
                const changes = {
                    CF_API_TOKEN: {
                        type: "plain_text",
                        value: newToken
                    },
                    CF_AC_ID: {
                        type: "plain_text",
                        value: newAccountId
                    },
                    PAGES_PROJECT_NAME: {
                        type: "plain_text",
                        value: target.name
                    }
                };
                const adminValue = env?.ADMIN != null && String(env.ADMIN).trim() ? String(env.ADMIN) : "";
                if (adminValue) changes.ADMIN = {
                    type: "plain_text",
                    value: adminValue
                };
                await patchPagesEnvironmentVariables(env, request, newToken, newAccountId, changes);
            } catch (e) {
                mirrorError = e;
            }
            if (env.DB) {
                await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('CF_API_TOKEN', ?)").bind(newToken).run();
                await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('CF_AC_ID', ?)").bind(newAccountId).run();
            } else if (mirrorError) {
                throw mirrorError;
            }
            return true;
        }
        const authToken = newToken;
        let currentAccountId = target.accountId || newAccountId || await DbService.getCfAccountId(env);
        if (!currentAccountId) {
            try {
                currentAccountId = await resolveCfAccountId(authToken, target);
            } catch (e) {}
        }
        if (!currentAccountId) {
            throw new Error("شناسهٔ اکانت Cloudflare مشخص نیست؛ شناسهٔ اکانت را در فیلد اختیاری همین صفحه وارد کنید، یا CF_AC_ID را به‌صورت Text تنظیم کنید یا دسترسی خواندن اکانت/زون را به توکن بدهید.");
        }
        const baseUrl = `https://api.cloudflare.com/client/v4/accounts/${currentAccountId}/workers/scripts/${encodeURIComponent(target.name)}`;
        const authHeaders = {
            Authorization: "Bearer " + authToken
        };
        const bindingsRes = await fetchWithTimeout(`${baseUrl}/bindings`, {
            headers: authHeaders
        }, CF_API_TIMEOUT_MS);
        const bindingsData = await parseCfApiJson(bindingsRes, "عدم دسترسی به bindings ورکر");
        if (!bindingsData.success) {
            throw new Error(withWorkerNameNotFoundHint(bindingsData.errors?.[0]?.message || "عدم دسترسی به تنظیمات ورکر"));
        }
        const existing = bindingsData.result || [];
        const adminValue = env?.ADMIN != null && String(env.ADMIN).trim() ? String(env.ADMIN) : "";
        for (const name of [ "CF_API_TOKEN", "CF_AC_ID", ...adminValue ? [ "ADMIN" ] : [] ]) {
            try {
                await fetch(`${baseUrl}/secrets/${encodeURIComponent(name)}`, {
                    method: "DELETE",
                    headers: authHeaders
                });
            } catch (e) {}
        }
        const replacedNames = new Set([ "CF_API_TOKEN", "CF_AC_ID" ]);
        if (adminValue) replacedNames.add("ADMIN");
        const newBindings = existing.filter(b => !replacedNames.has(b.name)).map(b => b.name === "WORKER_NAME" ? {
            type: "plain_text",
            name: "WORKER_NAME",
            text: target.name
        } : {
            type: "inherit",
            name: b.name
        });
        if (!existing.some(b => b.name === "WORKER_NAME")) {
            newBindings.push({
                type: "plain_text",
                name: "WORKER_NAME",
                text: target.name
            });
        }
        newBindings.push({
            type: "plain_text",
            name: "CF_API_TOKEN",
            text: newToken
        }, {
            type: "plain_text",
            name: "CF_AC_ID",
            text: newAccountId || currentAccountId
        });
        if (adminValue) newBindings.push({
            type: "plain_text",
            name: "ADMIN",
            text: adminValue
        });
        const formData = new FormData;
        formData.append("settings", new Blob([ JSON.stringify({
            bindings: newBindings
        }) ], {
            type: "application/json"
        }));
        const patchRes = await fetchWithTimeout(`${baseUrl}/settings`, {
            method: "PATCH",
            headers: authHeaders,
            body: formData
        }, CF_API_TIMEOUT_MS);
        const patchData = await parseCfApiJson(patchRes, "خطا در به‌روزرسانی CF_API_TOKEN و CF_AC_ID");
        if (!patchData.success) {
            throw new Error(patchData.errors?.[0]?.message || "خطا در به‌روزرسانی CF_API_TOKEN و CF_AC_ID");
        }
        if (env.DB) {
            await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('CF_API_TOKEN', ?)").bind(newToken).run();
            await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('CF_AC_ID', ?)").bind(newAccountId || currentAccountId).run();
        }
        return true;
    },
    async storeLocalPassword(env, password) {
        try {
            if (!env || !env.DB) return {
                ok: false,
                reason: "no-d1"
            };
            await DbService.ensureSchema(env.DB);
            const hash = await DbService.sha256(String(password));
            await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('ADMIN', ?)").bind(hash).run();
            setupReadyCache = {
                value: true,
                fetchedAt: Date.now()
            };
            return {
                ok: true
            };
        } catch (e) {
            return {
                ok: false,
                reason: e && e.message ? e.message : "unknown"
            };
        }
    },
    async hasStoredLocalPassword(env) {
        if (!env || !env.DB) return false;
        try {
            const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'ADMIN'").first();
            return !!(row && row.value && String(row.value).trim());
        } catch (e) {
            return false;
        }
    },
    async getStatus(env, request, options = {}) {
        /* deepProbe =true → اجازه‌ی فراخوانی API کلادفلر برای نمایش جزئیات بیشتر.
           پیش‌فرض false است تا صفحه راه‌اندازی سریع و بدون ریسک تایم‌اوت بماند. */
        const deepProbe = !!(options && options.deepProbe === true);
        try {
            await RuntimeIdentityService.prepare(env, request);
        } catch (e) {}
        const runtime = getRuntimeInfo(env, request);
        const target = getCloudflareApiTarget(env, request);
        let d1Connected = false;
        let d1BindingName = String(env?.__NEXA_DB_BINDING_NAME || "DB");
        let d1DatabaseName = null;
        let d1DatabaseId = null;
        let d1Error = null;
        if (!env.DB) {
            d1Error = runtime.type === "pages" ? "بایندینگ D1 داخل env این Deployment تزریق نشده است. پس از افزودن DB در Settings باید یک Deployment جدید یا Retry deployment انجام شود؛ وجود DB در داشبورد به‌تنهایی Deployment قبلی را تغییر نمی‌دهد." : "اتصال D1 یافت نشد. نام binding می‌تواند DB، D1، DATABASE یا هر نام دلخواه دیگری باشد.";
        } else {
            try {
                await DbService.ensureSchema(env.DB);
                await env.DB.prepare("SELECT 1 AS ok").first();
                d1Connected = true;
            } catch (e) {
                d1Error = e.message || "خطا در اتصال به D1";
            }
        }
        let cfToken = "";
        try {
            cfToken = await DbService.getCfToken(env);
        } catch (e) {}
        let cfAccountId = String(target.accountId || "").trim();
        if (!cfAccountId) {
            try {
                cfAccountId = await DbService.getCfAccountId(env);
            } catch (e) {}
        }
        let cfApiToken = !!cfToken || DbService.isCfTokenBound(env) || listRuntimeBindingNames(env).includes("CF_API_TOKEN");
        const tokenForApi = cfToken || DbService.readCfTokenFromEnv(env);
        let cfAccountIdAuto = !!target.accountId;
        if (deepProbe && !cfAccountId && tokenForApi && request) {
            cfAccountId = await DbService.getCfAccountIdResolved(env, request);
            cfAccountIdAuto = !!cfAccountId;
        }
        const cfAccountIdSet = !!cfAccountId;
        let apiBindings = [];
        let adminFromApi = false;
        if (deepProbe && cfAccountIdSet && tokenForApi && request && target.name) {
            try {
                const configData = await getCloudflareTargetConfiguration(env, request, tokenForApi, cfAccountId);
                apiBindings = configData.bindings || [];
                if (apiBindings.some(b => b.name === "CF_API_TOKEN")) cfApiToken = true;
                const adminBinding = apiBindings.find(b => b && b.name === "ADMIN");
                if (adminBinding && (adminBinding.type === "secret_text" || adminBinding.text != null && String(adminBinding.text).trim())) {
                    adminFromApi = true;
                }
                const d1Binding = apiBindings.find(b => b.type === "d1" && b.name === d1BindingName) || apiBindings.find(b => b.type === "d1");
                if (d1Binding) {
                    d1BindingName = d1Binding.name || d1BindingName;
                    d1DatabaseId = d1Binding.database_id || d1Binding.id || null;
                    if (d1DatabaseId) {
                        const dbRes = await fetch(`https://api.cloudflare.com/client/v4/accounts/${cfAccountId}/d1/database/${d1DatabaseId}`, {
                            headers: {
                                Authorization: "Bearer " + tokenForApi
                            }
                        });
                        const dbData = await dbRes.json();
                        if (dbData.success && dbData.result?.name) d1DatabaseName = dbData.result.name;
                    }
                }
            } catch (e) {}
        }
        const adminFromEnv = !!(env.ADMIN && String(env.ADMIN).trim());
        let adminFromD1 = false;
        if (!adminFromEnv && env.DB) {
            try {
                const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'ADMIN'").first();
                adminFromD1 = !!(row?.value && String(row.value).trim());
            } catch (e) {}
        }
        const adminConfigured = adminFromEnv || adminFromD1 || adminFromApi;
        /* CF_API_TOKEN دیگر برای راه‌اندازی الزامی نیست: رمز عبور در D1 ذخیره می‌شود.
           توکن فقط برای امکانات اختیاری (اسکنر، پاک‌سازی IP، دیپلوی خودکار) لازم است. */
        const tokenRequired = false;
        const setupReady = d1Connected && adminConfigured;
        return {
            runtime_type: runtime.type,
            runtime_name: target.name || "",
            pages_environment: runtime.type === "pages" ? target.environment : "",
            d1_connected: d1Connected,
            d1_binding_name: d1BindingName,
            d1_database_name: d1DatabaseName,
            d1_database_id: d1DatabaseId,
            d1_error: d1Error,
            detected_bindings: listRuntimeBindingNames(env).filter(name => !/^__NEXA_/.test(name)),
            cf_api_token: cfApiToken,
            cf_token_required: tokenRequired,
            cf_account_id: cfAccountIdSet,
            cf_account_id_auto: cfAccountIdAuto,
            cf_account_id_value: cfAccountId || "",
            admin_secret: adminConfigured,
            admin_configured: adminConfigured,
            admin_from_env: adminFromEnv,
            admin_from_d1: adminFromD1,
            admin_from_api: adminFromApi,
            admin_legacy_d1: adminFromD1,
            setup_ready: setupReady
        };
    },
    async isReady(env) {
        if (!env.DB) return false;
        if (setupReadyCache.value === true && Date.now() - setupReadyCache.fetchedAt < SETUP_READY_CACHE_TTL_MS) return true;
        try {
            await DbService.ensureSchema(env.DB);
            await env.DB.prepare("SELECT 1 AS ok").first();
        } catch (e) {
            return false;
        }
        const hasAdmin = !!await DbService.getPanelPassword(env);
        if (!hasAdmin) return false;
        /* داشتن رمز عبور (در D1 یا متغیر ADMIN) یعنی راه‌اندازی کامل شده است.
           این شرط قبلاً به CF_API_TOKEN هم نیاز داشت و باعث می‌شد /api/login
           با خطای ۴۰۳ بسته بماند. */
        const ready = true;
        if (ready) setupReadyCache = {
            value: true,
            fetchedAt: Date.now()
        };
        return ready;
    }
};

const EXPIRED_PURGE_DELAY_MS = 24 * 60 * 60 * 1e3;

function isUserExpired(user, now = Date.now()) {
    if (!user) return false;
    if (isVolumeExpired(user)) return true;
    return isTimeExpired(user, now);
}

function isVolumeExpired(user) {
    /* [FINAL] گارد null */ if (!user) return false;
    return user.limit_gb != null && user.used_gb >= user.limit_gb;
}

function isTimeExpired(user, now = Date.now()) {
    /* [FINAL] گارد null */ if (!user || !user.expiry_days || !user.created_at) return false;
    const created = new Date(user.created_at);
    const expiryDate = new Date(created.getTime() + user.expiry_days * 24 * 60 * 60 * 1e3);
    return now > expiryDate.getTime();
}

function getInactiveReason(user, now = Date.now()) {
    /* [FINAL] گارد null */ if (!user) return "غیرفعال";
    if (isUserRequestLimitExceeded(user, user.username)) return "اتمام ریکوئست";
    const volExp = isVolumeExpired(user);
    const timeExp = isTimeExpired(user, now);
    if (volExp && timeExp) return "پایان زمان و حجم سرویس";
    if (volExp) return "پایان حجم سرویس";
    if (timeExp) return "پایان زمان سرویس";
    if (user.is_active === 0) return "قطع شدن دستی توسط ادمین";
    return "غیرفعال";
}

function isUserInactive(user, now = Date.now()) {
    /* [FINAL] گارد null */ if (!user) return false;
    return user.is_active === 0 || isUserExpired(user, now) || isUserRequestLimitExceeded(user, user.username);
}

function fmtRemarkVolume(gb) {
    if (gb == null || gb === undefined) return "∞";
    if (gb < 1) return (gb * 1024).toFixed(0) + " MB";
    const n = gb % 1 === 0 ? gb.toFixed(0) : gb.toFixed(2);
    return n + " GB";
}

function buildServiceInfoRemark(user, now = Date.now()) {
    /* [FINAL] گارد null */ if (!user) return buildFirstRemark();
    const usedStr = fmtRemarkVolume(user.used_gb || 0);
    const totalStr = user.limit_gb != null ? fmtRemarkVolume(user.limit_gb) : "∞";
    let daysPart = "∞";
    if (user.expiry_days) {
        if (user.created_at) {
            const created = new Date(user.created_at);
            const expiryDate = new Date(created.getTime() + user.expiry_days * 24 * 60 * 60 * 1e3);
            const diffDays = Math.ceil((expiryDate - now) / (1e3 * 60 * 60 * 24));
            daysPart = (diffDays > 0 ? diffDays : 0) + " روز";
        } else {
            daysPart = user.expiry_days + " روز";
        }
    }
    return "[مصرف شده: " + usedStr + "]" + "[" + totalStr + " : کل " + "]" + "[مانده :" + daysPart + "]";
}

function buildFirstRemark() {
    return FREE_SERVICE_NOTICE;
}

function buildSecondRemark(user, now = Date.now(), workerConfig = null) {
    /* [FINAL] گارد null */ if (!user) return buildFirstRemark();
    if (isUserInactive(user, now)) {
        return "غیر فعال : " + getInactiveReason(user, now);
    }
    const template = workerConfig?.infoRemarkTemplate || WORKER_CONFIG_DEFAULTS.infoRemarkTemplate;
    return applyRemarkTemplate(template, user, now);
}

async function resolveSubscriptionState(user, env, opts) {
    const firstRemark = buildFirstRemark();
    const workerConfig = env ? await WorkerConfigService.loadSettings(env) : null;
    /* [FINAL] گارد null */ /* نصب تازه: جدول users خالی است و systemUser می‌تواند null باشد */
    if (!user) return {
        inactive: false,
        firstRemark: firstRemark,
        secondRemark: firstRemark,
        workerConfig: workerConfig
    };
    if (isUserRequestLimitExceeded(user, user.username)) {
        return {
            inactive: true,
            firstRemark: firstRemark,
            secondRemark: "غیر فعال : اتمام ریکوئست",
            workerConfig: workerConfig
        };
    }
    if (isUserInactive(user)) {
        return {
            inactive: true,
            firstRemark: firstRemark,
            secondRemark: buildSecondRemark(user, Date.now(), workerConfig),
            workerConfig: workerConfig
        };
    }
    if (env) {
        if (await PanelKillService.isAllServicesOff(env)) {
            return {
                inactive: true,
                firstRemark: firstRemark,
                secondRemark: "غیر فعال : قطع تمامی سرویس‌ها",
                workerConfig: workerConfig
            };
        }
    }
    return {
        inactive: false,
        firstRemark: firstRemark,
        secondRemark: buildSecondRemark(user, Date.now(), workerConfig),
        workerConfig: workerConfig
    };
}

let syncExpiredLastAt = 0;

let syncExpiredRunning = false;

async function syncExpiredUsersStatus(env) {
    const now = Date.now();
    if (syncExpiredRunning) return 0;
    if (now - syncExpiredLastAt < 6e4) return 0;
    syncExpiredRunning = true;
    let changed = 0;
    try {
        const {results: results} = await env.DB.prepare("SELECT * FROM users WHERE is_active = 1").all();
        for (const user of results || []) {
            if (!isUserExpired(user, now)) continue;
            await env.DB.prepare("UPDATE users SET is_active = 0 WHERE username = ? AND is_active = 1").bind(user.username).run();
            changed++;
            if (isVolumeExpired(user) && !user.expired_at) {
                await env.DB.prepare("UPDATE users SET expired_at = ? WHERE username = ? AND expired_at IS NULL").bind(now, user.username).run();
            }
        }
        syncExpiredLastAt = now;
    } catch (e) {
        markD1Outage();
    }
    syncExpiredRunning = false;
    return changed;
}

function getUserExpiredAtMs(user, now = Date.now()) {
    if (!isUserExpired(user, now)) return null;
    const timeExpiryMs = user.expiry_days && user.created_at ? new Date(user.created_at).getTime() + user.expiry_days * 24 * 60 * 60 * 1e3 : null;
    const timeExpired = timeExpiryMs != null && now > timeExpiryMs;
    const volumeExpired = user.limit_gb != null && user.used_gb >= user.limit_gb;
    if (timeExpired && volumeExpired) {
        return Math.max(timeExpiryMs, user.expired_at || 0);
    }
    if (timeExpired) return timeExpiryMs;
    return user.expired_at || now;
}

async function maybeMarkVolumeExpired(env, username) {
    try {
        const user = await env.DB.prepare("SELECT limit_gb, used_gb, expired_at, is_active FROM users WHERE username = ?").bind(username).first();
        if (user && isVolumeExpired(user)) {
            const now = Date.now();
            if (!user.expired_at) {
                await env.DB.prepare("UPDATE users SET expired_at = ?, is_active = 0 WHERE username = ? AND expired_at IS NULL").bind(now, username).run();
            } else if (user.is_active === 1) {
                await env.DB.prepare("UPDATE users SET is_active = 0 WHERE username = ? AND is_active = 1").bind(username).run();
            }
        }
    } catch (e) {}
}

const PANEL_USAGE_KEY = "panel_total_used_gb";

async function initPanelUsageRow(env) {
    try {
        const row = await env.DB.prepare("SELECT value FROM settings WHERE key = ?").bind(PANEL_USAGE_KEY).first();
        if (row) return parseFloat(row.value) || 0;
        const s = await env.DB.prepare("SELECT COALESCE(SUM(used_gb),0) AS total FROM users").first();
        const seed = s ? parseFloat(s.total) || 0 : 0;
        await env.DB.prepare("INSERT OR IGNORE INTO settings (key, value) VALUES (?, ?)").bind(PANEL_USAGE_KEY, String(seed)).run();
        const row2 = await env.DB.prepare("SELECT value FROM settings WHERE key = ?").bind(PANEL_USAGE_KEY).first();
        return row2 ? parseFloat(row2.value) || 0 : seed;
    } catch (e) {
        return 0;
    }
}

async function addPanelUsageGb(env, deltaGb) {
    if (!env || !(deltaGb > 0)) return;
    try {
        const row = await env.DB.prepare("SELECT value FROM settings WHERE key = ?").bind(PANEL_USAGE_KEY).first();
        if (!row) {
            const s = await env.DB.prepare("SELECT COALESCE(SUM(used_gb),0) AS total FROM users").first();
            const seed = s ? parseFloat(s.total) || 0 : 0;
            await env.DB.prepare("INSERT OR IGNORE INTO settings (key, value) VALUES (?, ?)").bind(PANEL_USAGE_KEY, String(seed)).run();
        }
        await env.DB.prepare("UPDATE settings SET value = CAST(COALESCE(CAST(value AS REAL), 0) + ? AS TEXT) WHERE key = ?").bind(deltaGb, PANEL_USAGE_KEY).run();
    } catch (e) {}
}

async function getPanelUsageGb(env) {
    if (!env) return 0;
    return initPanelUsageRow(env);
}

async function commitTrafficDelta(env, username, deltaGb) {
    if (!username || !(deltaGb > 0)) return true;
    await addPanelUsageGb(env, deltaGb);
    try {
        const row = await env.DB.prepare("UPDATE users SET used_gb = used_gb + ? WHERE username = ? RETURNING limit_gb, used_gb, expired_at, is_active").bind(deltaGb, username).first();
        if (row && row.limit_gb != null && row.used_gb >= row.limit_gb) {
            const now = Date.now();
            if (!row.expired_at) {
                await env.DB.prepare("UPDATE users SET expired_at = ?, is_active = 0 WHERE username = ? AND expired_at IS NULL").bind(now, username).run();
            } else if (row.is_active === 1) {
                await env.DB.prepare("UPDATE users SET is_active = 0 WHERE username = ? AND is_active = 1").bind(username).run();
            }
        }
        return true;
    } catch (e) {
        markD1Outage();
        try {
            await env.DB.prepare("UPDATE users SET used_gb = used_gb + ? WHERE username = ?").bind(deltaGb, username).run();
            await maybeMarkVolumeExpired(env, username);
            return true;
        } catch (e2) {
            return false;
        }
    }
}

async function purgeExpiredUsers(env) {
    try {
        const cfg = await WorkerConfigService.loadSettings(env);
        if (!cfg || !cfg.autoDeleteEnabled) return;
        const delayDays = [ 1, 7, 14, 30 ].includes(Number(cfg.autoDeleteDays)) ? Number(cfg.autoDeleteDays) : 1;
        const purgeDelayMs = delayDays * 24 * 60 * 60 * 1e3;
        const {results: results} = await env.DB.prepare("SELECT * FROM users").all();
        const now = Date.now();
        let deleted = 0;
        for (const user of results || []) {
            if (user.is_saved === 1 || isSystemUser(user)) continue;
            if (!isUserExpired(user, now)) continue;
            const volumeExpired = user.limit_gb != null && user.used_gb >= user.limit_gb;
            if (volumeExpired && !user.expired_at) {
                await env.DB.prepare("UPDATE users SET expired_at = ? WHERE username = ? AND expired_at IS NULL").bind(now, user.username).run();
                user.expired_at = now;
            }
            const expiredAt = getUserExpiredAtMs(user, now);
            if (expiredAt != null && now - expiredAt >= purgeDelayMs) {
                await env.DB.prepare("DELETE FROM users WHERE username = ?").bind(user.username).run();
                deleted++;
            }
        }
        if (deleted > 0) {
            try {
                await LogService.addLog(env, "حذف خودکار کانفیگ", deleted + " سرویس منقضی‌شده پس از " + delayDays + " روز از تاریخ انقضا حذف شد");
            } catch (e) {}
        }
    } catch (e) {}
}

function formatVolumeLabel(gb) {
    if (gb == null || gb === undefined) return "نامحدود";
    if (gb < 1) return (gb * 1024).toFixed(0) + " MB";
    const n = gb % 1 === 0 ? gb.toFixed(0) : gb.toFixed(2);
    return n + " GB";
}

function resolveConfigIps(host, userIpsRaw) {
    const userCleanIps = normalizeCleanIpList(userIpsRaw || "", PER_USER_CLEAN_IP_CAP);
    if (!userCleanIps.length) return [ host ];
    const ips = [ host ];
    for (const ip of userCleanIps) {
        if (!ips.some(existing => existing.toLowerCase() === ip.toLowerCase())) {
            ips.push(ip);
        }
    }
    return ips;
}

async function buildNodeTlsConfigLinks(user, host, inactive, env = null) {
    if (inactive || !user) return [];
    const fp = user.fingerprint || WorkerConfigService.getDefaults().fingerprint;
    const remark = user.username;
    const workerConfig = env ? await WorkerConfigService.loadSettings(env) : WorkerConfigService.getDefaults();
    const proto = workerConfig.protocolType === "mixed" ? "vless" : workerConfig.protocolType || "vless";
    return TLS_PORT_LIST.map(portStr => ({
        port: portStr,
        address: host,
        link: WorkerConfigService.buildNodeLink(workerConfig, user, host, portStr, fp, remark, proto, host)
    }));
}

function detectSubscriptionType(url, ua, isSubConverterRequest) {
    if (isSubConverterRequest) return "mixed";
    if (url && url.searchParams.has("target")) return url.searchParams.get("target");
    if (url && (url.searchParams.has("clash") || ua.includes("clash") || ua.includes("meta") || ua.includes("mihomo"))) return "clash";
    if (url && (url.searchParams.has("sb") || url.searchParams.has("singbox") || ua.includes("singbox") || ua.includes("sing-box"))) return "singbox";
    if (url && (url.searchParams.has("surge") || ua.includes("surge"))) return "surge&ver=4";
    if (url && (url.searchParams.has("quanx") || ua.includes("quantumult"))) return "quanx";
    if (url && (url.searchParams.has("loon") || ua.includes("loon"))) return "loon";
    return "mixed";
}

function isSubConverterRequest(request, url, ua) {
    if (!request && !url) return false;
    ua = ua || (request ? String(request.headers.get("User-Agent") || "").toLowerCase() : "");
    return !!(url && (url.searchParams.has("b64") || url.searchParams.has("base64"))) || !!(request && (request.headers.get("subconverter-request") || request.headers.get("subconverter-version"))) || ua.includes("subconverter") || ua.includes("cf-workers-sub");
}

const SubscriptionService = {
    async buildMixedLinks(user, host, env, workerConfig) {
        const proxySettingsBase = await CdnProxyService.loadSettings(env);
        const proxySettingsForRemark = CdnProxyService.buildUserSettings(proxySettingsBase, user);
        const proxyEntries = CdnProxyService.getEffectiveProxyListWithMeta(proxySettingsForRemark);
        const ips = resolveConfigIps(host, user.ips);
        const ports = String(user.port || "443").split(",").map(p => p.trim()).filter(p => p.length > 0);
        const fp = user.fingerprint || workerConfig.fingerprint || WorkerConfigService.getDefaults().fingerprint;
        const links = [];
        const {inactive: inactive, firstRemark: firstRemark, secondRemark: secondRemark} = await resolveSubscriptionState(user, env);
        const tc = WorkerConfigService.getTransportConfig(workerConfig);
        const pathEnc = encodeURIComponent(WorkerConfigService.resolveTransportPathValue(workerConfig));
        const buildFakeLink = remark => {
            const proto = workerConfig.protocolType === "mixed" ? "vless" : workerConfig.protocolType || "vless";
            return proto + "://" + user.uuid + "@127.0.0.1:17?encryption=none&security=none&type=" + WorkerConfigService.getTransportTypeParam(workerConfig) + "&" + tc.hostField + "=" + host + "&" + tc.pathField + "=" + pathEnc + "#" + encodeURIComponent(remark);
        };
        links.push(buildFakeLink(firstRemark));
        links.push(buildFakeLink(secondRemark));
        if (!inactive) {
            let nodeIndex = 0;
            let proxyList = proxyEntries.length ? proxyEntries : [ null ];
            if (proxyEntries.length && proxySettingsForRemark.proxy_sticky_ip !== false) {
                const pinned = proxyEntries[fnv1a32("nexa|" + String(user.uuid || user.username || "anon")) % proxyEntries.length];
                proxyList = [ pinned ];
            }
            ips.forEach(ip => {
                ports.forEach(portStr => {
                    proxyList.forEach(proxyEntry => {
                        const flag = proxyEntry ? flagEmojiFromCountryCode(proxyEntry.cc) : "";
                        const proxyipForRemark = proxyEntry ? proxyEntry.address : proxyEntries[0]?.address || "auto";
                        const remark = applyRemarkTemplate(workerConfig.nodeRemarkTemplate, user, Date.now(), {
                            port: portStr,
                            proxyip: proxyipForRemark,
                            flag: flag
                        });
                        let proto = workerConfig.protocolType || "vless";
                        if (proto === "mixed") {
                            proto = [ "vless", "trojan", "ss" ][nodeIndex % 3];
                        }
                        links.push(WorkerConfigService.buildNodeLink(workerConfig, user, ip, portStr, fp, remark, proto, host, proxyEntry ? proxyEntry.address : null));
                        nodeIndex++;
                    });
                });
            });
        }
        const noise = [ "# System Update Feed: OK", "# Sync Code: " + Math.random().toString(36).slice(2, 10), "# Version: 2.10.1", "# Description: Secure Node Configurations", "" ].join("\n");
        return noise + links.join("\n");
    },
    buildResponseHeaders(workerConfig, subType) {
        const headers = {
            "Access-Control-Allow-Origin": "*",
            "Cache-Control": "no-store"
        };
        if (subType === "clash") headers["Content-Type"] = "application/x-yaml; charset=utf-8"; else if (subType === "singbox") headers["Content-Type"] = "application/json; charset=utf-8"; else headers["Content-Type"] = "text/plain; charset=utf-8";
        if (workerConfig.subName) {
            try {
                headers["Profile-Title"] = "base64:" + btoa(unescape(encodeURIComponent(workerConfig.subName)));
            } catch (e) {}
        }
        if (workerConfig.subUpdateHours) {
            headers["Profile-Update-Interval"] = String(workerConfig.subUpdateHours);
        }
        return headers;
    },
    async generateText(user, host, env = null, request = null, url = null) {
        const workerConfig = env ? await WorkerConfigService.loadSettings(env) : WorkerConfigService.getDefaults();
        const networkSettings = env ? await NetworkSettingsService.loadSettings(env) : NetworkSettingsService.getDefaults();
        const ua = (request ? String(request.headers.get("User-Agent") || "") : "").toLowerCase();
        const converterReq = isSubConverterRequest(request, url, ua);
        const subType = detectSubscriptionType(url, ua, converterReq);
        const mixedContent = await this.buildMixedLinks(user, host, env, workerConfig);
        const headers = this.buildResponseHeaders(workerConfig, subType);
        if (subType === "mixed") {
            const shouldB64 = converterReq || !ua.includes("mozilla") || url && (url.searchParams.has("b64") || url.searchParams.has("base64"));
            const body = shouldB64 ? btoa(unescape(encodeURIComponent(mixedContent))) : mixedContent;
            return new Response(body, {
                headers: headers
            });
        }
        const subPath = workerConfig.subPagePath || WORKER_CONFIG_DEFAULTS.subPagePath;
        const origin = url ? url.protocol + "//" + url.host : "https://" + host;
        const mixedUrl = origin + "/" + subPath + "/" + encodeURIComponent(user.username) + "?target=mixed&b64";
        const converterApi = (workerConfig.subConverterApi || WORKER_CONFIG_DEFAULTS.subConverterApi).replace(/\/$/, "");
        const configUrl = workerConfig.subConfigUrl || WORKER_CONFIG_DEFAULTS.subConfigUrl;
        const emoji = workerConfig.subEmoji ? "true" : "false";
        const scv = workerConfig.skipCertVerify ? "true" : "false";
        const convertUrl = converterApi + "/sub?target=" + encodeURIComponent(subType) + "&url=" + encodeURIComponent(mixedUrl) + "&config=" + encodeURIComponent(configUrl) + "&emoji=" + emoji + "&scv=" + scv;
        let subContent;
        try {
            const res = await fetchWithTimeout(convertUrl, {
                headers: {
                    "User-Agent": "Subconverter for " + subType + " (Nexa Panel)"
                }
            }, 12e3);
            if (!res.ok) throw new Error(res.statusText || String(res.status));
            subContent = await res.text();
        } catch (e) {
            return new Response("Subscription converter error: " + e.message, {
                status: 403,
                headers: {
                    "Content-Type": "text/plain; charset=utf-8"
                }
            });
        }
        if (subType === "singbox") {
            subContent = NetworkSettingsService.applySingboxHotpatch(subContent, networkSettings);
        } else if (subType === "clash") {
            subContent = NetworkSettingsService.applyClashHotpatch(subContent, networkSettings);
        }
        return new Response(subContent, {
            headers: headers
        });
    }
};

async function flushExpiredTraffic(env) {
    const now = Date.now();
    for (const [uname, cachedBytes] of trafficByteCache.entries()) {
        if (cachedBytes <= 0) continue;
        if (dbWriteLock.get(uname)) continue;
        const lastActive = lastActiveWriteAt.get(uname) || 0;
        const activeCount = activeConnCountByUser.get(uname) || 0;
        if (activeCount <= 0 || now - lastActive > 65e3) {
            dbWriteLock.set(uname, true);
            trafficByteCache.set(uname, 0);
            const deltaGb = cachedBytes / (1024 * 1024 * 1024);
            try {
                await commitTrafficDelta(env, uname, deltaGb);
            } catch (e) {} finally {
                dbWriteLock.set(uname, false);
            }
        }
    }
}

async function handleVLESS(env, storedData = null, ctx = null, request = null, storedNetSettings = null) {
    const connectClientIp = request ? getClientIp(request) : "";
    const socketPair = new WebSocketPair;
    const [clientSock, serverSock] = Object.values(socketPair);
    serverSock.accept();
    serverSock.binaryType = "arraybuffer";
    let abuseSlotReleased = false;
    const releaseAbuseSlot = () => {
        if (abuseSlotReleased) return;
        abuseSlotReleased = true;
        try {
            AbuseGuard.releaseWs(connectClientIp || "unknown");
        } catch (e) {}
    };
    let username = null;
    let tickCount = 0;
    let validUUID = null;
    let connBytes = 0;
    let connStart = Date.now();
    function addBytes(bytes) {
        if (bytes <= 0 || !username) return;
        connBytes += bytes;
        let current = trafficByteCache.get(username) || 0;
        trafficByteCache.set(username, current + bytes);
        lastActiveWriteAt.set(username, Date.now());
        if (dbWriteLock.get(username)) return;
        let lastDbWrite = lastDbWriteAt.get(username) || 0;
        let now = Date.now();
        let thresholdBytes = 10 * 1024 * 1024;
        if (current >= thresholdBytes || current > 0 && now - lastDbWrite > 6e4) {
            dbWriteLock.set(username, true);
            let toCommit = trafficByteCache.get(username) || 0;
            if (toCommit <= 0) {
                dbWriteLock.set(username, false);
                return;
            }
            trafficByteCache.set(username, 0);
            lastDbWriteAt.set(username, now);
            let deltaGb = toCommit / (1024 * 1024 * 1024);
            let writeTask = async () => {
                try {
                    await commitTrafficDelta(env, username, deltaGb);
                } catch (e) {} finally {
                    dbWriteLock.set(username, false);
                }
            };
            safeWaitUntil(ctx, writeTask);
        }
    }
    let isOfflineSet = false;
    const setOffline = () => {
        if (isOfflineSet) return;
        isOfflineSet = true;
        releaseAbuseSlot();
        const uname = username;
        const uuid = validUUID;
        const clientIp = connectClientIp;
        const sessionBytes = connBytes;
        const sessionDuration = Date.now() - connStart;
        if (!uname) return;
        let activeCount = activeConnCountByUser.get(uname) || 1;
        activeCount = activeCount - 1;
        if (activeCount <= 0) {
            activeConnCountByUser.delete(uname);
            let cachedBytes = trafficByteCache.get(uname) || 0;
            if (cachedBytes > 0 && !dbWriteLock.get(uname)) {
                dbWriteLock.set(uname, true);
                trafficByteCache.set(uname, 0);
                const deltaGb = cachedBytes / (1024 * 1024 * 1024);
                const writeTask = async () => {
                    try {
                        await commitTrafficDelta(env, uname, deltaGb);
                    } catch (e) {} finally {
                        dbWriteLock.set(uname, false);
                    }
                };
                safeWaitUntil(ctx, writeTask);
            }
        } else {
            activeConnCountByUser.set(uname, activeCount);
        }
        if (uuid && clientIp) {
            const logConnTask = async () => {
                try {} catch (e) {}
            };
            safeWaitUntil(ctx, logConnTask);
        }
    };
    const heartbeat = setInterval(async () => {
        if (serverSock.readyState === 1) {
            try {
                serverSock.send(new Uint8Array(0));
                if (!validUUID) return;
                tickCount++;
                if (tickCount >= 4) {
                    tickCount = 0;
                    const user = await lookupVlessUser(env, validUUID);
                    if (user && user.__d1Unavailable) {
                        return;
                    }
                    let isExpired = false;
                    if (!user || user.is_active === 0) {
                        isExpired = true;
                    } else {
                        try {
                            if (await PanelKillService.isAllServicesOff(env)) isExpired = true;
                        } catch (e) {}
                    }
                    if (!isExpired) {
                        if (user.limit_gb && user.used_gb >= user.limit_gb) {
                            isExpired = true;
                        }
                        if (user.expiry_days && user.created_at) {
                            const created = new Date(user.created_at);
                            const expiryDate = new Date(created.getTime() + user.expiry_days * 24 * 60 * 60 * 1e3);
                            if (new Date > expiryDate) {
                                isExpired = true;
                            }
                        }
                    }
                    if (isExpired) {
                        try {
                            await env.DB.prepare("UPDATE users SET is_active = 0, last_active = 0 WHERE uuid = ?").bind(validUUID).run();
                        } catch (e2) {}
                        clearInterval(heartbeat);
                        closeSocketQuietly(serverSock);
                        return;
                    }
                    if (username) {
                        const now = Date.now();
                        const lastRecorded = lastActiveWriteAt.get(username) || 0;
                        if (now - lastRecorded > 6e4) {
                            lastActiveWriteAt.set(username, now);
                            try {
                                await env.DB.prepare("UPDATE users SET last_active = ? WHERE username = ?").bind(now, username).run();
                            } catch (e3) {}
                        }
                    }
                }
            } catch (e) {}
        } else {
            clearInterval(heartbeat);
        }
    }, 15e3);
    let remoteConnWrapper = {
        socket: null,
        connectingPromise: null,
        retryConnect: null
    };
    let reqUUID = null;
    let isHeaderParsed = false;
    let isDnsQuery = false;
    let chunkBuffer = new Uint8Array(0);
    let proxySettings = storedData || {
        proxy_ips: [],
        defaultProxyIPs: FALLBACK_PROXY_HOSTS.slice()
    };
    let netSettings = storedNetSettings || null;
    let activeProxyIp = "";
    let proxyEnableFallback = true;
    let proxyStickySeed = "";
    let udpFlowMode = null;
    let wsChain = Promise.resolve();
    let wsStopped = false, wsFailed = false, wsFinished = false;
    let swappingSocket = false;
    const attachClosedHook = sock => {
        if (!sock || !sock.closed) return;
        sock.closed.catch(() => {}).finally(() => {
            if (swappingSocket || wsFinished) return;
            closeSocketQuietly(serverSock);
        });
    };
    const swapRemoteSocket = async makeSocket => {
        const old = remoteConnWrapper.socket;
        swappingSocket = true;
        try {
            if (old) old.close();
        } catch (e) {}
        remoteConnWrapper.socket = null;
        let next = null;
        try {
            next = await makeSocket();
            remoteConnWrapper.socket = next;
        } finally {
            swappingSocket = false;
        }
        return next;
    };
    let wsQueueBytes = 0, wsQueueItems = 0;
    let currentSocketWriter = null, activeRemoteWriter = null;
    const releaseRemoteWriter = () => {
        if (activeRemoteWriter) {
            try {
                activeRemoteWriter.releaseLock();
            } catch (e) {}
            activeRemoteWriter = null;
        }
        currentSocketWriter = null;
    };
    const getRemoteWriter = () => {
        const s = remoteConnWrapper.socket;
        if (!s) return null;
        if (s !== currentSocketWriter) {
            releaseRemoteWriter();
            currentSocketWriter = s;
            activeRemoteWriter = s.writable.getWriter();
        }
        return activeRemoteWriter;
    };
    const upstreamQueue = createUpstreamQueue({
        getWriter: getRemoteWriter,
        releaseWriter: releaseRemoteWriter,
        retryConnect: async () => {
            if (typeof remoteConnWrapper.retryConnect === "function") {
                await remoteConnWrapper.retryConnect();
            }
        },
        closeConnection: () => {
            try {
                remoteConnWrapper.socket?.close();
            } catch (e) {}
            closeSocketQuietly(serverSock);
        },
        name: "VlessWSQueue"
    });
    let udpRelaySocket = null;
    let udpRelayWriter = null;
    const startUdpRelay = async (targetAddr, targetPort, firstPayload, header) => {
        try {
            if (AbuseGuard.destinationVerdict(targetAddr, targetPort, env).blocked) {
                AbuseGuard.noteBlocked(targetAddr, targetPort, "udp-policy");
                udpFlowMode = "ignore";
                return;
            }
            await AbuseGuard.dialSlot(env);
            let sock = null;
            try {
                const connectFn = await loadTcpConnect();
                sock = connectFn({
                    hostname: targetAddr,
                    port: targetPort,
                    transport: "datagrams"
                });
                await Promise.race([ sock.opened, new Promise((_, reject) => setTimeout(() => reject(new Error("udp open timeout")), TCP_DIAL_TIMEOUT_MS)) ]);
            } finally {
                AbuseGuard.releaseDial();
            }
            udpRelaySocket = sock;
            udpRelayWriter = sock.writable.getWriter();
            if (firstPayload && firstPayload.byteLength) {
                const first = convertToUint8Array(firstPayload);
                if (first.byteLength) await udpRelayWriter.write(first);
            }
            pumpUdpRelay(sock, header);
        } catch (e) {
            udpFlowMode = "ignore";
            await finishUdpRelay();
        }
    };
    const finishUdpRelay = async () => {
        try {
            if (udpRelayWriter) udpRelayWriter.releaseLock();
        } catch (e) {}
        udpRelayWriter = null;
        const sock = udpRelaySocket;
        udpRelaySocket = null;
        try {
            if (sock) sock.close();
        } catch (e) {}
    };
    const pumpUdpRelay = async (sock, header) => {
        let sentHeader = false;
        let reader = null;
        try {
            reader = sock.readable.getReader();
            for (;;) {
                const {done: done, value: value} = await reader.read();
                if (done) break;
                if (!value || !value.byteLength || serverSock.readyState !== WebSocket.OPEN) continue;
                addBytes(value.byteLength);
                if (!sentHeader && header && header.length) {
                    sentHeader = true;
                    const merged = new Uint8Array(header.length + value.byteLength);
                    merged.set(header, 0);
                    merged.set(value, header.length);
                    serverSock.send(merged);
                } else {
                    serverSock.send(value);
                }
            }
        } catch (e) {} finally {
            try {
                if (reader) reader.releaseLock();
            } catch (e) {}
            if (udpRelaySocket === sock) await finishUdpRelay();
            udpFlowMode = "ignore";
        }
    };
    const udpRelayWrite = async chunk => {
        if (!udpRelayWriter) return;
        try {
            const data = convertToUint8Array(chunk);
            if (!data.byteLength || data.byteLength > 1280) {
                if (data.byteLength > 1280) {
                    for (let off = 0; off < data.byteLength; off += 1200) {
                        await udpRelayWriter.write(data.subarray(off, off + 1200));
                    }
                }
                return;
            }
            await udpRelayWriter.write(data);
        } catch (e) {}
    };
    const writeToRemote = async (chunk, allowRetry = true) => {
        if (UPSTREAM_WAIT_FOR_FLUSH) return upstreamQueue.writeAndAwait(chunk, allowRetry);
        return upstreamQueue.write(chunk, allowRetry);
    };
    const processWsMessage = async chunk => {
        const bytes = chunk.byteLength || 0;
        await addBytes(bytes);
        if (udpFlowMode === "ignore") return;
        if (isDnsQuery) {
            await forwardVlessUDP(chunk, serverSock, null, addBytes, env);
            return;
        }
        if (udpFlowMode === "relay") {
            await udpRelayWrite(chunk);
            return;
        }
        if (await writeToRemote(chunk)) return;
        if (!isHeaderParsed) {
            chunkBuffer = concatBytes(chunkBuffer, chunk);
            if (chunkBuffer.byteLength < 24) return;
            reqUUID = extractUUIDFromVless(chunkBuffer);
            if (!reqUUID) {
                serverSock.close();
                return;
            }
            let user = await lookupVlessUser(env, reqUUID);
            let d1FailOpen = !!(user && user.__d1Unavailable);
            if (!d1FailOpen) {
                if (!user || user.is_active === 0) {
                    serverSock.close();
                    return;
                }
                try {
                    if (await PanelKillService.isAllServicesOff(env)) {
                        serverSock.close();
                        return;
                    }
                } catch (e) {}
                if (user.limit_gb && user.used_gb >= user.limit_gb) {
                    serverSock.close();
                    return;
                }
                if (user.expiry_days && user.created_at) {
                    const created = new Date(user.created_at);
                    const expiryDate = new Date(created.getTime() + user.expiry_days * 24 * 60 * 60 * 1e3);
                    if (new Date > expiryDate) {
                        try {
                            await env.DB.prepare("UPDATE users SET is_active = 0, last_active = 0 WHERE uuid = ?").bind(reqUUID).run();
                        } catch (e) {}
                        serverSock.close();
                        return;
                    }
                }
            }
            proxySettings = d1FailOpen ? proxySettings : CdnProxyService.buildUserSettings(proxySettings, user);
            const proxyState = CdnProxyService.getActiveProxyIp(proxySettings, request, validUUID || reqUUID || connectClientIp);
            activeProxyIp = proxyState.proxyIp;
            proxyEnableFallback = proxyState.enableFallback;
            proxyStickySeed = fnv1a32("nexa|" + (validUUID || reqUUID || connectClientIp || "anon")).toString(36);
            netSettings = Object.assign({}, netSettings || {}, {
                proxyRoutingMode: proxySettings.proxy_routing_mode
            });
            validUUID = reqUUID;
            username = d1FailOpen ? null : user.username;
            isHeaderParsed = true;
            if (!d1FailOpen) {
                if (isUserRequestLimitExceeded(user, username)) {
                    serverSock.close();
                    return;
                }
                trackUserRequest(username, env, ctx);
                let activeCount = activeConnCountByUser.get(username) || 0;
                activeConnCountByUser.set(username, activeCount + 1);
                if (activeCount === 0) {
                    const setOnlineTask = async () => {
                        try {
                            const now = Date.now();
                            lastActiveWriteAt.set(username, now);
                            await env.DB.prepare("UPDATE users SET last_active = ? WHERE username = ?").bind(now, username).run();
                        } catch (e) {}
                    };
                    safeWaitUntil(ctx, setOnlineTask);
                }
            }
            try {
                let offset = 17;
                const optLen = chunkBuffer[offset++];
                offset += optLen;
                const cmd = chunkBuffer[offset++];
                const port = chunkBuffer[offset++] << 8 | chunkBuffer[offset++];
                const addrType = chunkBuffer[offset++];
                let addr = "";
                if (addrType === 1) {
                    addr = `${chunkBuffer[offset++]}.${chunkBuffer[offset++]}.${chunkBuffer[offset++]}.${chunkBuffer[offset++]}`;
                } else if (addrType === 2) {
                    const domainLen = chunkBuffer[offset++];
                    addr = (new TextDecoder).decode(chunkBuffer.slice(offset, offset + domainLen));
                    offset += domainLen;
                } else if (addrType === 3) {
                    if (IPV6_UPSTREAM_ENABLED) {
                        addr = formatIpv6Groups(chunkBuffer, offset);
                        offset += 16;
                    } else {
                        offset += 16;
                        addr = "ipv6-unsupported";
                    }
                }
                if (addr && addr !== "ipv6-unsupported") {
                    const abuseVerdict = AbuseGuard.destinationVerdict(addr, port, env);
                    if (abuseVerdict.blocked) {
                        AbuseGuard.noteBlocked(addr, port, abuseVerdict.reason);
                        closeSocketQuietly(serverSock);
                        return;
                    }
                    const blockSettings = await DomainBlockService.getSettings(env);
                    const manualBlocked = blockSettings.enabled && DomainBlockService.isBlocked(addr, blockSettings.domains);
                    const policyResult = manualBlocked ? {
                        blocked: false
                    } : await ContentPolicyService.checkBlocked(env, addr);
                    if (manualBlocked || policyResult.blocked) {
                        serverSock.close();
                        return;
                    }
                }
                const rawData = chunkBuffer.slice(offset);
                const respHeader = new Uint8Array([ chunkBuffer[0], 0 ]);
                if (cmd === 2) {
                    const blockQuic = !!(netSettings && netSettings.blockQUIC);
                    if (port === 53) {
                        isDnsQuery = true;
                        await forwardVlessUDP(rawData, serverSock, respHeader, addBytes, env);
                    } else if (UDP_RELAY_ENABLED && !blockQuic && UDP_RELAY_PORTS.includes(port) && addr && addr !== "ipv6-unsupported") {
                        udpFlowMode = "relay";
                        await startUdpRelay(addr, port, rawData, respHeader);
                    } else {
                        udpFlowMode = "ignore";
                        closeSocketQuietly(serverSock);
                    }
                    return;
                }
                const connectTCP = async (dataPayload = null, useFallback = true) => {
                    if (remoteConnWrapper.connectingPromise) {
                        await remoteConnWrapper.connectingPromise;
                        return;
                    }
                    const establishConnection = async (targetAddr, targetPort, payload, allowProxyRetry) => {
                        const route = await resolveUpstreamRoute(targetAddr, targetPort, netSettings, !!activeProxyIp, allowProxyRetry);
                        let s = null;
                        if (route === "proxy") {
                            s = await connectViaActiveProxy(activeProxyIp, targetAddr, targetPort, validUUID || reqUUID, proxyEnableFallback, payload, proxyStickySeed, true);
                        } else if (route === "direct") {
                            try {
                                s = await connectDirect(targetAddr, targetPort, payload);
                            } catch (err) {
                                if (activeProxyIp && allowProxyRetry) {
                                    try {
                                        s = await connectViaActiveProxy(activeProxyIp, targetAddr, targetPort, validUUID || reqUUID, proxyEnableFallback, payload, proxyStickySeed, false);
                                    } catch (proxyErr) {
                                        throw err;
                                    }
                                } else {
                                    throw err;
                                }
                            }
                        } else {
                            const tasks = [];
                            if (activeProxyIp && allowProxyRetry) {
                                tasks.push(connectViaActiveProxy(activeProxyIp, targetAddr, targetPort, validUUID || reqUUID, false, null, proxyStickySeed, false).then(sock => ({
                                    socket: sock,
                                    viaProxy: true
                                })));
                            }
                            tasks.push(connectDirectSingle(targetAddr, targetPort, null).then(sock => ({
                                socket: sock,
                                viaProxy: false
                            })));
                            let win = null;
                            try {
                                win = await Promise.any(tasks);
                            } catch (err) {
                                if (activeProxyIp) {
                                    s = await connectViaActiveProxy(activeProxyIp, targetAddr, targetPort, validUUID || reqUUID, proxyEnableFallback, payload, proxyStickySeed, true);
                                } else {
                                    throw err;
                                }
                            }
                            if (win) {
                                s = win.socket;
                                for (const t of tasks) {
                                    t.then(r => {
                                        if (r.socket !== s) {
                                            try {
                                                r.socket.close();
                                            } catch (e2) {}
                                        }
                                    }).catch(() => {});
                                }
                                await writeInitialTcpData(s, payload);
                            }
                        }
                        remoteConnWrapper.socket = s;
                        attachClosedHook(s);
                        const retryWithProxy = useFallback && allowProxyRetry && activeProxyIp ? async () => {
                            try {
                                const retrySocket = await swapRemoteSocket(() => connectViaActiveProxy(activeProxyIp, addr, port, validUUID || reqUUID, proxyEnableFallback, null, proxyStickySeed, false));
                                if (!retrySocket) return;
                                attachClosedHook(retrySocket);
                                connectStreams(retrySocket, serverSock, respHeader, null, b => {
                                    addBytes(b);
                                });
                            } catch (e) {}
                        } : null;
                        connectStreams(s, serverSock, respHeader, retryWithProxy, b => {
                            addBytes(b);
                        });
                    };
                    const task = (async () => {
                        await establishConnection(addr, port, dataPayload, true);
                    })();
                    remoteConnWrapper.connectingPromise = task;
                    try {
                        await task;
                    } finally {
                        if (remoteConnWrapper.connectingPromise === task) {
                            remoteConnWrapper.connectingPromise = null;
                        }
                    }
                };
                remoteConnWrapper.retryConnect = async () => {
                    if (!activeProxyIp) return;
                    try {
                        const s = await swapRemoteSocket(() => connectViaActiveProxy(activeProxyIp, addr, port, validUUID || reqUUID, proxyEnableFallback, null, proxyStickySeed, false));
                        if (!s) return;
                        attachClosedHook(s);
                        connectStreams(s, serverSock, respHeader, null, b => {
                            addBytes(b);
                        });
                    } catch (e) {}
                };
                await connectTCP(rawData, true);
            } catch (e) {
                serverSock.close();
            }
        }
    };
    const handleWsError = err => {
        if (wsFailed) return;
        wsFailed = true;
        wsStopped = true;
        wsQueueBytes = 0;
        wsQueueItems = 0;
        upstreamQueue.clear();
        releaseRemoteWriter();
        closeSocketQuietly(serverSock);
        setOffline();
    };
    const pushToChain = task => {
        wsChain = wsChain.then(task).catch(handleWsError);
    };
    serverSock.addEventListener("message", event => {
        try {
            if (wsStopped || wsFailed) return;
            const data = event && event.data;
            const size = data && data.byteLength || 0;
            const nextBytes = wsQueueBytes + size;
            const nextItems = wsQueueItems + 1;
            if (nextBytes > UPSTREAM_QUEUE_MAX_BYTES || nextItems > UPSTREAM_QUEUE_MAX_ITEMS) {
                if (nextBytes > UPSTREAM_QUEUE_MAX_BYTES * 2 || nextItems > UPSTREAM_QUEUE_MAX_ITEMS * 2) {
                    handleWsError(new Error("ws queue overflow"));
                    return;
                }
                pushToChain(async () => {
                    await upstreamQueue.awaitLowWater(UPSTREAM_QUEUE_DRAIN_TIMEOUT_MS);
                });
            }
            wsQueueBytes = nextBytes;
            wsQueueItems = nextItems;
            const messageData = data;
            pushToChain(async () => {
                wsQueueBytes = Math.max(0, wsQueueBytes - size);
                wsQueueItems = Math.max(0, wsQueueItems - 1);
                if (wsFailed) return;
                await processWsMessage(messageData);
            });
        } catch (e) {
            handleWsError(e);
        }
    });
    serverSock.addEventListener("close", () => {
        try {
            releaseAbuseSlot();
            clearInterval(heartbeat);
            try {
                if (udpRelaySocket) udpRelaySocket.close();
            } catch (e) {}
            udpRelaySocket = null;
            udpRelayWriter = null;
            closeSocketQuietly(serverSock);
            setOffline();
            if (wsFinished) return;
            wsFinished = true;
            wsStopped = true;
            pushToChain(async () => {
                if (wsFailed) return;
                await upstreamQueue.awaitEmpty();
                releaseRemoteWriter();
            });
        } catch (e) {}
    });
    serverSock.addEventListener("error", err => {
        try {
            handleWsError(err);
        } catch (e) {}
    });
    return new Response(null, {
        status: 101,
        webSocket: clientSock
    });
}

async function getCfUsage(env) {
    const cfToken = await DbService.getCfToken(env);
    const cfAccountId = await DbService.getCfAccountIdResolved(env);
    if (!cfToken || !cfAccountId) return {
        today: 0,
        total: 0
    };
    try {
        const now = new Date;
        const startOfDay = new Date(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()).toISOString();
        const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1e3).toISOString();
        const q = `query {\n      viewer {\n        accounts(filter: {accountTag: "${cfAccountId}"}) {\n          today: workersInvocationsAdaptive(limit: 10, filter: {datetime_geq: "${startOfDay}"}) {\n            sum { requests }\n          }\n          total: workersInvocationsAdaptive(limit: 10, filter: {datetime_geq: "${thirtyDaysAgo}"}) {\n            sum { requests }\n          }\n        }\n      }\n    }`;
        const res = await fetchWithTimeout("https://api.cloudflare.com/client/v4/graphql", {
            method: "POST",
            headers: {
                Authorization: "Bearer " + cfToken,
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                query: q
            })
        }, 5e3);
        const j = await res.json();
        const acc = j?.data?.viewer?.accounts?.[0];
        const todayReqs = acc?.today?.[0]?.sum?.requests || 0;
        const totalReqs = acc?.total?.[0]?.sum?.requests || todayReqs;
        return {
            today: todayReqs,
            total: totalReqs
        };
    } catch (e) {
        return {
            today: 0,
            total: 0
        };
    }
}

function formatIpv6Groups(bytes, start) {
    const g = [];
    for (let i = 0; i < 16; i += 2) g.push((bytes[start + i] << 8 | bytes[start + i + 1]) & 65535);
    let bestStart = -1, bestLen = 0, curStart = -1, curLen = 0;
    for (let i = 0; i < 8; i++) {
        if (g[i] === 0) {
            if (curStart < 0) curStart = i;
            curLen = i - curStart + 1;
            if (curLen > bestLen) {
                bestLen = curLen;
                bestStart = curStart;
            }
        } else {
            curStart = -1;
            curLen = 0;
        }
    }
    if (bestLen < 2) {
        return g.map(x => x.toString(16)).join(":");
    }
    const head = g.slice(0, bestStart).map(x => x.toString(16)).join(":");
    const tail = g.slice(bestStart + bestLen).map(x => x.toString(16)).join(":");
    return (head ? head : "") + "::" + (tail ? tail : "");
}

function isIPv4(value) {
    const parts = String(value || "").split(".");
    return parts.length === 4 && parts.every(part => /^\d{1,3}$/.test(part) && Number(part) >= 0 && Number(part) <= 255);
}

function flagEmojiFromCountryCode(cc) {
    const code = String(cc || "").trim().toUpperCase();
    if (!/^[A-Z]{2}$/.test(code)) return "";
    const codePoints = code.split("").map(ch => 127397 + ch.charCodeAt(0));
    try {
        return String.fromCodePoint(...codePoints);
    } catch (e) {
        return "";
    }
}

function stripIPv6Brackets(hostname = "") {
    const host = String(hostname || "").trim();
    return host.startsWith("[") && host.endsWith("]") ? host.slice(1, -1) : host;
}

function isIPHostname(hostname = "") {
    const host = stripIPv6Brackets(hostname);
    if (isIPv4(host)) return true;
    if (!host.includes(":")) return false;
    try {
        new URL(`http://[${host}]/`);
        return true;
    } catch (e) {
        return false;
    }
}

function convertToUint8Array(data) {
    if (data instanceof Uint8Array) return data;
    if (data instanceof ArrayBuffer) return new Uint8Array(data);
    if (ArrayBuffer.isView(data)) return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
    return new Uint8Array(data || 0);
}

function concatBytes(...chunkList) {
    const chunks = chunkList.map(convertToUint8Array);
    const total = chunks.reduce((sum, c) => sum + c.byteLength, 0);
    const result = new Uint8Array(total);
    let offset = 0;
    for (const c of chunks) {
        result.set(c, offset);
        offset += c.byteLength;
    }
    return result;
}

function closeSocketQuietly(socket) {
    try {
        if (socket.readyState === WebSocket.OPEN || socket.readyState === WebSocket.CLOSING) {
            socket.close();
        }
    } catch (e) {}
}

async function fetchWithDeadline(url, options, timeoutMs) {
    const controller = new AbortController;
    const timer = setTimeout(() => {
        try {
            controller.abort();
        } catch (e) {}
    }, timeoutMs);
    try {
        const opts = Object.assign({}, options || {});
        const headers = new Headers(opts.headers || {});
        if (!headers.has("User-Agent")) headers.set("User-Agent", NEXA_USER_AGENT);
        if (!headers.has("Accept")) headers.set("Accept", "*/*");
        opts.headers = headers;
        return await fetch(url, Object.assign(opts, {
            signal: controller.signal
        }));
    } finally {
        clearTimeout(timer);
    }
}

async function dohQuery(domain, recordType) {
    return await dohQueryWithResolvers(domain, recordType, [ DOH_RESOLVER_URL ].concat(DOH_RESOLVER_BACKUP_URLS));
}

async function dohQueryWithResolvers(domain, recordType, resolvers) {
    const cacheKey = `${domain}:${recordType}`;
    if (dnsAnswerCache.has(cacheKey)) {
        const cached = dnsAnswerCache.get(cacheKey);
        if (Date.now() < cached.expires) return cached.data;
        dnsAnswerCache.delete(cacheKey);
    }
    for (let attempt = 0; attempt < resolvers.length; attempt++) {
        try {
            const answers = await dohQueryOnce(domain, recordType, resolvers[attempt]);
            dnsAnswerCache.set(cacheKey, {
                data: answers,
                expires: Date.now() + (answers.length ? dnsAnswerCache_TTL : dnsNegativeCache_TTL)
            });
            return answers;
        } catch (e) {}
    }
    return [];
}

async function dohQueryOnce(domain, recordType, resolverUrl) {
    try {
        const typeMap = {
            A: 1,
            AAAA: 28,
            TXT: 16
        };
        const qtype = typeMap[recordType.toUpperCase()] || 1;
        const encodeDomain = name => {
            const parts = name.endsWith(".") ? name.slice(0, -1).split(".") : name.split(".");
            const bufs = [];
            for (const label of parts) {
                const enc = (new TextEncoder).encode(label);
                bufs.push(new Uint8Array([ enc.length ]), enc);
            }
            bufs.push(new Uint8Array([ 0 ]));
            return concatBytes(...bufs);
        };
        const qname = encodeDomain(domain);
        const query = new Uint8Array(12 + qname.length + 4 + 11);
        const qview = new DataView(query.buffer);
        qview.setUint16(0, crypto.getRandomValues(new Uint16Array(1))[0]);
        qview.setUint16(2, 256);
        qview.setUint16(4, 1);
        qview.setUint16(6, 1);
        query.set(qname, 12);
        qview.setUint16(12 + qname.length, qtype);
        qview.setUint16(12 + qname.length + 2, 1);
        let ar = 12 + qname.length + 4;
        qview.setUint8(ar, 0);
        qview.setUint16(ar + 1, 41);
        qview.setUint16(ar + 3, DOH_EDNS_BUFSIZE);
        qview.setUint32(ar + 5, 0);
        qview.setUint16(ar + 9, 0);
        const response = await fetchWithDeadline(resolverUrl, {
            method: "POST",
            headers: {
                "Content-Type": "application/dns-message",
                Accept: "application/dns-message"
            },
            body: query
        }, DOH_QUERY_TIMEOUT_MS);
        if (!response || !response.ok) throw new Error("doh status " + (response ? response.status : "timeout"));
        const buf = new Uint8Array(await response.arrayBuffer());
        const dv = new DataView(buf.buffer);
        const qdcount = dv.getUint16(4);
        const ancount = dv.getUint16(6);
        const parseName = pos => {
            const labels = [];
            let p = pos, jumped = false, endPos = -1, safe = 128;
            while (p < buf.length && safe-- > 0) {
                const len = buf[p];
                if (len === 0) {
                    if (!jumped) endPos = p + 1;
                    break;
                }
                if ((len & 192) === 192) {
                    if (!jumped) endPos = p + 2;
                    p = (len & 63) << 8 | buf[p + 1];
                    jumped = true;
                    continue;
                }
                labels.push((new TextDecoder).decode(buf.slice(p + 1, p + 1 + len)));
                p += len + 1;
            }
            if (endPos === -1) endPos = p + 1;
            return [ labels.join("."), endPos ];
        };
        let offset = 12;
        for (let i = 0; i < qdcount; i++) {
            const [, end] = parseName(offset);
            offset = Number(end) + 4;
        }
        const answers = [];
        for (let i = 0; i < ancount && offset < buf.length; i++) {
            const [name, nameEnd] = parseName(offset);
            offset = Number(nameEnd);
            const type = dv.getUint16(offset);
            offset += 2;
            offset += 2;
            const ttl = dv.getUint32(offset);
            offset += 4;
            const rdlen = dv.getUint16(offset);
            offset += 2;
            const rdata = buf.slice(offset, offset + rdlen);
            offset += rdlen;
            let data;
            if (type === 1 && rdlen === 4) {
                data = `${rdata[0]}.${rdata[1]}.${rdata[2]}.${rdata[3]}`;
            } else if (type === 28 && rdlen === 16) {
                const segs = [];
                for (let j = 0; j < 16; j += 2) segs.push((rdata[j] << 8 | rdata[j + 1]).toString(16));
                data = segs.join(":");
            } else if (type === 16) {
                let tOff = 0;
                const parts = [];
                while (tOff < rdlen) {
                    const tLen = rdata[tOff++];
                    parts.push((new TextDecoder).decode(rdata.slice(tOff, tOff + tLen)));
                    tOff += tLen;
                }
                data = parts.join("");
            } else {
                data = Array.from(rdata).map(b => b.toString(16).padStart(2, "0")).join("");
            }
            answers.push({
                name: name,
                type: type,
                TTL: ttl,
                data: data
            });
        }
        if (!answers.length && dv.byteLength >= 4 && dv.getUint16(2) & 2) throw new Error("doh truncated");
        return answers;
    } catch (e) {
        throw e;
    }
}

function createUpstreamQueue({getWriter: getWriter, releaseWriter: releaseWriter, retryConnect: retryConnect, closeConnection: closeConnection, name: name = "UpstreamQueue"}) {
    let chunks = [];
    let head = 0;
    let queuedBytes = 0;
    let draining = false;
    let closed = false;
    let bundleBuffer = null;
    let idleResolvers = [];
    let activeCompletions = null;
    const settleCompletions = (completions, err = null) => {
        if (!completions) return;
        for (const comp of completions) {
            if (comp) {
                if (err) comp.reject(err); else comp.resolve();
            }
        }
    };
    const rejectQueued = err => {
        for (let i = head; i < chunks.length; i++) {
            const item = chunks[i];
            if (item && item.completions) settleCompletions(item.completions, err);
        }
    };
    const compact = () => {
        if (head > 32 && head * 2 >= chunks.length) {
            chunks = chunks.slice(head);
            head = 0;
        }
    };
    const resolveIdle = () => {
        if (queuedBytes || draining || !idleResolvers.length) return;
        const resolvers = idleResolvers;
        idleResolvers = [];
        for (const resolve of resolvers) resolve();
    };
    const clear = (err = null) => {
        const closeErr = err || (closed ? new Error(`${name}: queue closed`) : null);
        if (closeErr) {
            rejectQueued(closeErr);
            settleCompletions(activeCompletions, closeErr);
            activeCompletions = null;
        }
        chunks = [];
        head = 0;
        queuedBytes = 0;
        resolveIdle();
    };
    const shift = () => {
        if (head >= chunks.length) return null;
        const item = chunks[head];
        chunks[head++] = undefined;
        queuedBytes -= item.chunk.byteLength;
        compact();
        return item;
    };
    const bundle = () => {
        const first = shift();
        if (!first) return null;
        if (head >= chunks.length || first.chunk.byteLength >= UPSTREAM_BUNDLE_TARGET_BYTES) return first;
        let byteLength = first.chunk.byteLength;
        let end = head;
        let allowRetry = first.allowRetry;
        let completions = first.completions || null;
        while (end < chunks.length) {
            const next = chunks[end];
            const nextLength = byteLength + next.chunk.byteLength;
            if (nextLength > UPSTREAM_BUNDLE_TARGET_BYTES) break;
            byteLength = nextLength;
            allowRetry = allowRetry && next.allowRetry;
            if (next.completions) completions = completions ? completions.concat(next.completions) : next.completions;
            end++;
        }
        if (end === head) return first;
        const output = bundleBuffer ||= new Uint8Array(UPSTREAM_BUNDLE_TARGET_BYTES);
        output.set(first.chunk);
        let offset = first.chunk.byteLength;
        while (head < end) {
            const next = chunks[head];
            chunks[head++] = undefined;
            queuedBytes -= next.chunk.byteLength;
            output.set(next.chunk, offset);
            offset += next.chunk.byteLength;
        }
        compact();
        return {
            chunk: output.subarray(0, byteLength),
            allowRetry: allowRetry,
            completions: completions
        };
    };
    const drain = async () => {
        if (draining || closed) return;
        draining = true;
        try {
            for (;;) {
                if (closed) break;
                const item = bundle();
                if (!item) break;
                let writer = getWriter();
                if (!writer) throw new Error(`${name}: remote writer unavailable`);
                const completions = item.completions || null;
                activeCompletions = completions;
                try {
                    try {
                        await writer.write(item.chunk);
                    } catch (err) {
                        releaseWriter?.();
                        if (!item.allowRetry || typeof retryConnect !== "function") throw err;
                        await retryConnect();
                        writer = getWriter();
                        if (!writer) throw err;
                        await writer.write(item.chunk);
                    }
                    settleCompletions(completions);
                } catch (err) {
                    settleCompletions(completions, err);
                    throw err;
                } finally {
                    if (activeCompletions === completions) activeCompletions = null;
                }
            }
        } catch (err) {
            closed = true;
            clear(err);
            try {
                closeConnection?.(err);
            } catch (_) {}
        } finally {
            draining = false;
            if (!closed && head < chunks.length) queueMicrotask(drain); else resolveIdle();
        }
    };
    const enqueue = (data, allowRetry = true, waitForFlush = false) => {
        if (closed) return false;
        if (!getWriter()) return false;
        const chunk = convertToUint8Array(data);
        if (!chunk.byteLength) return true;
        const nextBytes = queuedBytes + chunk.byteLength;
        const nextItems = chunks.length - head + 1;
        if (nextBytes > UPSTREAM_QUEUE_MAX_BYTES || nextItems > UPSTREAM_QUEUE_MAX_ITEMS) {
            closed = true;
            const err = Object.assign(new Error(`${name}: upload queue overflow (${nextBytes}B/${nextItems})`), {
                isQueueOverflow: true
            });
            clear(err);
            try {
                closeConnection?.(err);
            } catch (_) {}
            throw err;
        }
        let completionPromise = null;
        let completions = null;
        if (waitForFlush) {
            completions = [];
            completionPromise = new Promise((resolve, reject) => completions.push({
                resolve: resolve,
                reject: reject
            }));
        }
        chunks.push({
            chunk: chunk,
            allowRetry: allowRetry,
            completions: completions
        });
        queuedBytes = nextBytes;
        if (!draining) queueMicrotask(drain);
        return waitForFlush ? completionPromise.then(() => true) : true;
    };
    return {
        write(data, allowRetry = true) {
            return enqueue(data, allowRetry, false);
        },
        writeAndAwait(data, allowRetry = true) {
            return enqueue(data, allowRetry, true);
        },
        async awaitEmpty() {
            if (!queuedBytes && !draining) return;
            await new Promise(resolve => idleResolvers.push(resolve));
        },
        async awaitLowWater(timeoutMs = 4e3) {
            if (queuedBytes <= UPSTREAM_QUEUE_LOW_WATER_BYTES) return;
            await new Promise(resolve => {
                let settled = false;
                const done = () => {
                    if (!settled) {
                        settled = true;
                        resolve();
                    }
                };
                const check = () => {
                    if (queuedBytes <= UPSTREAM_QUEUE_LOW_WATER_BYTES || closed) {
                        done();
                        return;
                    }
                    setTimeout(check, 10);
                };
                setTimeout(done, timeoutMs);
                check();
            });
        },
        clear() {
            closed = true;
            clear();
        }
    };
}

function createDownstreamSender(webSocket, headerData = null) {
    const packetCap = DOWNSTREAM_CHUNK_BYTES;
    const tailBytes = DOWNSTREAM_CHUNK_TAIL_MIN;
    const lowWaterBytes = Math.max(4096, tailBytes << 3);
    let header = headerData;
    let pendingBuffer = new Uint8Array(packetCap);
    let pendingBytes = 0;
    let flushTimer = null;
    let microtaskQueued = false;
    let generation = 0;
    let scheduledGeneration = 0;
    let waitRounds = 0;
    let flushPromise = null;
    const sendRawChunk = async chunk => {
        if (webSocket.readyState !== WebSocket.OPEN) throw new Error("ws.readyState is not open");
        webSocket.send(chunk);
    };
    const attachResponseHeader = chunk => {
        if (!header) return chunk;
        const merged = new Uint8Array(header.length + chunk.byteLength);
        merged.set(header, 0);
        merged.set(chunk, header.length);
        header = null;
        return merged;
    };
    const flush = async () => {
        while (flushPromise) await flushPromise;
        if (flushTimer) clearTimeout(flushTimer);
        flushTimer = null;
        microtaskQueued = false;
        if (!pendingBytes) return;
        const output = pendingBuffer.subarray(0, pendingBytes).slice();
        pendingBuffer = new Uint8Array(packetCap);
        pendingBytes = 0;
        waitRounds = 0;
        flushPromise = sendRawChunk(output).finally(() => {
            flushPromise = null;
        });
        return flushPromise;
    };
    const scheduleFlush = () => {
        if (flushTimer || microtaskQueued) return;
        microtaskQueued = true;
        scheduledGeneration = generation;
        queueMicrotask(() => {
            microtaskQueued = false;
            if (!pendingBytes || flushTimer) return;
            if (packetCap - pendingBytes < tailBytes) {
                flush().catch(() => closeSocketQuietly(webSocket));
                return;
            }
            if (pendingBytes <= DOWNSTREAM_INTERACTIVE_BYTES) {
                flush().catch(() => closeSocketQuietly(webSocket));
                return;
            }
            flushTimer = setTimeout(() => {
                flushTimer = null;
                if (!pendingBytes) return;
                if (packetCap - pendingBytes < tailBytes) {
                    flush().catch(() => closeSocketQuietly(webSocket));
                    return;
                }
                if (waitRounds < 1 && (generation !== scheduledGeneration || pendingBytes < lowWaterBytes)) {
                    waitRounds++;
                    scheduledGeneration = generation;
                    scheduleFlush();
                    return;
                }
                flush().catch(() => closeSocketQuietly(webSocket));
            }, Math.max(DOWNSTREAM_FLUSH_DELAY_MS, 0));
        });
    };
    return {
        async sendDirect(data) {
            let chunk = convertToUint8Array(data);
            if (!chunk.byteLength) return;
            chunk = attachResponseHeader(chunk);
            await sendRawChunk(chunk);
        },
        async send(data) {
            let chunk = convertToUint8Array(data);
            if (!chunk.byteLength) return;
            chunk = attachResponseHeader(chunk);
            let offset = 0;
            const totalBytes = chunk.byteLength;
            while (offset < totalBytes) {
                if (!pendingBytes && totalBytes - offset >= packetCap) {
                    const sendBytes = Math.min(packetCap, totalBytes - offset);
                    const view = offset || sendBytes !== totalBytes ? chunk.subarray(offset, offset + sendBytes) : chunk;
                    await sendRawChunk(view);
                    offset += sendBytes;
                    continue;
                }
                const copyBytes = Math.min(packetCap - pendingBytes, totalBytes - offset);
                pendingBuffer.set(chunk.subarray(offset, offset + copyBytes), pendingBytes);
                pendingBytes += copyBytes;
                offset += copyBytes;
                generation++;
                if (pendingBytes === packetCap || packetCap - pendingBytes < tailBytes) await flush(); else scheduleFlush();
            }
        },
        flush: flush
    };
}

async function waitForBackpressure(ws) {
    if (typeof ws.bufferedAmount === "number") {
        let rounds = 0;
        while (ws.bufferedAmount > DOWNSTREAM_WS_BACKPRESSURE_BYTES && rounds < 500) {
            await new Promise(r => setTimeout(r, DOWNSTREAM_WS_POLL_MS));
            rounds++;
        }
    }
}

async function connectStreams(remoteSocket, webSocket, headerData, retryFunc, onBytes) {
    let header = headerData, hasData = false, reader, useBYOB = false;
    const BYOB_LIMIT = 64 * 1024;
    const downstreamSender = createDownstreamSender(webSocket, header);
    header = null;
    try {
        reader = remoteSocket.readable.getReader({
            mode: "byob"
        });
        useBYOB = true;
    } catch (e) {
        reader = remoteSocket.readable.getReader();
    }
    try {
        if (!useBYOB) {
            while (true) {
                await waitForBackpressure(webSocket);
                const {done: done, value: value} = await reader.read();
                if (done) break;
                if (!value || value.byteLength === 0) continue;
                hasData = true;
                if (typeof onBytes === "function") onBytes(value.byteLength);
                await downstreamSender.send(value);
            }
        } else {
            let readBuffer = new ArrayBuffer(BYOB_LIMIT);
            while (true) {
                await waitForBackpressure(webSocket);
                const {done: done, value: value} = await reader.read(new Uint8Array(readBuffer, 0, BYOB_LIMIT));
                if (done) break;
                if (!value || value.byteLength === 0) continue;
                hasData = true;
                if (typeof onBytes === "function") onBytes(value.byteLength);
                if (value.byteLength >= DOWNSTREAM_CHUNK_BYTES) {
                    await downstreamSender.flush();
                    await downstreamSender.sendDirect(value);
                    readBuffer = new ArrayBuffer(BYOB_LIMIT);
                } else {
                    await downstreamSender.send(value);
                    readBuffer = value.buffer.byteLength >= BYOB_LIMIT ? value.buffer : new ArrayBuffer(BYOB_LIMIT);
                }
            }
        }
        await downstreamSender.flush();
    } catch (err) {
        closeSocketQuietly(webSocket);
    } finally {
        try {
            reader.cancel();
        } catch (e) {}
        try {
            reader.releaseLock();
        } catch (e) {}
    }
    if (!hasData && retryFunc) await retryFunc();
}

async function buildRaceCandidates(address, port) {
    if (!RACE_DIAL_ENABLED || isIPHostname(address)) return null;
    const [aRecords, aaaaRecords] = await Promise.all([ dohQuery(address, "A"), dohQuery(address, "AAAA") ]);
    const ipv4List = [ ...new Set(aRecords.flatMap(r => r.type === 1 && typeof r.data === "string" && isIPv4(r.data) ? [ r.data ] : [])) ];
    const ipv6List = [ ...new Set(aaaaRecords.flatMap(r => r.type === 28 && typeof r.data === "string" && isIPHostname(r.data) ? [ r.data ] : [])) ];
    const limit = Math.max(1, TCP_DIAL_CONCURRENCY | 0);
    const ipList = ipv4List.length >= limit ? ipv4List.slice(0, limit) : ipv4List.concat(ipv6List.slice(0, limit - ipv4List.length));
    if (ipList.length === 0) return null;
    return ipList.map((hostname, attempt) => ({
        hostname: hostname,
        port: port,
        attempt: attempt,
        resolvedFrom: address
    }));
}

async function openTcpConnection(host, port, timeoutMs = TCP_DIAL_TIMEOUT_MS) {
    const abuseVerdict = AbuseGuard.destinationVerdict(host, port, AbuseGuard.activeEnv);
    if (abuseVerdict.blocked) {
        AbuseGuard.noteBlocked(host, port, abuseVerdict.reason);
        throw new Error("destination refused by abuse policy: " + abuseVerdict.reason);
    }
    await AbuseGuard.dialSlot(AbuseGuard.activeEnv);
    try {
        const connectFn = await loadTcpConnect();
        const socket = connectFn({
            hostname: host,
            port: port
        });
        let timer = null;
        try {
            await Promise.race([ socket.opened, new Promise((_, reject) => {
                timer = setTimeout(() => reject(new Error("timeout")), timeoutMs);
            }) ]);
        } catch (e) {
            try {
                socket.close();
            } catch (e2) {}
            throw e;
        } finally {
            if (timer) clearTimeout(timer);
        }
        return socket;
    } finally {
        AbuseGuard.releaseDial();
    }
}

async function writeInitialTcpData(socket, initialData) {
    if (!initialData || !initialData.byteLength) return;
    const w = socket.writable.getWriter();
    try {
        await w.write(convertToUint8Array(initialData));
    } finally {
        w.releaseLock();
    }
}

async function raceOpenTcpConnections(candidates, initialData, timeoutMs = TCP_DIAL_TIMEOUT_MS) {
    const failed = [];
    if (candidates.length === 1) {
        let s = null;
        try {
            s = await openTcpConnection(candidates[0].hostname, candidates[0].port, timeoutMs);
        } catch (e) {
            failed.push(candidates[0]);
            throw e;
        }
        await writeInitialTcpData(s, initialData);
        return {
            socket: s,
            candidate: candidates[0],
            failedHosts: failed
        };
    }
    const attempts = candidates.map(c => openTcpConnection(c.hostname, c.port, timeoutMs).then(socket => ({
        socket: socket,
        candidate: c
    }), err => {
        failed.push(c);
        throw err;
    }));
    let winner = null;
    try {
        winner = await Promise.any(attempts);
        await writeInitialTcpData(winner.socket, initialData);
        winner.failedHosts = failed.slice();
        return winner;
    } catch (err) {
        err.failedHosts = failed.length ? failed.slice() : candidates.slice();
        throw err;
    } finally {
        for (const attempt of attempts) {
            attempt.then(({socket: socket}) => {
                if (!winner || socket !== winner.socket) {
                    try {
                        socket.close();
                    } catch (e) {}
                }
            }).catch(() => {});
        }
    }
}

function pickUpstreamRoute(targetAddr, targetPort, ns, proxyConfigured, allowProxyRetry) {
    if (!proxyConfigured || !allowProxyRetry) return "direct";
    const mode = String(ns && ns.proxyRoutingMode || "smart").toLowerCase();
    if (mode === "proxy" || mode === "chain") return "proxy";
    if (mode === "direct") return "direct";
    const addr = String(targetAddr || "");
    if (!addr) return "proxy";
    if (ns && ns.enableDomesticBypass && !isIPv4(addr) && !addr.includes(":") && isIranDomain(addr)) return "direct";
    if (isCloudflareIP(addr)) return "proxy";
    if (isIPHostname(addr)) return "direct";
    return "race";
}

const PROXY_LIST_MAX = 500;

const CF_DEST_VERDICT_TTL_MS = 10 * 60 * 1e3;

const CF_DEST_VERDICT_MISS_TTL_MS = 90 * 1e3;

const CF_DEST_VERDICT_CACHE_MAX = 512;

const PROXY_CHECK_TIMEOUT_MS = 2500;

const PROXY_CHECK_CONCURRENCY = 4;

const PROXY_CHECK_MAX_ENTRIES = 16;

const cfDestVerdictCache = new Map;

function isIpv4Literal(value) {
    const parts = String(value || "").split(".");
    if (parts.length !== 4) return false;
    return parts.every(part => /^\d{1,3}$/.test(part) && Number(part) <= 255);
}

function isHostnameLiteral(value) {
    const host = String(value || "").trim();
    if (!host || host.length > 253) return false;
    if (isIpv4Literal(host)) return true;
    if (host.includes(":")) return true;
    return /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)*$/i.test(host);
}

async function targetResolvesToCloudflare(host) {
    const key = String(host || "").trim().toLowerCase();
    if (!key || key.length > 253) return false;
    if (isIpv4Literal(key) || key.includes(":")) return isCloudflareIP(key);
    const now = Date.now();
    const cached = cfDestVerdictCache.get(key);
    if (cached && cached.expires > now) return cached.value;
    let value = false;
    try {
        const aRecords = await dohQuery(key, "A");
        const v4 = aRecords.filter(r => r.type === 1 && typeof r.data === "string").map(r => r.data);
        value = v4.some(ip => isCloudflareIPv4(ip));
        if (!value) {
            const aaaaRecords = await dohQuery(key, "AAAA");
            value = aaaaRecords.some(r => r.type === 28 && typeof r.data === "string" && isCloudflareIPv6(r.data));
        }
    } catch (e) {}
    if (cfDestVerdictCache.size >= CF_DEST_VERDICT_CACHE_MAX) cfDestVerdictCache.clear();
    cfDestVerdictCache.set(key, {
        value: value,
        expires: now + (value ? CF_DEST_VERDICT_TTL_MS : CF_DEST_VERDICT_MISS_TTL_MS)
    });
    return value;
}

async function resolveUpstreamRoute(targetAddr, targetPort, ns, proxyConfigured, allowProxyRetry) {
    const route = pickUpstreamRoute(targetAddr, targetPort, ns, proxyConfigured, allowProxyRetry);
    if (route !== "race") return route;
    if (await targetResolvesToCloudflare(targetAddr)) return "proxy";
    return route;
}

async function checkSingleProxyEntry(entry) {
    const meta = CdnProxyService.parseProxyEntryMeta(entry);
    const result = {
        entry: entry,
        address: meta.address,
        cc: meta.cc || "",
        ok: false,
        ms: 0,
        attempts: 0,
        resolved: 0,
        error: ""
    };
    if (!meta.address || CdnProxyService.isAutoProxy(meta.address)) {
        result.error = "auto";
        return result;
    }
    let pairs = [];
    try {
        pairs = await CdnProxyService.resolveProxyAddresses(meta.address, "www.cloudflare.com", "proxy-check", "proxy-check");
    } catch (e) {
        pairs = [];
    }
    result.resolved = pairs.length;
    if (!pairs.length) {
        result.error = "unresolved";
        return result;
    }
    const tried = new Set;
    for (const [addr, port] of pairs.slice(0, 3)) {
        const key = addr + ":" + port;
        if (tried.has(key)) continue;
        tried.add(key);
        result.attempts++;
        const started = Date.now();
        try {
            const socket = await openTcpConnection(addr, port, PROXY_CHECK_TIMEOUT_MS);
            const ms = Date.now() - started;
            try {
                socket.close();
            } catch (e) {}
            result.ok = true;
            result.ms = ms;
            result.address = addr;
            result.port = port;
            result.error = "";
            return result;
        } catch (e) {
            result.error = "timeout";
        }
    }
    return result;
}

async function checkProxyEntries(entries) {
    const list = [];
    const seen = new Set;
    for (const raw of Array.isArray(entries) ? entries : []) {
        const entry = String(raw || "").trim();
        if (!entry || seen.has(entry.toLowerCase())) continue;
        seen.add(entry.toLowerCase());
        list.push(entry);
        if (list.length >= PROXY_CHECK_MAX_ENTRIES) break;
    }
    const results = new Array(list.length);
    let cursor = 0;
    const workers = new Array(Math.max(1, Math.min(PROXY_CHECK_CONCURRENCY, list.length))).fill(null).map(async () => {
        while (cursor < list.length) {
            const index = cursor++;
            try {
                results[index] = await checkSingleProxyEntry(list[index]);
            } catch (e) {
                results[index] = {
                    entry: list[index],
                    ok: false,
                    ms: 0,
                    resolved: 0,
                    attempts: 0,
                    error: "failed",
                    address: "",
                    cc: ""
                };
            }
        }
    });
    await Promise.all(workers);
    return results.filter(Boolean);
}

async function connectViaActiveProxy(activeProxyIp, targetAddr, targetPort, uuid, enableFallback, payload, stickySeed = "", allowDirectFallback = false) {
    return connectProxyCDN(activeProxyIp, targetAddr, targetPort, uuid, enableFallback, payload, stickySeed, allowDirectFallback);
}

async function connectProxyCDN(proxyIP, targetHost, targetPort, uuid, enableFallback, initialData = null, stickySeed = "", allowDirectFallback = false) {
    const allProxies = await CdnProxyService.resolveProxyAddresses(proxyIP, targetHost, uuid, stickySeed);
    if (!allProxies.length) {
        if (enableFallback || allowDirectFallback) return connectDirect(targetHost, targetPort, initialData);
        throw new Error("No usable proxy address resolved for " + proxyIP);
    }
    const anchor = CdnProxyService.getStickyAnchor(allProxies.length, stickySeed, uuid);
    const order = [];
    for (let i = 0; i < allProxies.length; i++) order.push((anchor + i) % allProxies.length);
    const fresh = order.filter(idx => !proxyIsPenalized(allProxies[idx][0], allProxies[idx][1]));
    const usable = fresh.length ? fresh : order;
    const limit = Math.max(1, TCP_PROXY_DIAL_CONCURRENCY | 0);
    let lastErr = null;
    for (let i = 0; i < usable.length; i += limit) {
        const candidates = [];
        for (let j = 0; j < limit && i + j < usable.length; j++) {
            const idx = usable[i + j];
            const [proxyAddr, proxyPort] = allProxies[idx];
            candidates.push({
                hostname: proxyAddr,
                port: proxyPort,
                index: idx
            });
        }
        try {
            const result = await raceOpenTcpConnections(candidates, initialData, TCP_DIAL_TIMEOUT_PROXY_MS);
            for (const c of candidates) proxyClearPenalty(c.hostname, c.port);
            for (const c of result.failedHosts || []) proxyPenalize(c.hostname, c.port);
            return result.socket;
        } catch (e) {
            lastErr = e;
            for (const c of e.failedHosts || candidates) proxyPenalize(c.hostname, c.port);
        }
    }
    if (enableFallback || allowDirectFallback) {
        try {
            return await connectDirect(targetHost, targetPort, initialData);
        } catch (e) {
            throw lastErr || e;
        }
    }
    throw lastErr || new Error("All CDN proxy connections failed");
}

async function connectDirectSingle(address, port, initialData = null) {
    const socket = await openTcpConnection(address, port, TCP_DIAL_TIMEOUT_MS);
    await writeInitialTcpData(socket, initialData);
    return socket;
}

async function connectDirect(address, port, initialData = null) {
    if (!IPV6_UPSTREAM_ENABLED && address && address.includes(":")) {
        throw new Error("ipv6 upstream disabled");
    }
    const raceCandidates = await buildRaceCandidates(address, port);
    const candidates = raceCandidates || Array.from({
        length: TCP_DIAL_CONCURRENCY
    }, () => ({
        hostname: address,
        port: port
    }));
    const openConnection = (host, prt) => openTcpConnection(host, prt, TCP_DIAL_TIMEOUT_MS);
    if (candidates.length === 1) {
        const s = await openConnection(candidates[0].hostname, candidates[0].port);
        if (initialData && initialData.byteLength > 0) {
            const w = s.writable.getWriter();
            await w.write(convertToUint8Array(initialData));
            w.releaseLock();
        }
        return s;
    }
    const attempts = candidates.map(c => openConnection(c.hostname, c.port).then(socket => ({
        socket: socket,
        candidate: c
    })));
    let winner = null;
    try {
        winner = await Promise.any(attempts);
        if (initialData && initialData.byteLength > 0) {
            const w = winner.socket.writable.getWriter();
            await w.write(convertToUint8Array(initialData));
            w.releaseLock();
        }
        return winner.socket;
    } finally {
        if (winner) {
            for (const attempt of attempts) {
                attempt.then(({socket: socket}) => {
                    if (socket !== winner.socket) {
                        try {
                            socket.close();
                        } catch (e) {}
                    }
                }).catch(() => {});
            }
        }
    }
}

function looksLikeDnsQuery(buf, off) {
    if (!buf || buf.length < off + 13) return false;
    let dv;
    try {
        dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
    } catch (e) {
        return false;
    }
    const flags = dv.getUint16(off + 2);
    if ((flags & 32768) !== 0) return false;
    if ((flags >> 11 & 15) !== 0) return false;
    const qd = dv.getUint16(off + 4);
    if (qd < 1 || qd > 4) return false;
    if (dv.getUint16(off + 6) !== 0) return false;
    let p = off + 12;
    for (let i = 0; i < qd; i++) {
        for (;;) {
            if (p >= buf.length) return false;
            const len = buf[p];
            if (len === 0) {
                p++;
                break;
            }
            if ((len & 192) !== 0 || p + len >= buf.length) return false;
            p += len + 1;
        }
        p += 4;
        if (p > buf.length) return false;
    }
    return true;
}

function extractDnsMessage(buf) {
    const bytes = convertToUint8Array(buf);
    for (const off of [ 0, 16, 17, 18, 19, 20, 21 ]) {
        if (looksLikeDnsQuery(bytes, off)) return bytes.subarray(off);
    }
    return null;
}

async function answerDnsViaDoH(dnsQuery, webSocket, respHeader, onBytes) {
    const urls = [ DOH_RESOLVER_URL ].concat(DOH_RESOLVER_BACKUP_URLS);
    for (let i = 0; i < urls.length; i++) {
        try {
            const res = await fetchWithDeadline(urls[i], {
                method: "POST",
                headers: {
                    "Content-Type": "application/dns-message",
                    Accept: "application/dns-message"
                },
                body: dnsQuery
            }, Math.max(800, DOH_QUERY_TIMEOUT_MS));
            if (!res || !res.ok) continue;
            const answer = new Uint8Array(await res.arrayBuffer());
            if (!answer.byteLength) continue;
            if (typeof onBytes === "function") onBytes(answer.byteLength);
            if (webSocket.readyState !== WebSocket.OPEN) return true;
            if (respHeader && respHeader.length) {
                const merged = new Uint8Array(respHeader.length + answer.byteLength);
                merged.set(respHeader, 0);
                merged.set(answer, respHeader.length);
                webSocket.send(merged);
            } else {
                webSocket.send(answer);
            }
            return true;
        } catch (e) {}
    }
    return false;
}

async function forwardVlessUDP(udpChunk, webSocket, respHeader, onBytes, env) {
    const requestData = convertToUint8Array(udpChunk);
    const dnsQuery = extractDnsMessage(requestData);
    if (dnsQuery && await answerDnsViaDoH(dnsQuery, webSocket, respHeader, onBytes)) return;
    await AbuseGuard.dialSlot(env);
    let tcpSocket = null;
    const dnsDeadline = setTimeout(() => {
        try {
            if (tcpSocket) tcpSocket.close();
        } catch (e) {}
    }, DNS_TCP_FALLBACK_TIMEOUT_MS);
    try {
        const connectFn = await loadTcpConnect();
        tcpSocket = connectFn({
            hostname: "8.8.4.4",
            port: 53
        });
        let vlessHeader = respHeader;
        const writer = tcpSocket.writable.getWriter();
        await writer.write(requestData);
        writer.releaseLock();
        await tcpSocket.readable.pipeTo(new WritableStream({
            async write(chunk) {
                const response = convertToUint8Array(chunk);
                if (typeof onBytes === "function") onBytes(response.byteLength);
                if (webSocket.readyState !== WebSocket.OPEN) return;
                if (vlessHeader) {
                    const merged = new Uint8Array(vlessHeader.length + response.byteLength);
                    merged.set(vlessHeader, 0);
                    merged.set(response, vlessHeader.length);
                    webSocket.send(merged.buffer);
                    vlessHeader = null;
                } else {
                    webSocket.send(response);
                }
            }
        }));
    } catch (e) {} finally {
        clearTimeout(dnsDeadline);
        try {
            if (tcpSocket) tcpSocket.close();
        } catch (e) {}
        AbuseGuard.releaseDial();
    }
}

function extractUUIDFromVless(data) {
    if (data.byteLength < 17) return null;
    const hex = [ ...data.slice(1, 17) ].map(b => b.toString(16).padStart(2, "0")).join("");
    return `${hex.substring(0, 8)}-${hex.substring(8, 12)}-${hex.substring(12, 16)}-${hex.substring(16, 20)}-${hex.substring(20)}`;
}

function getRequestDateKey() {
    return (new Date).toISOString().split("T")[0];
}

function getUserReqUsageToday(user, username) {
    const pending = userRequestPending.get(username) || 0;
    const today = getRequestDateKey();
    const dbToday = user && user.req_last_date === today ? parseInt(user.used_requests_today) || 0 : 0;
    return dbToday + pending;
}

function getUserReqUsageTotal(user, username) {
    const pending = userRequestPending.get(username) || 0;
    return (parseInt(user?.used_requests) || 0) + pending;
}

function getUserReqUsage(user, username) {
    return getUserReqUsageToday(user, username);
}

function isUserRequestLimitExceeded(user, username) {
    if (!user) return false;
    if (user.max_requests && user.max_requests > 0 && getUserReqUsageTotal(user, username) >= user.max_requests) return true;
    if (user.max_requests_daily && user.max_requests_daily > 0 && getUserReqUsageToday(user, username) >= user.max_requests_daily) return true;
    return false;
}

function getUserRequestLimitReason(user, username) {
    if (!user) return null;
    if (user.max_requests && user.max_requests > 0 && getUserReqUsageTotal(user, username) >= user.max_requests) return "total";
    if (user.max_requests_daily && user.max_requests_daily > 0 && getUserReqUsageToday(user, username) >= user.max_requests_daily) return "daily";
    return null;
}

async function flushUserRequestCounts(env, username) {
    const pending = userRequestPending.get(username) || 0;
    if (pending <= 0) return;
    const today = getRequestDateKey();
    try {
        await env.DB.prepare("UPDATE users SET used_requests = COALESCE(used_requests, 0) + ?, used_requests_today = CASE WHEN req_last_date = ? THEN COALESCE(used_requests_today, 0) + ? ELSE ? END, req_last_date = ? WHERE username = ?").bind(pending, today, pending, pending, today, username).run();
        const remain = (userRequestPending.get(username) || 0) - pending;
        userRequestPending.set(username, remain > 0 ? remain : 0);
    } catch (e) {}
}

function trackUserRequest(username, env, ctx) {
    if (!username) return;
    userRequestPending.set(username, (userRequestPending.get(username) || 0) + 1);
    const now = Date.now();
    const lastFlush = userRequestLastFlush.get(username) || 0;
    if (now - lastFlush > 6e4) {
        userRequestLastFlush.set(username, now);
        const task = async () => {
            await flushUserRequestCounts(env, username);
        };
        safeWaitUntil(ctx, task);
    }
}

async function getTopRequestUsers(env, limit = 3) {
    try {
        const {results: results} = await env.DB.prepare("SELECT username, used_requests, max_requests, req_last_date, used_requests_today FROM users WHERE COALESCE(is_system, 0) = 0 ORDER BY COALESCE(used_requests, 0) DESC LIMIT 100").all();
        return (results || []).map(u => ({
            username: u.username,
            used: getUserReqUsageTotal(u, u.username),
            max: u.max_requests
        })).filter(u => u.used > 0).sort((a, b) => b.used - a.used).slice(0, limit);
    } catch (e) {
        return [];
    }
}

function trackRequest(env, ctx) {
    pendingRequestCount++;
    const now = Date.now();
    if (now - lastRequestFlushAt > 6e4 && pendingRequestCount > 0) {
        lastRequestFlushAt = now;
        const countToSave = pendingRequestCount;
        pendingRequestCount = 0;
        const task = async () => {
            try {
                const today = (new Date).toISOString().split("T")[0];
                await env.DB.batch([ env.DB.prepare("INSERT INTO settings (key, value) VALUES ('req_today', ?) ON CONFLICT(key) DO UPDATE SET value = CASE WHEN (SELECT value FROM settings WHERE key = 'req_last_date') IS NOT ? THEN CAST(excluded.value AS INTEGER) ELSE CAST(value AS INTEGER) + ? END").bind(String(countToSave), today, String(countToSave)), env.DB.prepare("INSERT INTO settings (key, value) VALUES ('req_last_date', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value").bind(today), env.DB.prepare("INSERT INTO settings (key, value) VALUES ('req_total', ?) ON CONFLICT(key) DO UPDATE SET value = CAST(value AS INTEGER) + ?").bind(String(countToSave), String(countToSave)) ]);
            } catch (e) {
                pendingRequestCount += countToSave;
            }
        };
        safeWaitUntil(ctx, task);
    }
}

