function buildPasswordRevealButton(inputId, variant) {
    const isSetup = variant === "setup";
    const buttonClass = isSetup ? "setup-reveal-toggle" : "adm-password-toggle";
    const targetAttribute = isSetup ? "data-setup-password-toggle" : "data-password-toggle";
    const eyeOpen = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" data-eye-open><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z"></path><circle cx="12" cy="12" r="3"></circle></svg>';
    const eyeClosed = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" class="hidden" data-eye-closed><path d="m3 3 18 18"></path><path d="M10.6 10.6a2 2 0 0 0 2.8 2.8"></path><path d="M9.9 5.2A10.5 10.5 0 0 1 12 5c6.4 0 10 7 10 7a15.7 15.7 0 0 1-3.1 4.2"></path><path d="M6.2 6.2C3.4 8.1 2 12 2 12s3.6 7 10 7a10 10 0 0 0 4.1-.9"></path></svg>';
    return '<button type="button" class="' + buttonClass + '" ' + targetAttribute + '="' + inputId + '" data-i18n-aria-label="password_show" data-i18n-title="password_show"' + ' aria-label="نمایش رمز" title="نمایش رمز" aria-pressed="false">' + eyeOpen + eyeClosed + "</button>";
}

function buildSetupHtml(status, options) {
    options = options || {};
    const cfTokenMode = !!options.cfTokenMode;
    const setupI18n = buildSetupI18n(status);
    const isPagesRuntime = status.runtime_type === "pages";
    const hasAdmin = !!(status.admin_configured || status.admin_from_env || status.admin_from_d1 || status.admin_from_api);
    /* رمز عبور در D1 ذخیره می‌شود؛ CF_API_TOKEN برای تنظیم رمز لازم نیست. */
    const tokenOkForSetup = true;
    const runtimeLabel = isPagesRuntime ? "Cloudflare Pages" : "Cloudflare Worker";
    const runtimeDetail = isPagesRuntime ? status.runtime_name ? `پروژه: ${status.runtime_name} — محیط: ${status.pages_environment || "production"}` : "پروژهٔ Pages از دامنه پیدا نشد؛ دسترسی Pages:Read یا متغیر PAGES_PROJECT_NAME را بررسی کنید." : status.runtime_name ? `نام Worker: ${status.runtime_name}` : "Worker از روی دامنه پیدا نشد؛ دسترسی خواندن دامنه‌ها و مسیرهای Worker یا متغیر WORKER_NAME را بررسی کنید.";
    const dbName = status.d1_database_name || null;
    const d1Label = dbName ? `D1: ${dbName}` : `D1 (binding: ${status.d1_binding_name})`;
    const d1Detail = status.d1_connected ? dbName ? `نام دیتابیس: ${String(dbName)}${status.d1_database_id ? "\nآیدی دیتابیس: " + status.d1_database_id : ""}` : `binding: ${String(status.d1_binding_name)}${status.d1_database_id ? "\nآیدی دیتابیس: " + status.d1_database_id : ""}` : status.d1_error || "اتصال D1 برقرار نیست";
    const tokenConnected = !!status.cf_api_token && !cfTokenMode;
    const statusCards = [ buildSetupStatusCard({
        label: runtimeLabel,
        connected: !!status.runtime_name,
        detail: runtimeDetail,
        labelKey: "runtime_label",
        detailKey: "runtime_detail"
    }), buildSetupStatusCard({
        label: d1Label,
        connected: status.d1_connected,
        detail: d1Detail,
        labelKey: "d1_label",
        detailKey: status.d1_connected ? "d1_ok" : "d1_err",
        mono: true
    }), buildSetupStatusCard({
        label: "ADMIN",
        connected: hasAdmin,
        detail: hasAdmin ? status.admin_from_d1 ? "رمز عبور به‌صورت هش در D1 ذخیره شده است" : status.admin_from_env ? "رمز عبور از متغیر ADMIN خوانده می‌شود" : "متغیر ADMIN در تنظیمات Cloudflare تعریف شده است؛ در Deployment فعلی هنوز فعال نشده — یک Deployment جدید یا Retry deployment انجام دهید." : "رمز عبور هنوز تنظیم نشده",
        labelKey: "admin_label",
        detailKey: hasAdmin ? "admin_ok" : "admin_err",
        badgeKey: hasAdmin ? "badge_set" : "badge_unset",
        badgeText: hasAdmin ? "تنظیم شده" : "تنظیم نشده"
    }), buildSetupStatusCard({
        label: "CF_API_TOKEN",
        connected: tokenConnected,
        optional: !tokenConnected && !cfTokenMode,
        detail: cfTokenMode ? "توکن معتبر نیست یا منقضی شده — توکن جدید وارد کنید" : status.cf_api_token ? "متغیر محیطی یا D1 تنظیم شده است" : "اختیاری — فقط برای امکانات جانبی (اسکنر، پاک‌سازی IP، دیپلوی خودکار). برای راه‌اندازی و ورود به پنل لازم نیست.",
        labelKey: "cf_token_label",
        detailKey: cfTokenMode ? "cf_token_invalid" : status.cf_api_token ? "cf_token_ok" : "cf_token_optional"
    }) ].join("");
    const canProceed = status.setup_ready;
    const canSetPassword = !hasAdmin && status.d1_connected && tokenOkForSetup;
    const passwordForm = `\n        <form id="setup-form" class="setup-form" novalidate>\n            <div class="setup-form-grid">\n                <div class="setup-field">\n                    <label for="setup-password" class="setup-label" data-i18n="pwd_label">رمز عبور پنل</label>\n                    <div class="setup-input-reveal-wrap">\n                        <input type="password" id="setup-password" required minlength="4" autocomplete="new-password"\n                            class="setup-input setup-input-reveal"\n                            data-i18n-placeholder="pwd_placeholder" placeholder="رمز عبور را وارد کنید">\n                        ${buildPasswordRevealButton("setup-password", "setup")}\n                    </div>\n                </div>\n                <div class="setup-field">\n                    <label for="setup-password-confirm" class="setup-label" data-i18n="pwd_confirm_label">تکرار رمز عبور</label>\n                    <div class="setup-input-reveal-wrap">\n                        <input type="password" id="setup-password-confirm" required minlength="4" autocomplete="new-password"\n                            class="setup-input setup-input-reveal"\n                            data-i18n-placeholder="pwd_confirm_placeholder" placeholder="رمز عبور را دوباره وارد کنید">\n                        ${buildPasswordRevealButton("setup-password-confirm", "setup")}\n                    </div>\n                </div>\n            </div>\n            ${status.cf_account_id ? "" : `\n            <div class="setup-field">\n                <label for="setup-account-id" class="setup-label" data-i18n="acct_id_label">شناسهٔ اکانت Cloudflare (اختیاری)</label>\n                <input type="text" id="setup-account-id" dir="ltr" autocomplete="off"\n                    class="setup-input setup-mono"\n                    data-i18n-placeholder="acct_id_placeholder" placeholder="Account ID — فقط در صورت خطا">\n                <p class="setup-panel-hint" data-i18n="acct_id_hint">شناسهٔ اکانت معمولاً به‌صورت خودکار از توکن یافت می‌شود؛ این فیلد فقط برای زمانی است که تشخیص خودکار با خطا مواجه شود.</p>\n            </div>`}\n            <p id="setup-error" class="setup-form-error hidden" aria-hidden="true"></p>\n            <button type="submit" id="setup-submit" class="setup-btn" data-i18n="pwd_submit">تنظیم رمز عبور</button>\n        </form>`;
    const passwordPanel = cfTokenMode ? canSetPassword ? `\n      <section class="setup-panel">\n        <div class="setup-panel-head">\n          <h2 class="setup-panel-title" data-i18n="pwd_req_title">برای ورود به پنل رمز عبور تنظیم کنید</h2>\n        </div>\n        ${passwordForm}\n      </section>` : "" : hasAdmin ? `\n      <section class="setup-panel">\n        <div class="setup-panel-head">\n          <h2 class="setup-panel-title" data-i18n="pwd_done_title">رمز عبور پنل تنظیم شده است</h2>\n        </div>\n        <ul class="setup-notes">\n          <li><span class="setup-note-dot" aria-hidden="true"></span><span data-i18n="pwd_change_1">این رمز عبور را می‌توانید از تنظیمات ورکر یا Pages خود، در بخش «تنظیمات متغیرهای محیطی»، تغییر دهید.</span></li>\n          <li><span class="setup-note-dot" aria-hidden="true"></span><span class="setup-note-body"><code class="setup-inline-code" dir="ltr">ADMIN</code> <span data-i18n="pwd_change_2">مقدار رمز دلخواه شماست.</span></span></li>\n          <li><span class="setup-note-dot" aria-hidden="true"></span><span data-i18n="pwd_change_3">همچنین از داخل پنل می‌توانید رمز عبور خود را تغییر دهید.</span></li>\n        </ul>\n        ${status.admin_from_d1 ? '<p class="setup-note-extra" data-i18n="pwd_legacy_note">رمز عبور فعلی به‌صورت هش در دیتابیس D1 ذخیره شده است.</p>' : ""}\n      </section>` : `\n      <section class="setup-panel">\n        <div class="setup-panel-head">\n          <h2 class="setup-panel-title" data-i18n="pwd_req_title">برای ورود به پنل رمز عبور تنظیم کنید</h2>\n        </div>\n        ${canSetPassword ? passwordForm : '<p class="setup-warn" data-i18n="' + (status.d1_connected ? "pwd_need_token" : "pwd_need_d1") + '">' + (status.d1_connected ? "برای تنظیم رمز عبور، ابتدا متغیر CF_API_TOKEN را در ورکر تنظیم کنید." : "برای تنظیم رمز عبور، ابتدا باید اتصال D1 برقرار شود.") + "</p>"}\n      </section>`;
    const missingVarsMsg = !canProceed && !canSetPassword && !cfTokenMode ? '<p class="setup-missing" data-i18n="setup_missing_vars">' + (isPagesRuntime ? "برای ادامه در Pages، اتصال D1 باید برقرار باشد و رمز پنل تنظیم شود." : "برای ورود به پنل، D1 باید متصل باشد و متغیرهای ADMIN و CF_API_TOKEN تنظیم شده باشند.") + "</p>" : "";
    const cfTokenForm = cfTokenMode ? `\n      <section class="setup-panel">\n        <div class="setup-panel-head">\n          <h2 class="setup-panel-title" data-i18n="setup_cf_token_title">به‌روزرسانی توکن Cloudflare</h2>\n          <p class="setup-panel-hint" data-i18n="setup_cf_token_invalid_msg">توکن CF_API_TOKEN معتبر نیست یا منقضی شده. توکن API جدید کلودفلر را وارد و ذخیره کنید.</p>\n        </div>\n        <form id="setup-cf-form" class="setup-form" novalidate>\n            <div class="setup-field">\n                <label for="setup-cf-token" class="setup-label" data-i18n="cf_token_label">CF_API_TOKEN</label>\n                <div class="setup-input-reveal-wrap">\n                    <input type="password" id="setup-cf-token" required dir="ltr" autocomplete="off"\n                        class="setup-input setup-input-reveal setup-mono"\n                        data-i18n-placeholder="setup_cf_token_placeholder" placeholder="Cloudflare API Token">\n                    ${buildPasswordRevealButton("setup-cf-token", "setup")}\n                </div>\n            </div>\n            <div class="setup-field">\n                <label for="setup-cf-account-id" class="setup-label" data-i18n="acct_id_label">شناسهٔ اکانت Cloudflare (اختیاری)</label>\n                <input type="text" id="setup-cf-account-id" dir="ltr" autocomplete="off"\n                    class="setup-input setup-mono"\n                    data-i18n-placeholder="acct_id_placeholder" placeholder="Account ID — فقط در صورت خطا">\n                <p class="setup-panel-hint" data-i18n="acct_id_hint">شناسهٔ اکانت معمولاً به‌صورت خودکار از توکن یافت می‌شود؛ این فیلد فقط برای زمانی است که تشخیص خودکار با خطا مواجه شود.</p>\n            </div>\n            <p id="setup-cf-error" class="hidden setup-form-error" aria-hidden="true"></p>\n            <button type="submit" id="setup-cf-submit" class="setup-btn" data-i18n="setup_cf_token_submit">ذخیره توکن</button>\n        </form>\n      </section>` : "";
    const panelEntryBlock = cfTokenMode ? '<a href="/admin" class="setup-btn setup-btn-ghost" data-i18n="setup_back_panel">بازگشت به پنل</a>' : canProceed ? '<a href="/admin" class="setup-btn" data-i18n="enter_panel">ورود به پنل</a>' : '<button type="button" disabled class="setup-btn setup-btn-disabled" data-i18n="enter_panel">ورود به پنل</button>';
    const enterHint = cfTokenMode ? "" : '<p class="setup-panel-hint" data-i18n="' + (canProceed ? "enter_hint_ready" : "enter_hint_locked") + '">' + (canProceed ? "همه‌چیز آماده است." : "تا زمانی که مراحل بالا کامل نشوند، ورود به پنل فعال نیست.") + "</p>";
    return `<!DOCTYPE html>\n<html lang="fa" dir="rtl">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    ${NEXA_THEME_COLOR_SETUP}\n    ${NEXA_FAVICON_TAGS}\n    ${NEXA_THEME_COLOR_SYNC_SCRIPT}\n    <title data-i18n="page_title">راه‌اندازی اولیه — Nexa Panel</title>\n    <link href="https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css" rel="stylesheet" type="text/css" />\n    <style>\n        html { color-scheme: light; }\n        html.dark { color-scheme: dark; }\n        body.setup-page, body.setup-page * { box-sizing: border-box; }\n        body.setup-page {\n            --s-brand: #2fa843;\n            --s-brand-strong: #1d8631;\n            --s-brand-lime: #79e62a;\n            --s-brand-glow: rgba(63, 181, 58, .18);\n            --s-brand-soft: rgba(47, 168, 67, .10);\n            --s-text: #101a14;\n            --s-text-soft: #37493d;\n            --s-muted: #64766b;\n            --s-page: #f4f7f4;\n            --s-surface: #ffffff;\n            --s-surface-2: #f7faf8;\n            --s-border: rgba(16, 44, 26, .10);\n            --s-border-strong: rgba(16, 44, 26, .17);\n            --s-input-bg: #fcfefd;\n            --s-ok: #178a43;\n            --s-ok-soft: rgba(34, 164, 71, .12);\n            --s-err: #cf4437;\n            --s-err-soft: rgba(207, 68, 55, .10);\n            --s-warn: #a9761a;\n            --s-warn-soft: rgba(197, 141, 33, .14);\n            --s-shadow: 0 26px 60px -48px rgba(8, 32, 18, .55);\n            --s-dot: rgba(16, 44, 26, .07);\n            margin: 0; width: 100%; min-height: 100vh; min-height: 100dvh;\n            display: flex; flex-direction: column;\n            font-family: 'Vazirmatn', system-ui, -apple-system, 'Segoe UI', sans-serif;\n            color: var(--s-text); line-height: 1.8; overflow-x: hidden;\n            -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility;\n            background-color: var(--s-page);\n            background-image:\n                radial-gradient(900px 460px at 88% -12%, rgba(63, 181, 58, .10), transparent 60%),\n                radial-gradient(720px 400px at 0% 104%, rgba(63, 181, 58, .06), transparent 60%),\n                radial-gradient(var(--s-dot) 1px, transparent 1.2px);\n            background-size: auto, auto, 26px 26px;\n            transition: background-color .25s, color .25s;\n        }\n        html.dark body.setup-page {\n            --s-brand: #58d356;\n            --s-brand-strong: #37ad3c;\n            --s-brand-glow: rgba(121, 230, 42, .16);\n            --s-brand-soft: rgba(121, 230, 42, .10);\n            --s-text: #e9f1ec;\n            --s-text-soft: #c6d6cc;\n            --s-muted: #92a59a;\n            --s-page: #090c0a;\n            --s-surface: #0f1512;\n            --s-surface-2: #141b17;\n            --s-border: rgba(255, 255, 255, .075);\n            --s-border-strong: rgba(255, 255, 255, .15);\n            --s-input-bg: rgba(255, 255, 255, .035);\n            --s-ok: #6fe28a;\n            --s-ok-soft: rgba(111, 226, 138, .10);\n            --s-err: #ff9186;\n            --s-err-soft: rgba(255, 145, 134, .10);\n            --s-warn: #f0c063;\n            --s-warn-soft: rgba(240, 192, 99, .12);\n            --s-shadow: 0 30px 70px -52px #000;\n            --s-dot: rgba(255, 255, 255, .05);\n            background-image:\n                radial-gradient(900px 460px at 88% -12%, rgba(63, 181, 58, .13), transparent 60%),\n                radial-gradient(720px 400px at 0% 104%, rgba(63, 181, 58, .07), transparent 60%),\n                radial-gradient(var(--s-dot) 1px, transparent 1.2px);\n            background-size: auto, auto, 26px 26px;\n        }\n        body.setup-page button, body.setup-page input { font: inherit; }\n        body.setup-page button { border: 0; }\n        body.setup-page .hidden { display: none !important; }\n        body.setup-page a { text-decoration: none; }\n        body.setup-page .setup-mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }\n\n        @keyframes setup-in {\n            from { opacity: 0; transform: translateY(10px); }\n            to { opacity: 1; transform: none; }\n        }\n\n        .setup-shell {\n            flex: 1 1 auto; width: 100%; max-width: none; margin: 0 auto;\n            padding: clamp(.85rem, 1.5vw, 1.3rem) clamp(1rem, 2.4vw, 2rem) clamp(.5rem, 1vw, .85rem);\n            display: flex; flex-direction: column; gap: clamp(.65rem, 1.1vw, 1rem);\n        }\n        .setup-topbar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding-inline: .15rem; }\n        .setup-brand { display: flex; align-items: center; gap: .8rem; min-width: 0; }\n        .setup-brand-logo {\n            width: 2.9rem; height: 2.9rem; flex: 0 0 auto; border-radius: .9rem; overflow: hidden;\n            display: inline-flex; align-items: center; justify-content: center;\n            background: var(--s-surface); border: 1px solid var(--s-border);\n            box-shadow: 0 14px 30px -24px rgba(8, 32, 18, .8);\n        }\n        .setup-brand-logo img { width: 1.85rem; height: 1.85rem; object-fit: contain; }\n        .setup-brand-text { display: flex; flex-direction: column; min-width: 0; line-height: 1.5; }\n        .setup-brand-name { font-size: 1rem; font-weight: 900; letter-spacing: .005em; }\n        .setup-brand-sub { font-size: .72rem; color: var(--s-muted); }\n\n        .setup-main {\n            flex: 1 1 auto; min-height: 0;\n            display: grid; gap: clamp(.8rem, 1.4vw, 1rem);\n            align-content: start; grid-template-columns: minmax(0, 1fr);\n        }\n\n        .setup-hero { display: flex; flex-direction: column; gap: .15rem; padding: .1rem .2rem .15rem; }\n        .setup-hero-title {\n            margin: 0; font-size: clamp(1.15rem, 1.9vw, 1.5rem); font-weight: 900;\n            letter-spacing: -.015em; line-height: 1.55;\n        }\n        .setup-hero-sub { margin: 0; max-width: 46rem; font-size: .82rem; line-height: 1.9; color: var(--s-muted); }\n\n        .setup-panel {\n            position: relative;\n            padding: clamp(.9rem, 1.45vw, 1.2rem);\n            border-radius: 1.1rem;\n            color: var(--s-text);\n            background: var(--s-surface);\n            border: 1px solid var(--s-border);\n            box-shadow: var(--s-shadow);\n            animation: setup-in .45s cubic-bezier(.2, .75, .25, 1) both;\n        }\n        .setup-panel:nth-of-type(2) { animation-delay: .04s; }\n        .setup-panel:nth-of-type(3) { animation-delay: .08s; }\n        .setup-panel:nth-of-type(4) { animation-delay: .12s; }\n        .setup-panel-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: .25rem .9rem; margin-bottom: .75rem; }\n        .setup-panel-title { margin: 0; font-size: .93rem; font-weight: 900; letter-spacing: .002em; color: var(--s-text); }\n        .setup-panel > .setup-panel-head:first-child .setup-panel-title::before {\n            content: ''; display: inline-block; width: .4rem; height: .4rem; margin-inline-end: .5rem;\n            border-radius: 999px; background: var(--s-brand); vertical-align: .08em;\n            box-shadow: 0 0 0 3px var(--s-brand-soft);\n        }\n        .setup-panel-hint { margin: 0; font-size: .73rem; color: var(--s-muted); line-height: 1.85; flex: 0 0 auto; }\n        .setup-panel-head .setup-panel-hint { text-align: end; flex: 1 1 12rem; }\n        .setup-field .setup-panel-hint { flex: 0 0 auto; }\n\n        .setup-status-grid { display: grid; gap: .65rem; grid-template-columns: repeat(auto-fit, minmax(14.5rem, 1fr)); }\n        .setup-status-card {\n            position: relative; display: flex; flex-direction: column; gap: .35rem;\n            padding: .8rem 1.1rem;\n            border-radius: .85rem; overflow: hidden;\n            background: var(--s-surface-2); border: 1px solid var(--s-border);\n            color: var(--s-text);\n            transition: background .2s, border-color .2s, transform .2s;\n        }\n        .setup-status-card:hover { transform: translateY(-1px); border-color: var(--s-border-strong); }\n        .setup-status-card::before {\n            content: ''; position: absolute; inset-block: .7rem; inset-inline-start: 0;\n            width: 3px; border-radius: 999px; background: currentColor; opacity: .85;\n        }\n        .setup-status-card.is-ok { color: var(--s-ok); }\n        .setup-status-card.is-err { color: var(--s-err); }\n        .setup-status-card.is-optional { color: var(--s-warn); }\n        .setup-status-top { display: flex; align-items: center; justify-content: space-between; gap: .6rem; }\n        .setup-status-name { display: inline-flex; align-items: center; gap: .45rem; min-width: 0; font-size: .8rem; font-weight: 800; color: var(--s-text); overflow-wrap: anywhere; }\n        .setup-status-dot { flex: 0 0 auto; width: .5rem; height: .5rem; border-radius: 999px; background: currentColor; box-shadow: 0 0 8px currentColor; }\n        .setup-status-badge {\n            flex: 0 0 auto; padding: .08rem .5rem; border-radius: 999px; font-size: .63rem; font-weight: 800;\n            border: 1px solid currentColor; color: currentColor; background: transparent;\n        }\n        .setup-status-card.is-ok .setup-status-badge { background: var(--s-ok-soft); }\n        .setup-status-card.is-err .setup-status-badge { background: var(--s-err-soft); }\n        .setup-status-card.is-optional .setup-status-badge { background: var(--s-warn-soft); }\n        .setup-status-detail {\n            margin: 0; font-size: .72rem; line-height: 1.75; color: var(--s-muted);\n            overflow-wrap: anywhere; white-space: pre-line;\n        }\n\n        .setup-form { display: grid; gap: .9rem; margin: 0; }\n        .setup-form-grid { display: grid; gap: .9rem; grid-template-columns: repeat(auto-fit, minmax(14.5rem, 1fr)); }\n        .setup-field { display: flex; flex-direction: column; gap: .35rem; min-width: 0; }\n        .setup-label { font-size: .76rem; font-weight: 800; color: var(--s-text-soft); }\n        .setup-input {\n            width: 100%; min-height: 2.85rem; padding: .6rem .85rem; font-size: .85rem;\n            color: var(--s-text); background: var(--s-input-bg);\n            border: 1px solid var(--s-border-strong); border-radius: .75rem;\n            transition: border-color .18s, box-shadow .18s, background .18s;\n        }\n        .setup-input::placeholder { color: var(--s-muted); opacity: .72; }\n        .setup-input:focus {\n            outline: none; border-color: var(--s-brand);\n            box-shadow: 0 0 0 3px var(--s-brand-glow);\n        }\n        .setup-input-reveal-wrap { position: relative; width: 100%; }\n        .setup-input-reveal-wrap .setup-input { padding-inline-end: 3rem; }\n        .setup-reveal-toggle {\n            position: absolute; inset-inline-end: .4rem; top: 50%; transform: translateY(-50%);\n            display: inline-flex; align-items: center; justify-content: center; width: 2.1rem; height: 2.1rem;\n            padding: .4rem; border: 0; border-radius: .6rem; color: var(--s-muted);\n            background: transparent; cursor: pointer; transition: color .16s, background .16s;\n        }\n        /* LTR fields (tokens, account id) grow from the left, so the eye sits on the physical right. */\n        .setup-input[dir="ltr"] ~ .setup-reveal-toggle { inset-inline-end: auto; right: .45rem; }\n        .setup-reveal-toggle:hover { color: var(--s-brand); background: var(--s-brand-soft); }\n        .setup-reveal-toggle:focus-visible { outline: 2px solid var(--s-brand); outline-offset: 2px; }\n        .setup-reveal-toggle svg { width: 1.1rem; height: 1.1rem; }\n\n        .setup-btn {\n            width: 100%; min-height: 2.85rem; padding: .6rem 1.4rem; border-radius: .8rem; cursor: pointer;\n            display: inline-flex; align-items: center; justify-content: center; gap: .5rem;\n            font-size: .85rem; font-weight: 900; color: #06210e; text-align: center;\n            background: linear-gradient(135deg, var(--s-brand-lime) 0%, #3fbf3f 58%, var(--s-brand-strong) 100%);\n            box-shadow: 0 16px 32px -22px rgba(63, 181, 58, .9);\n            transition: filter .2s, box-shadow .2s, transform .2s, opacity .2s;\n        }\n        .setup-btn:hover { filter: brightness(1.05); transform: translateY(-1px); }\n        .setup-btn:active { transform: none; }\n        .setup-btn:focus-visible { outline: 2px solid var(--s-brand); outline-offset: 3px; }\n        .setup-btn-ghost {\n            background: var(--s-surface-2); color: var(--s-text);\n            border: 1px solid var(--s-border-strong); box-shadow: none;\n        }\n        .setup-btn-ghost:hover { border-color: var(--s-brand); color: var(--s-brand); background: var(--s-brand-soft); }\n        .setup-btn-disabled {\n            background: var(--s-surface-2); color: var(--s-muted);\n            border: 1px dashed var(--s-border-strong); box-shadow: none; cursor: not-allowed;\n        }\n        .setup-form .setup-btn { justify-self: start; width: auto; min-width: 13rem; max-width: 100%; }\n\n        .setup-notes { list-style: none; margin: 0; padding: 0; display: grid; gap: .5rem; }\n        .setup-notes li {\n            display: flex; align-items: flex-start; gap: .6rem; font-size: .81rem; line-height: 1.9;\n            padding: .6rem .9rem; border-radius: .8rem; color: var(--s-text-soft);\n            background: var(--s-surface-2); border: 1px solid var(--s-border);\n        }\n        .setup-note-dot {\n            flex: 0 0 auto; width: .38rem; height: .38rem; margin-top: .68rem; border-radius: 999px;\n            background: var(--s-brand); box-shadow: 0 0 0 3px var(--s-brand-soft);\n        }\n        .setup-note-body { min-width: 0; }\n        .setup-inline-code {\n            display: inline-block; direction: ltr; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n            font-size: .76rem; font-weight: 700; padding: .08rem .45rem; border-radius: .45rem;\n            color: var(--s-brand); background: var(--s-brand-soft); border: 1px solid rgba(63, 181, 58, .28);\n        }\n        .setup-note-extra { margin: .65rem 0 0; font-size: .73rem; color: var(--s-muted); }\n\n        .setup-warn, .setup-form-error, .setup-missing {\n            display: flex; align-items: flex-start; gap: .5rem; margin: 0;\n            padding: .65rem .85rem; border-radius: .75rem; font-size: .77rem; line-height: 1.85;\n        }\n        .setup-warn, .setup-missing { color: var(--s-warn); background: var(--s-warn-soft); border: 1px solid rgba(197, 141, 33, .30); }\n        .setup-form-error { color: var(--s-err); background: var(--s-err-soft); border: 1px solid rgba(207, 68, 55, .32); }\n        .setup-warn { align-self: start; }\n\n        .setup-enter-wrap { display: flex; flex-wrap: wrap; align-items: center; gap: .8rem 1.1rem; }\n        .setup-enter-wrap .setup-panel-head { margin: 0; flex: 0 1 auto; }\n        .setup-enter-wrap .setup-btn { width: auto; min-width: 13rem; flex: 0 0 auto; }\n        .setup-enter-wrap .setup-panel-hint { text-align: start; flex: 1 1 16rem; }\n\n        .setup-footer {\n            display: flex; flex-direction: column; align-items: center; gap: .55rem;\n            padding: clamp(.8rem, 1.8vw, 1.35rem) 0 .2rem;\n        }\n        /* Keep the same visual order (Website, GitHub) in both RTL and LTR. */\n        .setup-social { display: flex; align-items: center; justify-content: center; gap: .6rem; direction: ltr; }\n        .setup-social-link {\n            width: 2.7rem; height: 2.7rem; flex: 0 0 auto;\n            display: inline-flex; align-items: center; justify-content: center;\n            border-radius: 999px; color: var(--s-muted);\n            background: var(--s-surface); border: 1px solid var(--s-border);\n            box-shadow: 0 12px 26px -24px rgba(8, 32, 18, .8);\n            transition: color .2s, border-color .2s, background .2s, transform .2s, box-shadow .2s;\n        }\n        .setup-social-link:hover {\n            color: var(--s-brand); border-color: rgba(63, 181, 58, .45); background: var(--s-brand-soft);\n            transform: translateY(-2px); box-shadow: 0 18px 30px -24px rgba(63, 181, 58, .8);\n        }\n        .setup-social-link:focus-visible { outline: 2px solid var(--s-brand); outline-offset: 3px; }\n        .setup-social-link svg { width: 1.18rem; height: 1.18rem; }\n        .setup-footer-note { margin: 0; font-size: .68rem; color: var(--s-muted); opacity: .8; letter-spacing: .01em; }\n\n        /* Full-width rows: keep every section in the normal top-to-bottom flow. */\n        @media (min-width: 1024px) {\n            .setup-shell { padding-inline: clamp(1.5rem, 3vw, 3.5rem); }\n            .setup-main { grid-template-columns: minmax(0, 1fr); align-items: start; gap: .85rem; }\n            .setup-main > * { grid-column: 1 / -1; min-width: 0; }\n            .setup-hero { flex-direction: column; align-items: flex-start; gap: .15rem; padding-block: .4rem .6rem; }\n            .setup-hero-sub { max-width: none; text-align: start; }\n            .setup-status-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }\n            .setup-notes { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n            .setup-panel { padding: .75rem 1rem; }\n            .setup-notes li { padding: .4rem .7rem; font-size: .75rem; line-height: 1.65; }\n            .setup-form { gap: .6rem; }\n            .setup-form-grid { gap: .6rem; }\n            .setup-field .setup-panel-hint { font-size: .68rem; line-height: 1.6; }\n            .setup-enter-wrap { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 1.2rem; }\n            .setup-enter-wrap .setup-panel-head { margin: 0; }\n            .setup-enter-wrap .setup-panel-hint { text-align: start; }\n            .setup-enter-wrap .setup-btn { width: auto; min-width: 14rem; grid-column: 3; grid-row: 1; }\n            .setup-enter-wrap .setup-panel-hint { grid-column: 2; grid-row: 1; }\n        }\n\n        ${NEXA_TOAST_CSS}\n\n        @media (max-width: 700px) {\n            .setup-shell { padding-top: 1rem; gap: .85rem; }\n            .setup-panel { border-radius: .95rem; }\n            .setup-status-grid { grid-template-columns: minmax(0, 1fr); }\n            .setup-form .setup-btn, .setup-enter-wrap .setup-btn { width: 100%; justify-self: stretch; }\n            .setup-hero-sub { text-align: start; }\n            .setup-enter-wrap .setup-panel-hint { text-align: start; }\n            .setup-brand-logo { width: 2.6rem; height: 2.6rem; border-radius: .8rem; }\n            .setup-brand-logo img { width: 1.6rem; height: 1.6rem; }\n            .setup-social-link { width: 2.55rem; height: 2.55rem; }\n        }\n        /* Short laptop screens: compact everything so the page still fits without scrolling. */\n        @media (min-width: 1024px) and (max-height: 820px) {\n            .setup-shell { padding-top: .7rem; gap: .55rem; }\n            .setup-hero { padding: 0 .2rem; }\n            .setup-hero-title { font-size: 1.16rem; }\n            .setup-hero-sub { font-size: .76rem; }\n            .setup-panel { padding: .8rem 1rem; }\n            .setup-panel-head { margin-bottom: .55rem; }\n            .setup-panel-title { font-size: .88rem; }\n            .setup-status-card { padding: .6rem .95rem; gap: .2rem; }\n            .setup-status-detail { font-size: .69rem; line-height: 1.6; }\n            .setup-notes { gap: .4rem; }\n            .setup-notes li { padding: .5rem .8rem; font-size: .78rem; line-height: 1.7; }\n            .setup-note-extra { margin-top: .45rem; font-size: .7rem; }\n            .setup-form { gap: .65rem; }\n            .setup-form-grid { gap: .65rem; }\n            .setup-input { min-height: 2.6rem; }\n            .setup-btn { min-height: 2.6rem; }\n            .setup-label { font-size: .73rem; }\n            .setup-footer { padding-top: .55rem; gap: .4rem; }\n            .setup-social-link { width: 2.4rem; height: 2.4rem; }\n            .setup-social-link svg { width: 1.05rem; height: 1.05rem; }\n            .setup-footer-note { font-size: .64rem; }\n        }\n        @media (min-width: 1024px) and (max-height: 740px) {\n            .setup-shell { padding-top: .5rem; gap: .45rem; }\n            .setup-panel { padding: .7rem .9rem; }\n            .setup-hero-title { font-size: 1.05rem; }\n            .setup-hero-sub { font-size: .72rem; }\n            .setup-status-detail { font-size: .66rem; line-height: 1.5; }\n            .setup-notes li { padding: .42rem .75rem; font-size: .75rem; line-height: 1.6; }\n            .setup-input, .setup-btn { min-height: 2.45rem; }\n            .setup-footer { padding-top: .4rem; }\n        }\n\n        /* Minimal finish; social links follow the last section, not the viewport bottom. */\n        .setup-main { flex: 0 0 auto; }\n        .setup-footer { padding-top: .35rem; gap: .4rem; }\n        body.setup-page, html.dark body.setup-page { background-image: none; }\n        .setup-panel { box-shadow: none; border-radius: .8rem; animation: none; }\n        .setup-status-card { border-radius: .6rem; }\n        .setup-status-card::before { width: 2px; opacity: .5; }\n        .setup-status-dot { box-shadow: none; width: .4rem; height: .4rem; }\n        .setup-panel > .setup-panel-head:first-child .setup-panel-title::before { box-shadow: none; }\n        .setup-note-dot { box-shadow: none; }\n        .setup-notes li { background: transparent; border-color: transparent; border-radius: 0; }\n        .setup-btn { background: var(--s-brand); box-shadow: none; border-radius: .6rem; }\n        .setup-btn-ghost, .setup-btn-disabled { background: var(--s-surface-2); }\n        .setup-brand-logo, .setup-social-link { box-shadow: none; }\n        .setup-social-link { border-color: var(--s-border-strong); }\n        .setup-social-link:hover { box-shadow: none; }\n        .setup-status-card:hover, .setup-btn:hover { transform: none; }\n\n        @media (prefers-reduced-motion: reduce) {\n            .setup-panel { animation: none !important; }\n            .setup-social-link, .setup-btn, .setup-status-card { transition: none !important; }\n        }\n    </style>\n    <script>\n        (function() {\n            try {\n                var theme = localStorage.getItem('color-theme') || localStorage.getItem('nexa-theme');\n                if (theme === 'dark' || (!theme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {\n                    document.documentElement.classList.add('dark');\n                }\n                var lang = localStorage.getItem('nexa-admin-lang') || 'fa';\n                document.documentElement.lang = lang;\n                document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr';\n            } catch (e) {}\n        })();\n    <\/script>\n</head>\n<body class="setup-page">\n<body class="setup-page">\n    ${NEXA_TOAST_HTML}\n    ${NEXA_TOAST_SCRIPT}\n    <div class="setup-shell">\n        <header class="setup-topbar">\n            <div class="setup-brand">\n                <span class="setup-brand-logo"><img src="${NEXA_LOGO_URL}" alt="Nexa Panel"></span>\n                <span class="setup-brand-text">\n                    <span class="setup-brand-name">Nexa Panel</span>\n                    <span class="setup-brand-sub" data-i18n="brand_sub">راه‌اندازی اولیه</span>\n                </span>\n            </div>\n        </header>\n        <main class="setup-main">\n            <section class="setup-hero">\n                <h1 class="setup-hero-title" data-i18n="setup_title">راه‌اندازی اولیه Nexa Panel</h1>\n                <p class="setup-hero-sub" data-i18n="setup_subtitle">برای شروع کار با پنل، اتصال‌ها را بررسی کنید و رمز عبور ورود را تنظیم نمایید.</p>\n            </section>\n            <section class="setup-panel setup-enter-wrap" id="setup-enter-wrap">\n                <div class="setup-panel-head">\n                    <h2 class="setup-panel-title" data-i18n="enter_title">ورود به پنل</h2>\n                </div>\n                ${panelEntryBlock}\n                ${enterHint}\n            </section>\n            ${passwordPanel}\n            ${cfTokenForm}\n            ${missingVarsMsg}\n            <section class="setup-panel setup-status-panel" aria-labelledby="setup-status-title">\n                <div class="setup-panel-head">\n                    <h2 class="setup-panel-title" id="setup-status-title" data-i18n="status_title">وضعیت اتصالات</h2>\n                    <p class="setup-panel-hint" data-i18n="status_hint">وضعیت به‌صورت زنده از محیط اجرای پنل خوانده می‌شود.</p>\n                </div>\n                <div class="setup-status-grid" id="status-list">\n                    ${statusCards}\n                </div>\n            </section>\n        </main>\n        <footer class="setup-footer">\n            <nav class="setup-social" aria-label="Nexa Team">\n                <a class="setup-social-link" href="https://github.com/farzadqavidel/nexa-panel" target="_blank" rel="noopener noreferrer" aria-label="GitHub" title="GitHub">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M9 19c-5 1.5-5-2.5-7-3m14 6v-3.87a3.37 3.37 0 0 0-.94-2.61c3.14-.35 6.44-1.54 6.44-7A5.44 5.44 0 0 0 20 4.77 5.07 5.07 0 0 0 19.91 1S18.73.65 16 2.48a13.38 13.38 0 0 0-7 0C6.27.65 5.09 1 5.09 1A5.07 5.07 0 0 0 5 4.77a5.44 5.44 0 0 0-1.5 3.78c0 5.42 3.3 6.61 6.44 7A3.37 3.37 0 0 0 9 18.13V22"/></svg>\n                </a>\n                <a class="setup-social-link" href="https://nexa.privte.workers.dev/" target="_blank" rel="noopener noreferrer" aria-label="Nexa website" title="Nexa website">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>\n                </a>\n            </nav>\n            <p class="setup-footer-note">Nexa Panel &middot; Nexa Team</p>\n        </footer>\n    </div>\n    <script>\n        var SETUP_I18N = ${JSON.stringify(setupI18n)};\n        function setupT(key) {\n            var lang = localStorage.getItem('nexa-admin-lang') || 'fa';\n            return (SETUP_I18N[lang] || SETUP_I18N.fa)[key] || key;\n        }\n        function applySetupI18n(lang) {\n            var dict = SETUP_I18N[lang] || SETUP_I18N.fa;\n            document.querySelectorAll('[data-i18n]').forEach(function(el) {\n                var key = el.getAttribute('data-i18n');\n                if (!dict[key]) return;\n                if (key === 'page_title') {\n                    document.title = dict[key];\n                    return;\n                }\n                if (el.children.length === 0) {\n                    el.textContent = dict[key];\n                }\n            });\n            document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el) {\n                var key = el.getAttribute('data-i18n-placeholder');\n                if (dict[key]) el.placeholder = dict[key];\n            });\n            document.querySelectorAll('[data-i18n-aria-label]').forEach(function(el) {\n                var key = el.getAttribute('data-i18n-aria-label');\n                if (dict[key]) el.setAttribute('aria-label', dict[key]);\n            });\n            document.querySelectorAll('[data-i18n-title]').forEach(function(el) {\n                var key = el.getAttribute('data-i18n-title');\n                if (dict[key]) el.title = dict[key];\n            });\n        }\n        function setSetupLang(lang) {\n            localStorage.setItem('nexa-admin-lang', lang);\n            document.documentElement.lang = lang;\n            document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr';\n            var faBtn = document.getElementById('setup-lang-fa');\n            var enBtn = document.getElementById('setup-lang-en');\n            if (faBtn) faBtn.classList.toggle('active', lang === 'fa');\n            if (enBtn) enBtn.classList.toggle('active', lang === 'en');\n            applySetupI18n(lang);\n        }\n        window.setSetupLang = setSetupLang;\n        function toggleSetupTheme() {\n            var root = document.documentElement;\n            var isDark = root.classList.toggle('dark');\n            localStorage.setItem('color-theme', isDark ? 'dark' : 'light');\n            localStorage.setItem('nexa-theme', isDark ? 'dark' : 'light');\n        }\n        window.toggleSetupTheme = toggleSetupTheme;\n        // Uses the shared Nexa toast (icon, auto-dismiss progress, stacking).\n        var showSetupToast = window.showNexaToast;\n        window.showNexaToast = showSetupToast;\n\n        var setupLangFaBtn = document.getElementById('setup-lang-fa');\n        if (setupLangFaBtn) setupLangFaBtn.addEventListener('click', function() { setSetupLang('fa'); });\n        var setupLangEnBtn = document.getElementById('setup-lang-en');\n        if (setupLangEnBtn) setupLangEnBtn.addEventListener('click', function() { setSetupLang('en'); });\n        var setupThemeBtn = document.getElementById('setup-theme-btn');\n        if (setupThemeBtn) setupThemeBtn.addEventListener('click', toggleSetupTheme);\n        setSetupLang(localStorage.getItem('nexa-admin-lang') || 'fa');\n\n        document.querySelectorAll('[data-setup-password-toggle]').forEach(function(button) {\n            button.addEventListener('click', function() {\n                var input = document.getElementById(button.getAttribute('data-setup-password-toggle'));\n                if (!input) return;\n                var visible = input.type === 'password';\n                input.type = visible ? 'text' : 'password';\n                button.setAttribute('aria-pressed', visible ? 'true' : 'false');\n                var labelKey = visible ? 'password_hide' : 'password_show';\n                button.setAttribute('data-i18n-aria-label', labelKey);\n                button.setAttribute('data-i18n-title', labelKey);\n                var lang = localStorage.getItem('nexa-admin-lang') || 'fa';\n                var dict = SETUP_I18N[lang] || SETUP_I18N.fa;\n                if (dict[labelKey]) { button.setAttribute('aria-label', dict[labelKey]); button.title = dict[labelKey]; }\n                var eyeOpen = button.querySelector('[data-eye-open]');\n                var eyeClosed = button.querySelector('[data-eye-closed]');\n                if (eyeOpen) eyeOpen.classList.toggle('hidden', visible);\n                if (eyeClosed) eyeClosed.classList.toggle('hidden', !visible);\n            });\n        });\n\n        var form = document.getElementById('setup-form');\n        if (form) {\n            var submitBtn = document.getElementById('setup-submit');\n            form.addEventListener('submit', async function(e) {\n                e.preventDefault();\n                var password = document.getElementById('setup-password').value.trim();\n                var confirmPassword = document.getElementById('setup-password-confirm').value.trim();\n                if (!password) {\n                    showSetupToast(setupT('pwd_required'), 'error');\n                    return;\n                }\n                if (password.length < 4) {\n                    showSetupToast(setupT('pwd_minlength'), 'error');\n                    return;\n                }\n                if (password !== confirmPassword) {\n                    showSetupToast(setupT('pwd_mismatch'), 'error');\n                    return;\n                }\n                submitBtn.disabled = true;\n                submitBtn.textContent = setupT('pwd_saving');\n                try {\n                    var manualAccountId = ((document.getElementById('setup-account-id') || {}).value || '').trim();\n                    var res = await fetch('/api/setup', {\n                        method: 'POST',\n                        headers: { 'Content-Type': 'application/json' },\n                        body: JSON.stringify({ password: password, confirmPassword: confirmPassword, cf_account_id: manualAccountId })\n                    });\n                    var data;\n                    try {\n                        data = await res.json();\n                    } catch (parseErr) {\n                        showSetupToast(setupT('server_error'), 'error');\n                        submitBtn.disabled = false;\n                        submitBtn.textContent = setupT('pwd_submit');\n                        return;\n                    }\n                    if (!res.ok) {\n                        showSetupToast(data.error || setupT('pwd_error'), 'error');\n                        submitBtn.disabled = false;\n                        submitBtn.textContent = setupT('pwd_submit');\n                        return;\n                    }\n                    if (data && data.warning) {\n                        // The password is saved and login will work, but the\n                        // Cloudflare variable was not updated: say so instead\n                        // of a plain success message.\n                        showSetupToast(String(data.warning), 'error');\n                    } else {\n                        showSetupToast(setupT('pwd_success'), 'success');\n                    }\n                    var enterWrap = document.getElementById('setup-enter-wrap');\n                    if (enterWrap) {\n                        enterWrap.innerHTML = '<div class="setup-panel-head"><h2 class="setup-panel-title" data-i18n="enter_title">'\n                            + setupT('enter_title') + '</h2></div><a href="/admin" class="setup-btn" data-i18n="enter_panel">'\n                            + setupT('enter_panel') + '</a>';\n                    }\n                    setTimeout(function() { window.location.href = '/admin'; }, 1500);\n                } catch (err) {\n                    showSetupToast(setupT('server_error'), 'error');\n                    submitBtn.disabled = false;\n                    submitBtn.textContent = setupT('pwd_submit');\n                }\n            });\n        }\n        var enterPanelLink = document.querySelector('a.setup-btn[data-i18n="enter_panel"]');\n        if (enterPanelLink) {\n            enterPanelLink.addEventListener('click', function(e) {\n                e.preventDefault();\n                showSetupToast(setupT('enter_success'), 'success');\n                setTimeout(function() { window.location.href = '/admin'; }, 800);\n            });\n        }\n        var cfForm = document.getElementById('setup-cf-form');\n        if (cfForm) {\n            var cfSubmitBtn = document.getElementById('setup-cf-submit');\n            var cfErrorEl = document.getElementById('setup-cf-error');\n            cfForm.addEventListener('submit', async function(e) {\n                e.preventDefault();\n                var cfToken = (document.getElementById('setup-cf-token') || {}).value || '';\n                cfErrorEl.classList.add('hidden');\n                cfErrorEl.textContent = '';\n                if (!cfToken.trim()) {\n                    cfErrorEl.textContent = setupT('setup_cf_token_required');\n                    cfErrorEl.classList.remove('hidden');\n                    return;\n                }\n                cfSubmitBtn.disabled = true;\n                cfSubmitBtn.textContent = setupT('setup_cf_token_saving');\n                try {\n                    var cfAccountIdManual = ((document.getElementById('setup-cf-account-id') || {}).value || '').trim();\n                    var res = await fetch('/api/cf-credentials', {\n                        method: 'POST',\n                        headers: { 'Content-Type': 'application/json' },\n                        body: JSON.stringify({ cf_token: cfToken.trim(), cf_account_id: cfAccountIdManual })\n                    });\n                    var data;\n                    try {\n                        data = await res.json();\n                    } catch (parseErr) {\n                        cfErrorEl.textContent = setupT('server_error');\n                        cfErrorEl.classList.remove('hidden');\n                        cfSubmitBtn.disabled = false;\n                        cfSubmitBtn.textContent = setupT('setup_cf_token_submit');\n                        return;\n                    }\n                    if (!res.ok) {\n                        if (res.status === 401) {\n                            window.location.href = '/admin';\n                            return;\n                        }\n                        cfErrorEl.textContent = data.error || setupT('setup_cf_token_error');\n                        cfErrorEl.classList.remove('hidden');\n                        cfSubmitBtn.disabled = false;\n                        cfSubmitBtn.textContent = setupT('setup_cf_token_submit');\n                        return;\n                    }\n                    showSetupToast(setupT('setup_cf_token_success'), 'success');\n                    setTimeout(function() { window.location.href = '/admin'; }, 1500);\n                } catch (err) {\n                    cfErrorEl.textContent = setupT('server_error');\n                    cfErrorEl.classList.remove('hidden');\n                    cfSubmitBtn.disabled = false;\n                    cfSubmitBtn.textContent = setupT('setup_cf_token_submit');\n                }\n            });\n        }\n    <\/script>\n</body>\n</html>`;
}

function buildNexaStatusPage(startedAtMs) {
    const started = Number(startedAtMs) || Date.now();
    return `<!DOCTYPE html>\n<html lang="fa" dir="rtl">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Nexa</title>\n<script>(function(){try{var l=localStorage.getItem('nexa-admin-lang')||'fa';document.documentElement.lang=l;document.documentElement.dir=l==='fa'?'rtl':'ltr';}catch(e){}})();<\/script>\n${NEXA_FAVICON_TAGS}\n<link href="https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css" rel="stylesheet">\n<style>\n  :root{\n    --bg:#f4f8f6;--bg2:#e8f2ed;--card:#fff;--card2:#eef5f1;--text:#111827;--muted:#64748b;\n    --accent:#3FB53A;--accent2:#1E8A2E;--border:#dfe8e4;--glow:rgba(63,181,58,0.28);\n  }\n  html.dark{\n    --bg:#0b0f0d;--bg2:#0f1512;--card:#131a17;--card2:#0f1512;--text:#e8ece9;--muted:#8b95a8;\n    --accent:#79E62A;--accent2:#3FB53A;--border:#22302a;--glow:rgba(121,230,42,0.22);\n  }\n  *{box-sizing:border-box;}\n  .lang-line,.lang-inline{display:none;}\n  html[lang="fa"] .lang-line.fa,html[lang="en"] .lang-line.en{display:block;}\n  html[lang="fa"] .lang-inline.fa,html[lang="en"] .lang-inline.en{display:inline;}\n  body{\n    margin:0;min-height:100vh;font-family:'Vazirmatn',sans-serif;color:var(--text);\n    display:flex;align-items:center;justify-content:center;transition:background .3s,color .3s;\n    background:\n      radial-gradient(ellipse 70% 55% at 15% 10%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 55%),\n      radial-gradient(ellipse 60% 50% at 90% 90%, color-mix(in srgb, var(--accent2) 8%, transparent), transparent 50%),\n      linear-gradient(155deg, var(--bg) 0%, var(--bg2) 100%);\n  }\n  .card{\n    max-width:30rem;width:100%;margin:1rem;padding:2.75rem 2.25rem;text-align:center;position:relative;\n    border-radius:1.75rem;\n    background: linear-gradient(160deg, var(--card) 0%, var(--card2) 100%);\n    border:1px solid color-mix(in srgb, var(--accent) 22%, var(--border));\n    box-shadow:\n      0 1px 0 color-mix(in srgb, #fff 25%, transparent) inset,\n      0 -20px 40px -30px color-mix(in srgb, var(--accent) 30%, transparent) inset,\n      0 24px 60px -18px rgba(0,0,0,.22),\n      0 8px 24px -12px var(--glow);\n    overflow:hidden;\n  }\n  .card::before{\n    content:'';position:absolute;inset-inline:0;top:0;height:3px;\n    background:linear-gradient(90deg, transparent, var(--accent), var(--accent2), transparent);\n    opacity:.85;\n  }\n  .logo{\n    width:5rem;height:5rem;margin:0 auto 1.35rem;border-radius:1.15rem;overflow:hidden;position:relative;\n    box-shadow:0 14px 30px -10px var(--glow), 0 2px 8px rgba(0,0,0,.1);\n    transform:translateZ(0);\n    animation:float 4s ease-in-out infinite;\n  }\n  @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}\n  .logo img{width:100%;height:100%;object-fit:contain;}\n  h1{font-size:1.5rem;font-weight:900;margin:0 0 .6rem;letter-spacing:.01em;}\n  .sub{font-size:.85rem;color:var(--muted);margin:0 0 .5rem;line-height:1.7;}\n  .dot{\n    display:inline-block;width:.55rem;height:.55rem;border-radius:9999px;\n    background:radial-gradient(circle at 30% 30%, #fff, var(--accent));\n    margin-inline-end:.45rem;box-shadow:0 0 12px var(--accent), 0 0 2px var(--accent);\n    animation:pulse 1.8s infinite;\n  }\n  @keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.55;transform:scale(.85)}}\n  .uptime{\n    margin-top:1.85rem;padding-top:1.35rem;border-top:1px solid color-mix(in srgb, var(--accent) 15%, var(--border));\n    font-size:.8rem;color:var(--muted);\n  }\n  .uptime b{\n    color:var(--text);font-family:ui-monospace,monospace;display:block;margin-top:.5rem;font-size:1.15rem;\n    letter-spacing:.03em;\n    text-shadow:0 0 18px var(--glow);\n  }\n  .theme-btn{\n    position:fixed;top:1rem;left:1rem;width:2.5rem;height:2.5rem;border-radius:.85rem;\n    background:var(--card);border:1px solid var(--border);color:var(--muted);\n    display:flex;align-items:center;justify-content:center;cursor:pointer;transition:all .2s;\n    box-shadow:0 6px 16px -6px rgba(0,0,0,.15);\n  }\n  .theme-btn:hover{border-color:color-mix(in srgb, var(--accent) 40%, var(--border));transform:translateY(-1px);}\n  .theme-btn svg{width:1.2rem;height:1.2rem;}\n  .theme-btn .icon-sun{display:none}\n  .theme-btn .icon-moon{display:block}\n  html.dark .theme-btn .icon-sun{display:block}\n  html.dark .theme-btn .icon-moon{display:none}\n</style>\n</head>\n<body>\n<button class="theme-btn" onclick="(function(){document.documentElement.classList.toggle('dark');try{localStorage.setItem('nexa-status-theme',document.documentElement.classList.contains('dark')?'dark':'light');}catch(e){}})()" title="تغییر تم">\n  <svg class="icon-sun" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="color:#facc15"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707m12.728 0l-.707-.707M6.343 6.343l-.707-.707M14 12a2 2 0 11-4 0 2 2 0 014 0z"></path></svg>\n  <svg class="icon-moon" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"></path></svg>\n</button>\n<div class="card">\n  <div class="logo"><img src="${NEXA_LOGO_URL}" alt="Nexa"></div>\n  <h1><span class="dot"></span>Nexa</h1>\n  <p class="sub lang-line fa">نکسا در حال حاضر فعال است و به درستی کار می‌کند.</p>\n  <p class="sub lang-line en" dir="ltr">Nexa is currently up and running.</p>\n  <div class="uptime">\n    <span class="lang-inline fa">مدت زمان روشن بودن پنل</span><span class="lang-inline en" dir="ltr">Panel uptime</span>\n    <b id="uptime-val">--</b>\n  </div>\n</div>\n<script>\n(function(){\n  try{\n    var t=localStorage.getItem('nexa-status-theme');\n    if(t==='dark'||(!t&&window.matchMedia('(prefers-color-scheme: dark)').matches)) document.documentElement.classList.add('dark');\n  }catch(e){}\n  try{\n    var isDarkInit = document.documentElement.classList.contains('dark');\n    var iconEl = document.getElementById('nexa-theme-icon');\n    if(iconEl){\n      iconEl.innerHTML = isDarkInit\n        ? '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707m12.728 0l-.707-.707M6.343 6.343l-.707-.707M14 12a2 2 0 11-4 0 2 2 0 014 0z"></path>'\n        : '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"></path>';\n    }\n  }catch(e){}\n  var started=${Number(started)};\n  function fmt(ms){\n    var s=Math.floor(ms/1000);\n    var d=Math.floor(s/86400); s%=86400;\n    var h=Math.floor(s/3600); s%=3600;\n    var m=Math.floor(s/60); s%=60;\n    var hh=(h<10?'0':'')+h, mm=(m<10?'0':'')+m, ss=(s<10?'0':'')+s;\n    return (d?d+' روز، ':'') + hh+':'+mm+':'+ss;\n  }\n  function tick(){ document.getElementById('uptime-val').textContent = fmt(Date.now()-started); }\n  tick();\n  setInterval(tick, 1000);\n})();\n<\/script>\n</body>\n</html>`;
}

const NEXA_PUBLIC_LANG_TOGGLE = `<div class="nexa-public-lang-switch" role="group" aria-label="Language"><button type="button" data-public-lang="fa" onclick="setNexaPublicLang('fa')">فا</button><button type="button" data-public-lang="en" onclick="setNexaPublicLang('en')">EN</button></div>`;

const NEXA_PUBLIC_I18N_SCRIPT = `<script>\n(function() {\n  var fa = { 'وضعیت سرویس':'Service status','نام سرویس':'Service name','فعال':'Active','غیرفعال':'Inactive','وضعیت سرویس: فعال':'Service status: Active','وضعیت سرویس: غیرفعال':'Service status: Inactive', 'حجم مصرفی':'Usage','زمان اشتراک':'Subscription time','مصرف شده:':'Used:','حجم کل:':'Total:','باقی‌مانده:':'Remaining:','کل اعتبار:':'Validity:', 'نامحدود':'Unlimited','دریافت لینک اشتراک':'Get subscription links','کپی کانفیگ VLESS':'Copy VLESS config','کپی لینک ساب':'Copy subscription link','QR لینک ساب':'Subscription QR','آموزش اتصال':'Connection guide','بازگشت':'Back','راهنما':'Guide', 'این سرویس فروشی نیست و به صورت رایگان می‌توانید استفاده کنید.':'This service is free and not for sale.','سرویس یافت نشد':'Service not found','کاربر مورد نظر وجود ندارد':'User not found', 'سرویس مورد نظر یافت نشد یا حذف شده است. لطفاً لینک صحیح را از پنل یا بات دریافت کنید.':'The service was not found or has been deleted. Please get a valid link from the panel or bot.', 'اسکن کد QR لینک ساب':'Scan subscription QR code','بستن':'Close','در حال بارگذاری...':'Loading...','حجم کل':'Total volume','زمان باقی‌مانده':'Time remaining', 'راهنمای اتصال — اندروید':'Connection guide — Android','راهنمای اتصال — آیفون (iOS)':'Connection guide — iPhone (iOS)','راهنمای اتصال — ویندوز / مک':'Connection guide — Windows / Mac', 'اندروید':'Android','آیفون':'iPhone','ویندوز / مک':'Windows / Mac','مک':'Mac','ویندوز':'Windows', 'هنوز اتصالی ثبت نشده است.':'No connections recorded yet.','بروزرسانی':'Refresh','حذف همه':'Delete all','۰ رویداد':'0 events','نام کاربری اجباری است':'Username is required', 'نتوانستید متصل شوید؟':'Could not connect?','از پشتیبانی سایت کمک بگیرید':'Get help from website support','نکته:':'Tip:','اتصال':'Connection','دریافت کانفیگ':'Config download','این سرویس فروشی نیست و به صورت رایگان می‌توانید استفاده کنید. از این بخش می‌توانید وضعیت سرویس، میزان مصرف، زمان باقی‌مانده و لینک‌های اتصال را مدیریت کنید.':'This service is free and not for sale. Use this page to view service status, usage, remaining time, and connection links.','در حال بارگذاری...':'Loading...','وضعیت سرویس: غیرفعال — پایان زمان و حجم سرویس':'Service status: Inactive — time and volume expired','وضعیت سرویس: غیرفعال — پایان حجم سرویس':'Service status: Inactive — volume expired','وضعیت سرویس: غیرفعال — پایان زمان سرویس':'Service status: Inactive — time expired','وضعیت سرویس: غیرفعال — قطع شدن دستی توسط ادمین':'Service status: Inactive — manually disabled by admin','وضعیت سرویس: غیرفعال — قطع تمامی سرویس‌ها':'Service status: Inactive — all services are disabled','وضعیت سرویس: غیرفعال (اتمام ریکوئست)':'Service status: Inactive — request limit reached','آموزش اتصال':'Connection guide','دریافت کانفیگ':'Config download','IP':'IP','پورت':'Port','پینگ':'Ping','جیتر':'Jitter','کپی':'Copy' };\n  Object.assign(fa, {\n    'آموزش اتصال - Nexa Team':'Connection Guide - Nexa Team',\n    'اپ V2rayNG را از لینک زیر دانلود کنید:':'Download V2rayNG from the link below:',\n    'اپ را باز کنید':'Open the app',\n    'در بالا راست بزنید':'Tap the button at the top right',\n    'گزینه':'Option',\n    'را انتخاب کنید':'Select it',\n    'را بزنید':'Tap it',\n    '(لینک کانفیگ باید از قبل کپی شده باشد)':'(Copy the configuration link first)',\n    'کانفیگ در لیست ظاهر می‌شود — روی آن بزنید تا انتخاب شود':'The config appears in the list. Tap it to select it.',\n    'دکمه':'button',\n    'پایین صفحه را بزنید , اکنون با موفقیت متصل شدید .':'Tap the button at the bottom to connect.',\n    'نکته:':'Tip:',\n    'برای مشاهده جزئیات سرویس و اپدیت کانفیگ‌ها در زمان قطعی، کافی است از':'To view service details and update configurations during an outage, use',\n    '۳ نقطه':'the three-dot menu',\n    'بالای صفحه گزینه آخر':'the last option at the top',\n    'بروزرسانی اشتراک':'Update subscription',\n    'یا همان':'or',\n    'را بزنید.':'Tap it.',\n    'نتوانستید متصل شوید؟':'Unable to connect?',\n    'از پشتیبانی سایت کمک بگیرید':'Get help from website support',\n    'اپ Streisand را از App Store دانلود کنید:':'Download Streisand from the App Store:',\n    'کانفیگ اضافه شد — کنارش Connect را بزنید':'Config added. Tap Connect next to it.',\n    'در پنجره‌ای که باز می‌شود Allow را بزنید':'Tap Allow in the pop-up window',\n    'نرم‌افزار v2rayN را دانلود کنید:':'Download v2rayN:',\n    'فایل zip را extract کنید و v2rayN.exe را اجرا کنید':'Extract the zip and run v2rayN.exe',\n    'در تسک‌بار روی آیکون برنامه راست‌کلیک کنید':'Right-click the app icon in the taskbar',\n    'را بزنید و گزینه اول نام دلخواه و گزینه دوم لینک کپی شده را وارد کنید و روی گزینه تایید بزنید':'Click +, enter a name and paste the copied link, then confirm',\n    'از منوی بالا روی گروه اشتراک زده و گزینه سوم را بزنید .':'Open the subscription group from the top menu and choose the third option.',\n    'اکنون برای متصل شدن در پایین صفحه گزینه پاک کردن سیستم پروکسی رو روی گزینه دوم بزارید .':'To connect, set Clear system proxy at the bottom to the second option.',\n    'اپ FoXray را از Mac App Store دانلود کنید':'Download FoXray from the Mac App Store',\n    'بزنید و Import from clipboard را انتخاب کنید':'and select Import from clipboard',\n    'کانفیگ را انتخاب و Connect بزنید':'Select the config and tap Connect',\n    'روی':'Tap'\n  });\n  function translate(root) {\n    var lang=localStorage.getItem('nexa-admin-lang') || 'fa';\n    document.documentElement.lang=lang; document.documentElement.dir=lang==='fa'?'rtl':'ltr';\n    document.querySelectorAll('[data-public-lang]').forEach(function(b){ b.classList.toggle('active',lang===b.getAttribute('data-public-lang')); });\n    if (lang !== 'en') return;\n    var walker=document.createTreeWalker(root||document.body,NodeFilter.SHOW_TEXT), n;\n    while(n=walker.nextNode()) { var v=n.nodeValue.trim(); if(!v) continue; Object.keys(fa).sort(function(a,b){ return b.length-a.length; }).forEach(function(k){ var cur=n.nodeValue; if(cur===k) n.nodeValue=fa[k]; else if(cur.indexOf(k)>=0) n.nodeValue=cur.split(k).join(fa[k]); }); }\n    document.querySelectorAll('[title]').forEach(function(el){ Object.keys(fa).forEach(function(k){ if(el.title===k) el.title=fa[k]; }); });\n    document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(function(el){ Object.keys(fa).forEach(function(k){ if(el.placeholder===k) el.placeholder=fa[k]; }); });\n  }\n  window.setNexaPublicLang=function(lang){ lang=(lang==='en'||lang==='fa')?lang:((localStorage.getItem('nexa-admin-lang')||'fa')==='fa'?'en':'fa'); localStorage.setItem('nexa-admin-lang',lang); location.reload(); };\n  translate(document.body);\n  document.addEventListener('DOMContentLoaded',function(){ if((localStorage.getItem('nexa-admin-lang')||'fa')==='en'){ var o=new MutationObserver(function(){translate(document.body);}); o.observe(document.body,{childList:true,subtree:true,characterData:true}); setTimeout(function(){o.disconnect();},5000); } });\n})();\n<\/script>`;

