const NEXA_GLOBAL_PAGE_CSS = `<style>\n    :root { --bg:#0A0F0C; --card:#111A15; --border:rgba(121,230,42,.14); --border-hi:rgba(121,230,42,.32); --g1:#7FEE2E; --text-dim:#94A79B; }\n    html[data-theme="light"] { --bg:#F6F8F3; --card:#FFFFFF; --border:rgba(30,80,20,.12); --border-hi:rgba(30,80,20,.24); --g1:#4FBF2A; --text-dim:#4C5C51; }\n    .nav-actions { display:inline-flex; align-items:center; gap:4px; padding:4px; border:1px solid var(--border); border-radius:99px; background:color-mix(in srgb,var(--card) 70%,transparent); backdrop-filter:blur(8px); -webkit-backdrop-filter:blur(8px); flex:0 0 auto; }\n    .nav-actions .icon-btn { width:36px; height:36px; flex:0 0 36px; padding:0; line-height:1; border:0; background:none; cursor:pointer; display:inline-flex; align-items:center; justify-content:center; border-radius:99px; color:var(--text-dim); position:relative; isolation:isolate; transition:color .25s ease,transform .25s cubic-bezier(.2,.8,.2,1); }\n    .nav-actions .icon-btn::before { position:absolute; inset:0; border-radius:inherit; z-index:-1; content:""; background:linear-gradient(140deg,rgba(127,238,46,.22),rgba(127,238,46,.06)); opacity:0; transform:scale(.6); transition:opacity .25s ease,transform .3s cubic-bezier(.2,.8,.2,1); }\n    .nav-actions .icon-btn:hover { color:var(--g1); }\n    .nav-actions .icon-btn:hover::before { opacity:1; transform:scale(1); }\n    .nav-actions .icon-btn:active { transform:scale(.92); }\n    .nav-actions .icon-btn:focus-visible { outline:2px solid var(--g1); outline-offset:3px; }\n    .nav-actions .icon { width:17px; height:17px; display:block; fill:none; stroke:currentColor; stroke-width:1.7; stroke-linecap:round; stroke-linejoin:round; transition:transform .5s cubic-bezier(.2,.8,.2,1); }\n    .nav-actions .icon-btn:hover .icon { transform:rotate(25deg); }\n    .nav-actions .lang-btn { font-family:'Space Grotesk','IBM Plex Sans',sans-serif; font-size:12px; font-weight:700; letter-spacing:.06em; padding:0; padding-top:1px; }\n    .nexa-global-floating { position:fixed; top:16px; inset-inline-end:16px; z-index:9999; }\n    .adm-topbar-actions .nexa-global-actions, .svc-header-actions .nexa-global-actions, .st-topbar .nexa-global-actions { position:relative; inset:auto; }\n    .adm-topbar-actions .nexa-global-actions { margin-inline-start:0; }\n    .nexa-global-hidden { display:none !important; }\n@keyframes nexa-global-page-in { from { opacity:0; transform:translateY(12px) scale(.99); } to { opacity:1; transform:none; } }\n    @keyframes nexa-global-field-in { from { opacity:0; transform:translateY(7px); } to { opacity:1; transform:none; } }\n    @keyframes nexa-global-fade { from { opacity:0; } to { opacity:1; } }\n    body { animation:nexa-global-fade .36s ease both; }\n    .login-card,.setup-card,.adm-content,.svc-wrap,.st-shell,.card { animation:nexa-global-page-in .54s cubic-bezier(.2,.75,.25,1) both; }\n    input:not([type="hidden"]),select,textarea { animation:nexa-global-field-in .44s cubic-bezier(.2,.75,.25,1) .06s both; transition:border-color .24s ease,box-shadow .24s ease,background-color .24s ease,transform .24s ease; }\n    button,a { -webkit-tap-highlight-color:transparent; transition-duration:.23s; transition-timing-function:cubic-bezier(.2,.75,.25,1); }\n    button:not(:disabled):active { transform:scale(.975); }\n    button.adm-password-toggle:not(:disabled):active,button.setup-reveal-toggle:not(:disabled):active,button.login-pwd-toggle:not(:disabled):active { transform:translateY(-50%); }\n    button:not(:disabled):hover { filter:brightness(1.035); }\n    input:focus,select:focus,textarea:focus { transform:translateY(-1px); }\n    .login-lang-switch,.setup-lang-switch,.adm-lang-switch,.nexa-public-lang-switch,.nexa-public-lang-btn,\n    #theme-toggle,#setup-theme-btn,.theme-toggle-btn,.svc-theme-btn,.theme-btn,button[onclick*="toggleLoginTheme"] { display:none !important; }\n    @media (prefers-reduced-motion:reduce) { *,*::before,*::after { animation-duration:.01ms !important; animation-iteration-count:1 !important; transition-duration:.01ms !important; scroll-behavior:auto !important; } }\n</style>`;

const NEXA_GLOBAL_ACTIONS_HTML = `<nav class="nav-actions nexa-global-actions nexa-global-floating" id="nexa-global-actions" aria-label="Display settings">\n    <button class="icon-btn" id="nexa-global-theme" type="button" aria-label="Toggle theme" title="Toggle theme"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"></svg></button>\n    <button class="icon-btn lang-btn" id="nexa-global-lang" type="button" aria-label="Language">EN</button>\n</nav>`;

const NEXA_GLOBAL_ACTIONS_SCRIPT = `<script>\n(function(){\n  var root=document.documentElement, actions=document.getElementById('nexa-global-actions');\n  if(!actions) return;\n  var themeBtn=document.getElementById('nexa-global-theme'), langBtn=document.getElementById('nexa-global-lang'), icon=themeBtn&&themeBtn.querySelector('svg');\n  var moon='<path d="M20.2 15.5A8.5 8.5 0 0 1 8.5 3.8 8.6 8.6 0 1 0 20.2 15.5Z"/>', sun='<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>';\n  function syncTheme(){ var dark=root.classList.contains('dark'); root.dataset.theme=dark?'dark':'light'; if(icon) icon.innerHTML=dark?moon:sun; if(themeBtn){themeBtn.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');themeBtn.title=dark?'Light theme':'Dark theme';} }\n  function currentLang(){ try{return localStorage.getItem('nexa-admin-lang')||root.lang||'fa';}catch(e){return root.lang||'fa';} }\n  function syncLang(){ var lang=currentLang()==='en'?'en':'fa'; root.lang=lang;root.dir=lang==='fa'?'rtl':'ltr'; if(langBtn){langBtn.textContent=lang==='fa'?'EN':'FA';langBtn.setAttribute('aria-label',lang==='fa'?'Switch language to English':'تغییر زبان به فارسی');} }\n  var legacyTheme=document.querySelector('#theme-toggle,#setup-theme-btn,.theme-toggle-btn,.svc-theme-btn,.theme-btn,button[onclick*="toggleLoginTheme"]');\n  var host=document.querySelector('.adm-topbar-actions,.svc-header-actions,.st-topbar');\n  if(host){ host.appendChild(actions); actions.classList.remove('nexa-global-floating'); }\n  else { document.body.appendChild(actions); }\n  syncTheme();syncLang();\n  themeBtn.addEventListener('click',function(){\n    if(legacyTheme){legacyTheme.click();setTimeout(syncTheme,0);requestAnimationFrame(syncTheme);}\n    else { var dark=root.classList.toggle('dark'); try{localStorage.setItem('nexa-theme',dark?'dark':'light');localStorage.setItem('color-theme',dark?'dark':'light');localStorage.setItem('nexa-status-theme',dark?'dark':'light');}catch(e){} syncTheme(); }\n  });\n  langBtn.addEventListener('click',function(){\n    var next=currentLang()==='fa'?'en':'fa';\n    if(typeof window.setAdminLang==='function'){window.setAdminLang(next);syncLang();return;}\n    if(typeof window.setLoginLang==='function'){window.setLoginLang(next);syncLang();return;}\n    if(typeof window.setSetupLang==='function'){window.setSetupLang(next);syncLang();return;}\n    if(typeof window.setNexaPublicLang==='function'){window.setNexaPublicLang(next);syncLang();return;}\n    try{localStorage.setItem('nexa-admin-lang',next);}catch(e){}\n    root.lang=next;root.dir=next==='fa'?'rtl':'ltr';syncLang();\n  });\n  new MutationObserver(syncTheme).observe(root,{attributes:true,attributeFilter:['class']});\n})();\n<\/script>`;



const NEXA_GLOBAL_HTML_CACHE = new Map;

function buildEnhancedHtmlResponse(response, html) {
    const headers = new Headers(response.headers);
    headers.delete("Content-Length");
    headers.delete("Content-Encoding");
    headers.delete("ETag");
    headers.delete("Content-MD5");
    return new Response(html, {
        status: response.status,
        statusText: response.statusText,
        headers: headers
    });
}

async function withNexaGlobalPageEnhancements(response, cacheKey) {
    const contentType = response.headers.get("Content-Type") || "";
    if (!/text\/html/i.test(contentType)) return response;
    if (cacheKey && NEXA_GLOBAL_HTML_CACHE.has(cacheKey)) return buildEnhancedHtmlResponse(response, NEXA_GLOBAL_HTML_CACHE.get(cacheKey));
    let html = await response.text();
    if (html.includes('id="nexa-global-actions"')) return response;
    html = html.replace(/<\/head>/i, NEXA_GLOBAL_PRECONNECTS + "\n" + NEXA_GLOBAL_LANG_INIT + "\n" + NEXA_GLOBAL_PAGE_CSS + "\n</head>");
    html = html.replace(/<body\b[^>]*>/i, function(tag) {
        return tag + NEXA_GLOBAL_ACTIONS_HTML;
    });
    html = html.replace(/<\/body>/i, NEXA_GLOBAL_ACTIONS_SCRIPT + "\n</body>");
    if (cacheKey) NEXA_GLOBAL_HTML_CACHE.set(cacheKey, html);
    return buildEnhancedHtmlResponse(response, html);
}

